// Edit freely. Each item: id, s (session 1-13), type mc|two|num, q, opts, a (index) or ans/tol, why, src.
const BANK=[{"id":"s1-02","s":1,"type":"two","term":"Positive vs Normative","q":"“The fare should be lower.”","opts":["Positive","Normative"],"a":1,"why":"A hidden “should” is a value judgment. Normative.","src":"Corridor case (session worked example)"},{"id":"s1-03","s":1,"type":"two","term":"Positive vs Normative","q":"“Raising the fare will reduce ridership.”","opts":["Positive","Normative"],"a":0,"why":"Testable against data. Positive.","src":"Corridor case (session worked example)"},{"id":"s1-07","s":1,"type":"two","term":"PPF","q":"A point inside the PPF curve means the economy is:","opts":["Inefficient","Impossible"],"a":0,"why":"Inside = resources unused. Outside = unattainable.","src":"Corridor case (session worked example)"},{"id":"s1-09","s":1,"type":"num","term":"Opportunity Cost","q":"Tuition is $9,000 and you give up a $14,000 job. Full opportunity cost of attending, in dollars?","ans":23000,"tol":0,"why":"Explicit $9,000 + implicit $14,000 = $23,000.","src":"Corridor case (session worked example)"},{"id":"s2-01","s":2,"type":"two","term":"Shift vs Movement","q":"Gas prices rise, so fewer gallons are bought.","opts":["Movement along","Shift of curve"],"a":0,"why":"Only the good’s own price changed. Movement along demand.","src":"Corridor case (session worked example)"},{"id":"s2-02","s":2,"type":"two","term":"Shift vs Movement","q":"Incomes rise, so more steak is bought at every price.","opts":["Movement along","Shift of curve"],"a":1,"why":"Income is a demand shifter. Whole curve moves.","src":"Corridor case (session worked example)"},{"id":"s2-03","s":2,"type":"two","term":"Shift vs Movement","q":"A new machine cuts production costs for bikes.","opts":["Movement along","Shift of curve"],"a":1,"why":"Technology shifts supply right.","src":"Corridor case (session worked example)"},{"id":"s2-09","s":2,"type":"two","term":"Law of Demand","q":"A table shows quantity demanded rising as price rises. This table:","opts":["Obeys the law","Breaks the law"],"a":1,"why":"Law of demand: price up, quantity demanded down.","src":"Corridor case (session worked example)"},{"id":"s3-01","s":3,"type":"num","term":"Surplus","q":"At $8, sellers offer 500 and buyers want 320. Size of the surplus?","ans":180,"tol":0,"why":"Qs − Qd = 500 − 320 = 180.","src":"Corridor case (session worked example)"},{"id":"s3-02","s":3,"type":"num","term":"Shortage","q":"At $3, buyers want 900 and sellers offer 650. Size of the shortage?","ans":250,"tol":0,"why":"Qd − Qs = 900 − 650 = 250.","src":"Corridor case (session worked example)"},{"id":"s3-03","s":3,"type":"two","term":"Surplus vs Shortage","q":"Price is set above equilibrium. Result:","opts":["Surplus","Shortage"],"a":0,"why":"Too high: sellers offer more than buyers want.","src":"Corridor case (session worked example)"},{"id":"s3-04","s":3,"type":"two","term":"Market Adjustment","q":"There is a shortage. Price will:","opts":["Rise","Fall"],"a":0,"why":"Buyers compete for scarce units and bid price up.","src":"Corridor case (session worked example)"},{"id":"s3-09","s":3,"type":"two","term":"Disequilibrium","q":"A surplus is a form of disequilibrium.","opts":["True","False"],"a":0,"why":"Disequilibrium covers both surplus and shortage.","src":"Corridor case (session worked example)"},{"id":"s4-01","s":4,"type":"num","term":"Midpoint Method","q":"Fare goes from $5.35 to $7.00. Percent change in price by the midpoint method? (whole number)","ans":27,"tol":1,"why":"$1.65 ÷ $6.175 = 26.7%, about 27%. Not 31% (that divides by the start).","src":"Corridor case (session worked example)"},{"id":"s4-02","s":4,"type":"two","term":"Elastic vs Inelastic","q":"Elasticity of 0.68. Demand is:","opts":["Elastic","Inelastic"],"a":1,"why":"Less than 1 = inelastic. The corridor commute.","src":"Corridor case (session worked example)"},{"id":"s4-03","s":4,"type":"two","term":"Elastic vs Inelastic","q":"One brand of cola among many. Demand is likely:","opts":["Elastic","Inelastic"],"a":0,"why":"Many substitutes = elastic.","src":"Corridor case (session worked example)"},{"id":"s4-05","s":4,"type":"num","term":"Total Revenue","q":"Fare $5.35, riders 21,000. Daily total revenue in dollars?","ans":112350,"tol":0,"why":"TR = P × Q = $112,350.","src":"Corridor case (session worked example)"},{"id":"s4-09","s":4,"type":"num","term":"Price Elasticity","q":"Quantity falls 20% when price rises 25%. Elasticity of demand (drop the minus sign, 2 decimals)?","ans":0.8,"tol":0.01,"why":"20 ÷ 25 = 0.80. Inelastic.","src":"Corridor case (session worked example)"},{"id":"s5-01","s":5,"type":"num","term":"Consumer Burden","q":"Original fare $5.35. After a $1.60 tax riders pay $6.10. Consumer burden in dollars?","ans":0.75,"tol":0.01,"why":"$6.10 − $5.35 = $0.75. Subtract from the original price, not from the tax.","src":"Corridor case (session worked example)"},{"id":"s5-02","s":5,"type":"num","term":"Producer Burden","q":"Original fare $5.35, operator now receives $4.50. Producer burden in dollars?","ans":0.85,"tol":0.01,"why":"$5.35 − $4.50 = $0.85. Burdens add to the $1.60 tax.","src":"Corridor case (session worked example)"},{"id":"s5-03","s":5,"type":"two","term":"Burden Rule","q":"Demand is more inelastic than supply. Who bears more of a tax?","opts":["Buyers","Sellers"],"a":0,"why":"The more inelastic side has fewer ways to walk away.","src":"Corridor case (session worked example)"},{"id":"s5-05","s":5,"type":"two","term":"Price Ceiling","q":"A price ceiling set ABOVE equilibrium:","opts":["Causes a shortage","Changes nothing"],"a":1,"why":"Only a ceiling below equilibrium binds.","src":"Corridor case (session worked example)"},{"id":"s5-07","s":5,"type":"num","term":"Tax Revenue","q":"Tax $1.60 per ride. Rides fall from 21,000 to 19,000. Daily tax revenue in dollars?","ans":30400,"tol":0,"why":"$1.60 × 19,000 = $30,400. Use quantity AFTER the tax.","src":"Corridor case (session worked example)"},{"id":"s5-09","s":5,"type":"num","term":"Shortage from Ceiling","q":"At the capped rent, renters want 5,000 units and landlords offer 4,200. Shortage?","ans":800,"tol":0,"why":"5,000 − 4,200 = 800.","src":"Corridor case (session worked example)"},{"id":"s5-10","s":5,"type":"num","term":"Burden Share","q":"Supply elasticity 0.60, demand elasticity 0.68. Buyers’ share of the tax, as a percent (whole number)?","ans":47,"tol":1,"why":"0.60 ÷ 1.28 = 47%.","src":"Corridor case (session worked example)"},{"id":"s6-02","s":6,"type":"two","term":"Price Taker","q":"For a price taker, marginal revenue equals:","opts":["The market price","Less than the price"],"a":0,"why":"Every unit sells at the market price.","src":"Corridor case (session worked example)"},{"id":"s6-03","s":6,"type":"two","term":"Monopoly MR","q":"For a monopolist, marginal revenue is:","opts":["Equal to price","Below price"],"a":1,"why":"Selling one more means cutting price on every unit.","src":"Corridor case (session worked example)"},{"id":"s6-04","s":6,"type":"num","term":"Economic Cost","q":"Bakery bills $8,000 a month; owner gave up a $3,000 job. Economic cost in dollars?","ans":11000,"tol":0,"why":"Accounting cost + opportunity cost = $11,000.","src":"Corridor case (session worked example)"},{"id":"s6-08","s":6,"type":"num","term":"DWL of Monopoly","q":"Competition: 80 rides at $20. Monopoly: 40 rides at $60. Deadweight loss in dollars?","ans":800,"tol":0,"why":"½ × 40 × $40 = $800.","src":"Corridor case (session worked example)"},{"id":"dd1-01","s":1,"type":"mc","src":"DemiDec SE1 Q1 RG p.6","term":"Scarcity","q":"Scarcity forces every economy to consider how to","opts":["endlessly expand production","cope with irrational actors","allocate limited resources","constrain producers’ greed"],"a":2,"why":"Because wants exceed available resources, every economy must decide how to use its limited labor, capital, and time. Growth eases that pressure but never erases the choice."},{"id":"dd1-02","s":1,"type":"mc","src":"DemiDec SE1 Q2 RG p.7","term":"Opportunity Cost","q":"A worker leaves a salaried job to run a bakery full-time. Which item is part of their opportunity cost?","opts":["the salary forgone by leaving the old job","principal repaid on an equipment loan","the sales tax the bakery collects","interest still earned on untouched savings"],"a":0,"why":"Opportunity cost is the value of the best alternative given up, so the salary the owner could be earning elsewhere counts even though no check is written for it. Collected taxes, untouched interest, and repaid principal are not what this choice sacrifices."},{"id":"dd1-03","s":1,"type":"mc","src":"DemiDec SE1 Q3 RG p.7","term":"Implicit Cost","q":"Why can the opportunity cost of an activity exceed the amount of money it requires?","opts":["it adds sales tax left out of the cash price","it counts forgone options like time, not paid in cash","it rises with inflation while cash prices stay fixed","it measures only hours and ignores money"],"a":1,"why":"Opportunity cost includes everything sacrificed, like time that could have earned income, so it can exceed the cash outlay even though that lost value never shows up on a receipt."},{"id":"dd1-04","s":1,"type":"mc","src":"DemiDec SE1 Q4 RG p.6","term":"Invisible Hand","q":"In Adam Smith’s famous example, what leads the butcher and the baker to provide our dinner?","opts":["self-interest","charity","careful planning","custom"],"a":0,"why":"Smith’s point is that self-interested producers, not benevolence, planning, or tradition, reliably supply goods, because each gains by serving others through trade."},{"id":"dd1-05","s":1,"type":"mc","src":"DemiDec SE1 Q5 RG p.8","term":"Positive vs Normative","q":"Which statement belongs to normative rather than positive economics?","opts":["The government ought to raise the minimum wage.","A higher minimum wage would raise the earnings of workers who keep their jobs.","Firms facing higher wage costs would raise their prices.","Raising the minimum wage would cut the number of low-wage jobs."],"a":0,"why":"A normative statement says what ought to be and rests on a value judgment. The other three are testable predictions about what would happen, the work of positive economics."},{"id":"dd1-06","s":1,"type":"mc","src":"DemiDec SE1 Q6 RG p.8","term":"Pareto Efficiency","q":"An allocation can still be Pareto efficient even when which of the following is true?","opts":["workers and machines sit idle","someone could be made better off at no one’s expense","income is distributed very unequally","some output is produced but then wasted"],"a":2,"why":"Pareto efficiency only rules out changes that help someone without hurting anyone, so it says nothing about fairness. A highly unequal allocation can be efficient as long as no costless improvement remains."},{"id":"dd1-07","s":1,"type":"mc","src":"DemiDec SE1 Q7 RG p.7","term":"Economic Models","q":"Why do economists treat a model’s simplicity as a strength rather than a flaw?","opts":["leaving out detail makes the key forces easier to see","fewer assumptions let economists skip testing against data","a simpler model predicts more accurately than a detailed one","a simpler model is a more realistic picture of the economy"],"a":0,"why":"A model strips away detail so the essential relationships stand out. Its simplicity aids understanding, not realism or prediction, and never removes the need to test it against evidence."},{"id":"dd1-08","s":1,"type":"mc","src":"DemiDec SE1 Q8 RG p.9","term":"Micro vs Macro","q":"Which question is a microeconomic rather than a macroeconomic one?","opts":["How does a firm set the price of its product?","What determines the growth rate of total output?","What pushes the unemployment rate up in a recession?","Why does the overall price level rise over time?"],"a":0,"why":"Microeconomics studies individual decision-makers and single markets, so one firm’s pricing is micro. The overall price level, unemployment, and total output are economy-wide, macroeconomic questions."},{"id":"dd1-09","s":2,"type":"mc","src":"DemiDec SE1 Q9 RG p.10","term":"Market","q":"Why are the scattered buyers and sellers of gasoline in a town still a single market?","opts":["They trade the same good at commonly known prices.","A government office establishes regulations around the sale of the good.","Each station sells a different brand to separate buyers.","One station sets the price all others must charge."],"a":0,"why":"A market is all the buyers and sellers trading a good, however they interact, so scattered stations and drivers dealing at known prices form one market with no central place, price-setter, or official oversight."},{"id":"dd1-10","s":2,"type":"mc","src":"DemiDec SE1 Q10 RG p.10; 11","term":"Perfect Competition","q":"In a perfectly competitive market, why does a seller who prices above the going rate lose nearly all buyers?","opts":["A single dominant buyer dictates the price.","Sellers have agreed to match prices.","The good is identical and prices are known.","Buyers are legally barred from paying more."],"a":2,"why":"With many sellers offering an identical product to well-informed buyers, anyone charging more is instantly undercut, so each seller must take the market price. This follows from competition, not regulation, a dominant buyer, or collusion."},{"id":"dd1-11","s":2,"type":"mc","src":"DemiDec SE1 Q11 RG p.11","term":"Perfect Competition","q":"A market moves closer to perfect competition when the product is","opts":["offered by only a few firms","supplied mostly by one dominant firm","sold at prices buyers cannot observe","standardized and sold by many sellers"],"a":3,"why":"Perfect competition requires a standardized good, many participants, and good information, so a uniform product sold by many sellers approaches the ideal. Dominance, hidden prices, or few firms move a market away from it."},{"id":"dd1-12","s":2,"type":"mc","src":"DemiDec SE1 Q12 RG p.11; 13","term":"Law of Demand","q":"Holding everything else constant, a rise in a good’s own price will","opts":["raise demand as the good seems more valuable","lower the quantity demanded along the curve","shift the demand curve right","shift the entire demand curve left"],"a":1,"why":"The law of demand says a higher own-price lowers quantity demanded. Because only the good’s own price changed, buyers slide along a fixed demand curve rather than shifting it."},{"id":"dd1-13","s":2,"type":"mc","src":"DemiDec SE1 Q13 RG p.13","term":"Shift vs Movement","q":"Which change shifts the entire demand curve rather than causing a movement along it?","opts":["a rise in the good’s own price","a rise in consumers’ incomes","an increase in the quantity sellers supply","the market moving toward equilibrium"],"a":1,"why":"Only a non-price factor like income shifts the whole demand curve. A change in the good’s own price, in quantity supplied, or movement toward equilibrium all slide along curves rather than shifting demand."},{"id":"dd1-14","s":2,"type":"mc","src":"DemiDec SE1 Q14 RG p.12","term":"Market Demand","q":"At a price of $4, Steve will buy 35 gallons and Nora will buy 8 gallons. If they are the only buyers, what is the market quantity demanded at $4?","opts":["35 gallons","21.5 gallons","27 gallons","43 gallons"],"a":3,"why":"Market demand at a price sums every buyer’s quantity, so 35 plus 8 gives 43 gallons. Subtracting, averaging, or taking only the larger buyer all misread how individual demands combine."},{"id":"dd1-15","s":2,"type":"mc","src":"DemiDec SE1 Q15 RG p.13","term":"Inferior Good","q":"As household income rises, which type of good will people buy less of?","opts":["store-brand cereal","bakery bread","restaurant meals","air travel"],"a":0,"why":"People buy less of an inferior good as income rises. Cheap staples like store-brand cereal get traded up for pricier substitutes, while restaurant meals, air travel, and bakery bread rise with income."},{"id":"dd1-16","s":2,"type":"mc","src":"DemiDec SE1 Q16 RG p.13","term":"Substitutes","q":"When the price of coffee falls, the quantity of tea demanded also falls. This relationship identifies coffee and tea as","opts":["substitutes","complements","unrelated goods","two inferior goods"],"a":0,"why":"Substitutes meet the same need, so cheaper coffee draws buyers away from tea. Complements would raise tea demand instead, and inferior or unrelated goods would not produce this cross-price reaction."},{"id":"dd1-17","s":2,"type":"mc","src":"DemiDec SE1 Q17 RG p.14","term":"Complements","q":"Which pair of goods are complements?","opts":["tennis rackets and tennis balls","butter and margarine","tea and coffee","bus tickets and subway tickets"],"a":0,"why":"Complements are used together, so a lower price for one raises demand for the other. Rackets and balls go together; the other pairs are substitutes buyers choose between."},{"id":"dd1-18","s":2,"type":"mc","src":"DemiDec SE1 Q18 RG p.14","term":"Buyer Expectations","q":"Consumers come to expect that coffee will cost more next month. What happens to their demand for coffee today?","opts":["It increases as buyers stock up before the rise.","It falls as shoppers save for the higher price.","It falls as buyers wait for low prices to return.","It increases as buyers move along the demand curve."],"a":0,"why":"Expectations shape current choices, so anticipating a higher future price leads buyers to purchase more now, raising today’s demand before the increase arrives."},{"id":"dd1-19","s":2,"type":"mc","src":"DemiDec SE1 Q19 RG p.14; 15","term":"Law of Supply","q":"A higher price that sellers can obtain for a good leads them to","opts":["supply the same amount at a higher margin","increase the quantity they supply","cut output to keep the price high","lower quality instead of raising quantity"],"a":1,"why":"Sellers weigh price against the rising cost of making more, so a higher price makes extra output worthwhile and quantity supplied rises rather than being held back."},{"id":"dd1-20","s":2,"type":"mc","src":"DemiDec SE1 Q20 RG p.15","term":"Shift vs Movement","q":"Which change moves a seller along a fixed supply curve rather than shifting the curve?","opts":["a change in the good’s own price","an improvement in production technology","a change in workers’ wages","a change in the number of firms"],"a":0,"why":"Only a change in the good’s own price moves quantity supplied along an unchanged curve. Wages, technology, and the number of firms are non-price factors that shift the whole curve."},{"id":"dd1-21","s":2,"type":"mc","src":"DemiDec SE1 Q21 RG p.15","term":"Input Prices","q":"A bakery’s wage bill rises sharply. What happens to the supply of bread?","opts":["supply falls, shifting the curve left","demand for bread falls as wages rise","supply is unchanged, since wages aren’t an input cost","the bakery moves up its curve to a larger quantity"],"a":0,"why":"Wages are an input cost, so a higher wage bill raises the cost of each loaf and the bakery offers less at every price, shifting the supply curve left rather than moving along it or shifting demand."},{"id":"dd1-22","s":2,"type":"mc","src":"DemiDec SE1 Q22 RG p.15","term":"Technology & Supply","q":"A bakery installs a new oven that lowers its baking costs. What is the MOST likely effect on its supply of bread?","opts":["supply rises, shifting the curve right","demand rises while supply stays put","the bakery moves along its curve without it shifting","supply falls, shifting the curve left"],"a":0,"why":"Cheaper baking lowers the cost of each loaf, so the bakery supplies more at every price and the curve shifts right. That is a shift in supply, not a movement along it or a change in demand."},{"id":"dd1-23","s":2,"type":"mc","src":"DemiDec SE1 Q23 RG p.15","term":"Seller Expectations","q":"A juice maker expects orange prices to jump after a frost ruins the coming harvest. How is it MOST likely to adjust today’s supply?","opts":["hold inventory back to sell after prices rise","sell as much as possible before prices change","expand production to build extra inventory","leave today’s supply unchanged"],"a":0,"why":"When sellers expect higher prices ahead, holding goods to sell later is more profitable, so they cut today’s supply by storing inventory rather than dumping it now or making more."},{"id":"dd1-24","s":2,"type":"mc","src":"DemiDec SE1 Q24 RG p.15; 18","term":"Equilibrium","q":"A competitive market is in equilibrium at the price where","opts":["sellers take in the most total revenue","sellers offer more than buyers will buy","buyers want more than sellers will provide","quantity demanded equals quantity supplied"],"a":3,"why":"Equilibrium is the market-clearing price where quantity demanded equals quantity supplied and neither side wants to change. Excess demand, excess supply, or the revenue-maximizing price are not equilibrium."},{"id":"dd1-25","s":3,"type":"mc","src":"DemiDec SE1 Q25 RG p.18","term":"Surplus vs Shortage","q":"If the price in a competitive market is held above equilibrium, what results?","opts":["no change, since the market simply trades at the higher price","a surplus, as quantity supplied exceeds quantity demanded","a shortage, as quantity demanded exceeds quantity supplied","an immediate jump in demand that absorbs the extra output"],"a":1,"why":"Above equilibrium, sellers offer more than buyers want, so the gap shows up as an unsold surplus that pushes the price back down, not a shortage, a demand surge, or a stable new price."},{"id":"dd1-26","s":3,"type":"mc","src":"DemiDec SE1 Q26 RG p.19; 20","term":"Shortage","q":"A price held below equilibrium produces a shortage, which shows up as","opts":["buyers lining up for too few units","sellers watching unsold goods pile up","the price climbing until the shortage clears","sellers restocking shelves to meet the rush"],"a":0,"why":"Below equilibrium, buyers want more than sellers supply, so excess demand shows up as bare shelves and queues. Piled-up inventory is a surplus symptom, and the held-down price neither rises to clear the gap nor draws out extra supply to end the shortage."},{"id":"dd1-27","s":3,"type":"mc","src":"DemiDec SE1 Q27 RG p.18","term":"Market Adjustment","q":"How does a competitive market clear a surplus without any outside intervention?","opts":["Buyers voluntarily pay the high price for the extra units.","The government buys the unsold units.","Sellers destroy the extra units to keep prices high.","Sellers cut the price until the surplus disappears."],"a":3,"why":"Facing unsold goods, each seller undercuts rivals, driving the price down until quantity demanded again equals quantity supplied. Overpaying, government buying, or destroying output are not how competition clears a surplus."},{"id":"dd1-28","s":3,"type":"mc","src":"DemiDec SE1 Q28 RG p.20","term":"Consumer Surplus","q":"Consumer surplus is the gap between","opts":["the price a seller receives and the seller’s cost","quantity demanded and quantity supplied at equilibrium","the highest and lowest prices ever paid","the most a buyer will pay and the price paid"],"a":3,"why":"Consumer surplus is the extra value buyers capture when the price sits below the most they would have paid. The seller-side gap is producer surplus; price ranges and quantity gaps are something else."},{"id":"dd1-29","s":3,"type":"mc","src":"DemiDec SE1 Q29 RG p.20","term":"Producer Surplus","q":"A seller earns producer surplus whenever","opts":["price sits above the seller’s lowest price","revenue covers all the seller’s costs","a binding price ceiling caps the price","price equals the most the buyer will pay"],"a":0,"why":"Producer surplus is the gap between the price received and the seller’s lowest acceptable price, so it arises whenever price tops that floor, no matter whether all costs are covered, what the buyer would pay, or any price control."},{"id":"dd1-30","s":3,"type":"mc","src":"DemiDec SE1 Q30 RG p.20","term":"Willingness to Pay","q":"At a given quantity, the height of the demand curve shows the","opts":["consumer surplus on that unit","marginal seller’s cost of that unit","total revenue at that quantity","most the marginal buyer will pay"],"a":3,"why":"The demand curve ranks buyers by willingness to pay, so its height at a quantity is the marginal buyer’s valuation of that unit. The seller’s cost is read off the supply curve, revenue is an area, and consumer surplus is the gap down to price, not the height itself."},{"id":"dd1-31","s":3,"type":"mc","src":"DemiDec SE1 Q31 RG p.22","term":"Total Surplus","q":"Total surplus is largest at the competitive equilibrium quantity, which means that at that quantity","opts":["gains from trade are split equally between buyers and sellers","no trade could help anyone without hurting someone else","the government’s tax revenue is at its maximum","consumer surplus exceeds producer surplus"],"a":1,"why":"Maximizing total surplus is exactly Pareto efficiency, so at the equilibrium quantity no one can gain without someone else losing. It says nothing about an equal split, which side gains more, or tax revenue."},{"id":"dd1-32","s":3,"type":"mc","src":"DemiDec SE1 Q32 RG p.22","term":"Efficiency of Equilibrium","q":"Why is any quantity below the competitive equilibrium inefficient?","opts":["Sellers value extra units more than buyers will pay.","Buyers value extra units more than sellers’ cost.","Total surplus is already as large as possible.","The good sells for less than it costs to produce."],"a":1,"why":"Below equilibrium the demand curve lies above the supply curve, so each extra unit is worth more to buyers than it costs sellers. Leaving those gains untaken wastes surplus, so output below equilibrium is inefficient."},{"id":"dd1-33","s":3,"type":"mc","src":"DemiDec SE1 Q33 RG p.23; 25","term":"Supply Shift Effects","q":"New technology lets dairy farmers produce milk at lower cost. What does the competitive model predict?","opts":["an unchanged price and lower quantity","a lower price and higher quantity","a higher price and lower quantity","a higher price and higher quantity"],"a":1,"why":"Cheaper production shifts the milk supply curve right, so the market slides down the demand curve to a lower price and higher quantity. The other combinations describe a supply decrease or a demand change."},{"id":"dd1-34","s":4,"type":"mc","src":"DemiDec SE1 Q34 RG p.25","term":"Total Revenue","q":"Cost-saving technology spreads through a competitive farm sector whose product has inelastic demand. What happens to farmers’ total revenue?","opts":["It rises, since lower costs raise revenue.","It falls, as price drops proportionally more than quantity rises.","It rises, since selling more always brings more money.","It stays the same, as the larger quantity offsets the lower price."],"a":1,"why":"With inelastic demand the price falls by a larger percentage than quantity rises, so the lower price dominates and total revenue declines. This is the paradox in which bumper harvests can leave farmers worse off."},{"id":"dd1-35","s":4,"type":"mc","src":"DemiDec SE1 Q35 RG p.25","term":"Demand Shift Effects","q":"With supply unchanged, an anti-fast-food campaign reduces consumers’ desire for fast food. The new equilibrium shows","opts":["a higher price and a higher quantity","a lower price but a higher quantity","a higher price and a lower quantity","a lower price and a lower quantity"],"a":3,"why":"The campaign shifts the fast-food demand curve left, so the market slides down the unchanged supply curve to a lower price and lower quantity. A higher price would take a leftward supply shift instead, which this campaign does not cause."},{"id":"dd1-36","s":4,"type":"mc","src":"DemiDec SE1 Q36 RG p.25; 26","term":"Elasticity vs Slope","q":"One advantage of price elasticity of demand over the slope of the demand curve is that elasticity","opts":["is the same at every point on a straight-line demand curve","equals price times quantity sold","does not depend on the units of measure","can be read off the vertical axis"],"a":2,"why":"Because elasticity uses percentage changes, it comes out the same whether quantity is in gallons or liters, unlike slope. It is not revenue, an axis reading, or constant along a linear demand curve."},{"id":"dd1-37","s":4,"type":"mc","src":"DemiDec SE1 Q37 RG p.25; 26","term":"Substitutes & Elasticity","q":"Which good would tend to have the MOST elastic demand?","opts":["gasoline","table salt","soda","insulin"],"a":2,"why":"Demand is most elastic when close substitutes are easy to find, so a cola brand buyers can swap for a rival is far more elastic than a necessity with few substitutes like insulin, commuting fuel, or salt."},{"id":"dd1-38","s":4,"type":"mc","src":"DemiDec SE1 Q38 RG p.25","term":"Necessities vs Luxuries","q":"Compared with the demand for a luxury cruise, the demand for a basic necessity tends to be","opts":["more elastic","equally elastic","perfectly inelastic","less elastic"],"a":3,"why":"Necessities are hard to do without, so buyers keep buying even as prices rise, making their demand less elastic than that for luxuries people can skip. It is a matter of degree, not perfect inelasticity or a uniform response."},{"id":"dd1-39","s":4,"type":"mc","src":"DemiDec SE1 Q39 RG p.26","term":"Time Horizon","q":"Why does the demand for gasoline grow more elastic over a longer time horizon?","opts":["Gasoline prices fall as time passes.","Gasoline gains fewer substitutes over time.","Buyers respond more sharply in the short run.","Given time, drivers buy fuel-efficient cars."],"a":3,"why":"In the short run drivers can do little but pay more. Over time they switch to efficient vehicles or shorten commutes, so quantity demanded responds more strongly to price. Substitution grows with time, not shrinks."},{"id":"dd1-40","s":4,"type":"mc","src":"DemiDec SE1 Q40 RG p.26","term":"Perfectly Inelastic","q":"The supply of original paintings by a long-dead artist is perfectly inelastic, which means the quantity supplied","opts":["stays fixed as the price climbs","decreases as the price climbs","increases sharply as the price climbs","rises slowly as the price climbs"],"a":0,"why":"No new works by a dead artist can be made, so the quantity is fixed and unresponsive to price, the defining feature of perfectly inelastic supply. Any response to price would make supply at least somewhat elastic."},{"id":"dd1-41","s":4,"type":"mc","src":"DemiDec SE1 Q41 RG p.26; 29","term":"Total Revenue","q":"If a good has inelastic demand, a fall in its price will cause total revenue to","opts":["fall, as quantity rises proportionally less than price falls","rise, as the lower price draws proportionally more buyers","rise, since a lower price sells more units","stay unchanged, as price and quantity effects cancel"],"a":0,"why":"With inelastic demand, quantity rises by a smaller percentage than the price drops, so the price effect dominates and total revenue falls. The extra units sold never outweigh the revenue lost on each one."},{"id":"dd1-42","s":5,"type":"mc","src":"DemiDec SE1 Q42 RG p.33","term":"Price Floor Surplus","q":"A government sets a wheat price floor above the market equilibrium. The MOST direct result is that","opts":["wheat production drops below equilibrium","buyers want more wheat than farmers will grow","farmers grow more wheat than buyers want","the price falls until all wheat is sold"],"a":2,"why":"A binding floor sits above the market-clearing price, spurring extra production while discouraging purchases, so farmers are left with unsold wheat. The price cannot fall to clear it, and output rises rather than falls."},{"id":"dd1-43","s":5,"type":"mc","src":"DemiDec SE1 Q43 RG p.32","term":"Price Ceiling Effects","q":"Over the long run, why does a rent ceiling tend to make a housing shortage worse?","opts":["The ceiling rises each year with the cost of living.","Developers rush to build to capture demand.","Renters leave the city for higher rents elsewhere.","Landlords cut upkeep and withdraw units over time."],"a":3,"why":"Given time, capped rents lead owners to neglect or pull units while drawing in more would-be tenants, so the gap between apartments wanted and apartments offered widens rather than closes."},{"id":"dd1-44","s":5,"type":"mc","src":"DemiDec SE1 Q44 RG p.32","term":"Rent Control","q":"Apart from shrinking the number of apartments, why does rent control allocate housing inefficiently?","opts":["Landlords must rent only to the longest-waiting tenants.","Units no longer go to the renters who value them most.","Apartments are auctioned to the highest bidder.","Rents climb until only the wealthy can afford them."],"a":1,"why":"Once a capped price can no longer ration scarce apartments, landlords pick tenants by personal preference or side payments, so units stop going to those who value them most. An auction, rising rents, or a waiting-list mandate are not what rent control produces."},{"id":"dd1-45","s":5,"type":"mc","src":"DemiDec SE1 Q45 RG p.33","term":"Tax Wedge","q":"A per-unit tax can be pictured as a wedge equal to the gap between the","opts":["highest and lowest prices found in the market","consumer surplus and producer surplus","quantity demanded and the quantity supplied","price buyers pay and the price sellers receive"],"a":3,"why":"The tax separates the buyer’s price from the seller’s price by exactly the tax amount, so that price gap is the wedge that shrinks the quantity traded. It is not a quantity gap, a price range, or a comparison of surpluses."},{"id":"dd1-46","s":5,"type":"mc","src":"DemiDec SE1 Q46 RG p.34","term":"Deadweight Loss","q":"What BEST describes the deadweight loss caused by a tax?","opts":["the consumer surplus buyers keep after the tax","the part of the tax passed to buyers","the revenue the government collects","the value of beneficial trades the tax prevents"],"a":3,"why":"By driving the buyer’s price above the seller’s, a tax blocks trades that would have helped both sides, and the surplus lost on those forgone exchanges is the deadweight loss. Tax revenue, pass-through, and remaining surplus are not losses."},{"id":"dd1-47","s":3,"type":"mc","src":"DemiDec SE1 Q47 RG p.23","term":"Double Shift","q":"When both demand and supply for a good increase at the same time, the equilibrium quantity will","opts":["move in an unpredictable direction","stay fixed while the price clearly rises","rise, while the change in price is uncertain","fall, as larger supply drives price and quantity down"],"a":2,"why":"Both a rightward demand shift and a rightward supply shift raise the quantity traded, so quantity clearly rises. Because the shifts push price in opposite directions, the price change depends on their relative size."},{"id":"dd1-48","s":3,"type":"mc","src":"DemiDec SE1 Q48 RG p.20; 21","term":"Consumer Surplus","q":"Four buyers value a concert ticket at $90, $70, $60, and $40. If the ticket price is $60, what is the total consumer surplus?","opts":["$30","$40","$20","$160"],"a":1,"why":"The $90 buyer gains $30 and the $70 buyer gains $10; the $60 buyer breaks even and the $40 buyer does not buy, so consumer surplus totals $40. Counting one buyer, including those who would not purchase, or forgetting to subtract the price all give wrong totals."},{"id":"dd1-49","s":3,"type":"mc","src":"DemiDec SE1 Q49 RG p.20","term":"Marginal Cost","q":"At a given quantity, the height of the supply curve shows the marginal seller’s","opts":["profit margin on that unit","total revenue earned from that unit","willingness to pay for that unit","opportunity cost of that unit"],"a":3,"why":"The supply curve ranks sellers by cost, so its height at a quantity is the marginal seller’s opportunity cost, the price below which that seller would quit. It is not a buyer’s valuation, total revenue, or a profit margin."},{"id":"dd1-50","s":5,"type":"mc","src":"DemiDec SE1 Q50 RG p.34","term":"Deadweight Loss","q":"Why does a tax on a good with very inelastic supply and demand create only a small deadweight loss?","opts":["the tax raises little revenue","sellers bear almost the entire burden","the tax barely cuts the quantity traded","the buyer-seller price wedge disappears"],"a":2,"why":"Deadweight loss comes from trades a tax prevents, so when buyers and sellers respond little to price, quantity falls only slightly and few beneficial trades are lost. The small loss has nothing to do with revenue, incidence, or any vanishing wedge."},{"id":"dd2-01","s":13,"type":"mc","src":"DemiDec SE2 Q1 RG p.36","term":"Opportunity Cost","q":"Maya can bake twenty-four loaves of bread or brew eight jugs of cider in a day. What is her opportunity cost of baking one loaf?","opts":["one jug of cider","three jugs of cider","one-third of a jug of cider","eight jugs of cider"],"a":2,"why":"Maya gives up eight jugs of cider to bake twenty-four loaves of bread, so each loaf costs her eight divided by twenty-four, or one-third of a jug of cider."},{"id":"dd2-02","s":13,"type":"mc","src":"DemiDec SE2 Q2 RG p.36","term":"Comparative Advantage","q":"Priya can out-produce Diego in both coding apps and tutoring sessions, yet both end up better off when she specializes in coding apps and he specializes in tutoring sessions. The idea that explains this result is","opts":["diminishing returns","comparative advantage","economies of scale","absolute advantage"],"a":1,"why":"What drives the gains from trade is not who is more productive overall but who gives up less to make a good, so Diego's lower opportunity cost in tutoring sessions hands him the comparative advantage despite Priya's edge in both."},{"id":"dd2-03","s":13,"type":"mc","src":"DemiDec SE2 Q3 RG p.40","term":"Opening to Trade","q":"A country whose domestic price sits above the world price lifts its ban on trade. What happens in that market?","opts":["The domestic price falls, and the country imports the shortfall in its own output.","The domestic price rises, and domestic consumers cut back their purchases.","The domestic price rises, and the country exports its surplus output.","The domestic price falls, and domestic producers expand their output."],"a":0,"why":"When the world price is below the domestic price, opening trade pulls the home price down to the world level, so consumers buy more, domestic producers supply less, and imports fill the gap."},{"id":"dd2-04","s":13,"type":"mc","src":"DemiDec SE2 Q4 RG p.40","term":"Concentrated Losses","q":"Free trade raises a nation's total surplus, so why does organized opposition to it so often arise?","opts":["Free trade lowers a nation's total income even as it raises output.","Free trade mainly helps foreign producers, not domestic consumers.","The gains from trade are usually too small to notice.","The industries that shrink under trade concentrate real losses on identifiable workers and firms."],"a":3,"why":"Trade grows the overall pie but reshuffles which industries thrive, so even though the winners gain more than the losers lose, the people in shrinking industries feel concentrated losses and push back."},{"id":"dd2-05","s":13,"type":"mc","src":"DemiDec SE2 Q5 RG p.40","term":"Small-Country Assumption","q":"Economists analyzing a small country's entry into world trade assume its added output leaves the world price unchanged because","opts":["the world price is set by international agreement","the country is tiny relative to the world market","its exporters coordinate to hold the price steady","its currency is pegged to a global standard"],"a":1,"why":"The small-country case assumes the nation supplies so little to the world market that its extra exports cannot move the world price, so it takes that price as given."},{"id":"dd2-06","s":13,"type":"mc","src":"DemiDec SE2 Q6 RG p.36","term":"Gains from Specialization","q":"Before trading, Aisha and Marco together produce thirty-three blankets and twenty-one candles. After each shifts toward the good he or she gives up less to produce, their combined output becomes thirty-three blankets and twenty-seven candles. What does this outcome show?","opts":["Gains from trade require each party to make every good.","Specialization expands total production.","Trade helps only the party with an absolute advantage.","Specialization helps one party at the other's expense."],"a":1,"why":"With the same hours and no new resources, specializing where each has the lower opportunity cost yields six more candles and no fewer blankets, so the gains come purely from reallocating effort."},{"id":"dd2-07","s":13,"type":"mc","src":"DemiDec SE2 Q7 RG p.36","term":"Source of Gains from Trade","q":"Two countries can both gain from trading with each other as long as","opts":["neither imposes a tariff on the other","they produce the two goods at identical costs","their opportunity costs of producing the goods differ","one of them can produce both goods more cheaply"],"a":2,"why":"Gains from trade come from differences in opportunity cost, so as long as the two sacrifice different amounts to make a good, each can specialize where it gives up less and both end up ahead."},{"id":"dd2-08","s":6,"type":"mc","src":"DemiDec SE2 Q8 RG p.40","term":"Economic Cost","q":"Why can a firm's economic costs exceed its accounting costs?","opts":["Accounting costs add taxes that economic costs leave out.","Economic costs ignore the wages paid to hired workers.","Economic costs add the opportunity cost of resources the owner already owns.","Economic costs add the sunk costs that accountants have already written off."],"a":2,"why":"Accounting costs track money actually paid out, while economic costs also count what the owner gives up by using his own time and capital here instead of elsewhere, so the economic figure is larger."},{"id":"dd2-09","s":6,"type":"mc","src":"DemiDec SE2 Q9 RG p.43","term":"Price as a Signal","q":"Besides rationing scarce goods among buyers, the second job prices perform in a competitive market is to","opts":["guarantee every firm an equal share of industry profit","steer labor and capital toward the activities that earn the highest returns","keep accounting and economic profit equal for every firm","hold each firm's output fixed regardless of demand"],"a":1,"why":"Positive economic profit in an activity signals that buyers value its output highly, which draws resources into that activity, so prices allocate inputs as well as ration goods."},{"id":"dd2-10","s":6,"type":"mc","src":"DemiDec SE2 Q10 RG p.","term":"Zero Economic Profit","q":"In a competitive long-run equilibrium, firms earn zero economic profit, yet their owners willingly stay in business. Why?","opts":["Zero economic profit means revenue exactly covers their explicit costs.","Zero economic profit means they are still earning their best alternative income.","Zero economic profit still leaves a large accounting loss they tolerate.","Zero economic profit means their accounting profit has also fallen to zero."],"a":1,"why":"Economic profit already subtracts the owner's opportunity cost, so earning zero means the owner makes exactly what the next-best use of time and money would pay, which is reason enough to stay."},{"id":"dd2-11","s":6,"type":"mc","src":"DemiDec SE2 Q11 RG p.42","term":"Diminishing Returns","q":"Bob runs a bakery that bakes and sells bread. Why do his marginal costs rise as he bakes more loaves in the short run?","opts":["The market price of bread falls as Bob produces more.","Each added worker must be paid a higher hourly wage than the last.","Bob's fixed costs increase with every additional loaf he bakes.","With the ovens fixed, each added worker crowds the same equipment and adds less output."],"a":3,"why":"Because the ovens cannot be expanded in the short run, extra workers add less and less output, so the cost of each additional loaf climbs, an example of diminishing returns."},{"id":"dd2-12","s":6,"type":"mc","src":"DemiDec SE2 Q12 RG p.42","term":"Price Taker","q":"Lena sells coffee in a perfectly competitive market at four dollars a cup. $4.00 is her","opts":["marginal profit","average total cost","marginal revenue","marginal cost"],"a":2,"why":"A competitive firm is too small to move the price, so Lena sells each extra cup at the going four dollars, making her marginal revenue equal to the market price no matter how many she sells."},{"id":"dd2-13","s":6,"type":"mc","src":"DemiDec SE2 Q13 RG p.42","term":"Marginal Cost","q":"Lena sells coffee in a perfectly competitive market. Her marginal cost of brewing one more cup is BEST understood as the","opts":["opportunity cost of the resources used to make that cup","price she must charge to break even on that cup","average of her fixed and variable costs","total revenue she earns from that cup"],"a":0,"why":"Marginal cost measures what Lena must give up in added resources to brew one more cup, so it is the opportunity cost of that single unit, not an average over all her output."},{"id":"dd2-14","s":6,"type":"mc","src":"DemiDec SE2 Q14 RG p.45","term":"Monopoly MR","q":"Because a cable monopolist must cut the price for all its subscribers to attract more of them, its marginal revenue is","opts":["greater than the price of a subscription","zero at every level of output","equal to the price of a subscription","less than the price of a subscription"],"a":3,"why":"To sell one more subscription the monopolist lowers the price for everyone, so the revenue from the extra customer is partly offset by the smaller amount collected from existing ones, leaving marginal revenue below the price."},{"id":"dd2-15","s":6,"type":"mc","src":"DemiDec SE2 Q15 RG p.44","term":"Natural Monopoly","q":"An industry is called a natural monopoly when","opts":["the government grants one firm the exclusive right to produce","a few large firms secretly agree to act as one","a single firm owns the only source of a key input","one firm can supply the whole market more cheaply than several firms could"],"a":3,"why":"A natural monopoly exists when large fixed costs let one firm serve the entire market at lower cost than rivals could, as with railroads, pipelines, and cable systems."},{"id":"dd2-16","s":6,"type":"mc","src":"DemiDec SE2 Q16 RG p.43","term":"Key Resource Monopoly","q":"De Beers long controlled the world's diamond supply by owning the mines where most diamonds are found. Which source of monopoly power does this fact illustrate?","opts":["a merger approved by antitrust regulators","a government-granted patent","ownership of a key resource","a natural monopoly from high fixed costs"],"a":2,"why":"Holding the mines that produce most of the world's diamonds lets De Beers shut out rivals, a monopoly built on owning a scarce resource rather than on a government grant or a cost advantage."},{"id":"dd2-17","s":6,"type":"mc","src":"DemiDec SE2 Q17 RG p.45","term":"DWL of Monopoly","q":"Economists name two effects of monopoly on social welfare. One is a transfer of surplus from consumers to the firm. What is the other?","opts":["lower product quality because the firm faces no pressure from competitors","a transfer of surplus from the firm to the government through taxes on its profit","a transfer of surplus from the firm back to its workers","a loss of welfare because output is held below the competitive level"],"a":3,"why":"Beyond shifting surplus from subscribers to the company, the monopoly restricts output below the competitive quantity, so units worth more than they cost go unmade, and that lost surplus is a cost to society."},{"id":"dd2-18","s":6,"type":"mc","src":"DemiDec SE2 Q18 RG p.45","term":"Antitrust","q":"What goal did regulators pursue when they broke up AT&T in 1984 and forced Microsoft to unbundle its web browser from Windows?","opts":["raising government tax revenue","setting reasonable prices","keeping markets competitive","guaranteeing a fair consumer experience"],"a":2,"why":"Both actions used antitrust law to stop a dominant firm from shutting out rivals, the same aim behind the Sherman Anti-Trust Act's effort to preserve competition."},{"id":"dd2-19","s":6,"type":"mc","src":"DemiDec SE2 Q19 RG p.45","term":"Price Discrimination","q":"If a monopolist could charge each buyer his or her exact maximum willingness to pay, it would supply","opts":["a smaller quantity than the competitive market","the same quantity as a single-price monopoly","the same quantity as a competitive market","a smaller quantity than a single-price monopoly"],"a":2,"why":"With perfect price discrimination the firm no longer loses revenue on existing customers when it serves one more, so it keeps selling all the way to the efficient, competitive quantity."},{"id":"dd2-20","s":6,"type":"mc","src":"DemiDec SE2 Q20 RG p.47","term":"Price Discrimination","q":"Although price discrimination raises a monopoly's profit, its effect on social welfare is to","opts":["lower welfare by raising every customer's price","raise welfare by pushing output toward the efficient quantity","lower welfare by restricting output even further","leave welfare unchanged by shifting only profit"],"a":1,"why":"By selling extra units to customers who would not pay the single monopoly price, price discrimination expands output toward the efficient level, so it lifts total welfare even as it fattens the firm's profit."},{"id":"dd2-21","s":6,"type":"mc","src":"DemiDec SE2 Q21 RG p.48","term":"Cartel Instability","q":"After OPEC pushed oil from eleven dollars a barrel in 1972 to thirty-five dollars in 1981, prices collapsed to thirteen dollars by 1986. What does this episode illustrate?","opts":["High prices attract new producers from outside the cartel, adding to supply.","Falling demand is the main thing that drives a cartel's price down.","Cheaper extraction technology lowered costs, so the price fell with them.","Members' incentive to overproduce tends to unravel a cartel's high prices."],"a":3,"why":"Tempted by high prices, OPEC members expanded production through the early 1980s, and the added supply broke the price down, showing how a cartel's own members undermine its pricing."},{"id":"dd2-22","s":6,"type":"mc","src":"DemiDec SE2 Q22 RG p.48","term":"Monopolistic Competition","q":"Which of the following markets BEST illustrates monopolistic competition?","opts":["book publishing","residential electricity","commercial aircraft","wheat farming"],"a":0,"why":"Monopolistic competition means many sellers offering similar but distinct products, which fits book publishing, unlike the single seller, few sellers, or standardized good of the other structures."},{"id":"dd2-23","s":6,"type":"mc","src":"DemiDec SE2 Q23 RG p.49","term":"Creative Destruction","q":"Joseph Schumpeter's phrase “creative destruction” captures the idea that","opts":["cartels deliberately sabotage their smaller competitors","governments must dismantle every monopoly to spur growth","competition eventually drives every firm's profit to zero","innovation builds market power even as it breaks down old barriers"],"a":3,"why":"Schumpeter saw entrepreneurs earning profit by innovating, which creates fresh market power, while the lure of those profits drives others to invent around the old barriers, so progress both creates and destroys."},{"id":"dd2-24","s":6,"type":"mc","src":"DemiDec SE2 Q24 RG p.48","term":"Cartels & Antitrust","q":"Why can OPEC coordinate its members' output openly while the same agreement among United States firms would be illegal?","opts":["OPEC is a pact among sovereign nations.","OPEC's targets have little real effect on the price of oil.","OPEC keeps its production targets completely secret.","OPEC sells a product that no antitrust law happens to cover."],"a":0,"why":"Cartels are illegal under United States antitrust law, but OPEC is an agreement among independent countries, so no single nation's law can stop it from coordinating production."},{"id":"dd2-25","s":7,"type":"mc","src":"DemiDec SE2 Q25 RG p.49","term":"Negative Externality","q":"A factory's smoke dirties a neighbor's laundry, and no money changes hands between them. This situation is an example of","opts":["a public bad","a negative externality","a common resource","a free-rider problem"],"a":1,"why":"Because the smoke harms the neighbor and neither side pays nor is paid for the effect, it is a spillover that the market price misses, which is a negative externality."},{"id":"dd2-26","s":7,"type":"mc","src":"DemiDec SE2 Q26 RG p.50","term":"Positive Externality","q":"When a firm invests in research, rival firms can freely learn from its discoveries, a benefit the firm is never paid for. Compared with the socially optimal amount, how much research does the market produce?","opts":["more research than is socially optimal","exactly the socially optimal amount","more research than consumers actually want","less research than is socially optimal"],"a":3,"why":"Since the firm captures only the value of what it sells and not the free knowledge rivals gain, the market signal understates research's true value, so too little gets produced."},{"id":"dd2-27","s":7,"type":"mc","src":"DemiDec SE2 Q27 RG p.50","term":"Social Cost","q":"If treating the pollution from each unit of paper costs a constant fifteen dollars, the true social cost of the mill's output is drawn as","opts":["the private supply curve shifted up by fifteen dollars at every quantity","the demand curve shifted up by fifteen dollars at every quantity","the demand curve shifted down by fifteen dollars at every quantity","the private supply curve shifted down by fifteen dollars at every quantity"],"a":0,"why":"Adding the fifteen-dollar cleanup cost to the mill's private marginal cost raises the cost of every unit, so the social cost curve is the private supply curve lifted fifteen dollars at each quantity."},{"id":"dd2-28","s":7,"type":"mc","src":"DemiDec SE2 Q28 RG p.50","term":"Optimal Externality","q":"What do economists say about the optimal level of a negative externality?","opts":["The optimal level is the point where the activity's total benefit equals its total harm.","The activity is valuable, so cutting it to zero costs more than the harm avoided.","Pollution is harmful, so permitting any amount of it is wrong.","The optimal level is whatever amount the polluting firm finds most profitable."],"a":1,"why":"The activity behind the externality also produces real value, so squeezing it to zero sacrifices more benefit than the remaining harm is worth, leaving some positive level as the efficient amount."},{"id":"dd2-29","s":7,"type":"mc","src":"DemiDec SE2 Q29 RG p.51","term":"Coase Theorem","q":"What does the Coase Theorem say about which party starts out holding the property right?","opts":["The party that lacks the right tends to end up worse off overall.","The initial assignment decides whether an efficient deal is possible.","The outcome is efficient either way, as long as the right is clearly defined.","Bargaining succeeds only when the polluter holds the right."],"a":2,"why":"Coase showed that as long as rights are clearly defined, the parties bargain to the same efficient result no matter who holds them at the start, since the side that values the outcome more will pay to get it."},{"id":"dd2-30","s":7,"type":"mc","src":"DemiDec SE2 Q30 RG p.51","term":"Internalizing Externalities","q":"Netflix moved from streaming other companies' shows to producing its own. How does this move address the spillover between content makers and streamers?","opts":["It removes the spillover by pushing the original content makers out of business.","It shifts the spillover onto subscribers by raising their fees.","It keeps the two activities separate but has them share the benefit through a contract.","It internalizes the externality by combining both activities in one firm."],"a":3,"why":"By making its own content, Netflix brings the two sides of the spillover under one roof, so benefits that used to pass between separate firms now register inside a single company."},{"id":"dd2-31","s":7,"type":"mc","src":"DemiDec SE2 Q31 RG p.53","term":"Tradable Permits","q":"After capping total sulfur dioxide emissions, the EPA auctioned the rights to emit to the highest bidders. Compared with a fixed quota handed out to firms, the advantage of these tradable permits is that","opts":["they hand every firm the same emissions allowance","they push total emissions below the cap as firms trade","the right to emit ends up with the firms that value it most","they remove the need for the government to set any cap"],"a":2,"why":"A plain quota may give permits to firms that gain little from them, but letting firms buy and sell the permits moves the right to emit toward those who value it most, while still holding emissions to the cap."},{"id":"dd2-32","s":7,"type":"mc","src":"DemiDec SE2 Q32 RG p.56","term":"Rivalry & Excludability","q":"Economists sort goods into four types using two characteristics. What are they?","opts":["elasticity and substitutability","rivalry in consumption and excludability","scarcity and durability","marginal cost and marginal revenue"],"a":1,"why":"Whether one person's use leaves less for others (rivalry) and whether non-payers can be kept out (excludability) are the two dimensions that define private goods, common resources, collective goods, and public goods."},{"id":"dd2-33","s":7,"type":"mc","src":"DemiDec SE2 Q33 RG p.56","term":"Common Resource","q":"Anyone may catch ocean fish, yet each fish one boat lands is one fewer for the others. Which type of good are ocean fish?","opts":["a public good","a common resource","a collective good","a private good"],"a":1,"why":"Ocean fish are rival, since each fish caught is gone for everyone else, but non-excludable, since access is hard to limit, and that combination defines a common resource."},{"id":"dd2-34","s":7,"type":"mc","src":"DemiDec SE2 Q34 RG p.56","term":"Collective Goods","q":"Satellite radio is easy to withhold from non-subscribers but costs almost nothing to provide to one more listener. Why are such collective goods often natural monopolies?","opts":["Their marginal cost is near zero.","They cannot be sold for a price.","Their marginal cost rises steeply.","They are rival in consumption."],"a":0,"why":"Because an extra listener adds almost no cost, average cost keeps falling as more people are served, so a single provider supplies the good more cheaply than several could, the mark of a natural monopoly."},{"id":"dd2-35","s":7,"type":"mc","src":"DemiDec SE2 Q35 RG p.56","term":"Public Good Undersupply","q":"Cable and satellite systems carry far more channels than free over-the-air broadcast. Economists read this as evidence that","opts":["viewers value broadcast channels more than cable channels","broadcast television is rival in consumption","public goods funded only by advertising tend to be undersupplied","advertising funds more programming than subscriptions do"],"a":2,"why":"Because subscribers pay directly for cable and satellite, those systems support far more content than advertising-funded broadcast, which suggests purely public provision leaves such goods undersupplied."},{"id":"dd2-36","s":7,"type":"mc","src":"DemiDec SE2 Q36 RG p.55","term":"Tragedy of the Commons","q":"Six villagers each decide on their own whether to buy a boat to fish a commonly owned lake. Because none of them counts the effect of their own fishing on the others' catch, the number who buy boats turns out to be more than the number that","opts":["would maximize total village income","would give each villager a fair share of the catch","would maximize the total catch of fish","the six villagers could afford to buy"],"a":0,"why":"Acting alone, each villager ignores how his fishing thins the catch for everyone else, so more boats go on the lake than the village's combined income would call for, the familiar tragedy of the commons."},{"id":"dd2-37","s":7,"type":"mc","src":"DemiDec SE2 Q37 RG p.55","term":"Property Rights","q":"According to the tragedy-of-the-commons analysis, what is the simplest way to stop the overfishing of a commonly owned lake?","opts":["Let someone own the lake and decide how many may fish it.","Divide the year's catch equally among all the villagers.","Subsidize each villager who buys a fishing boat.","Require every villager to fish at different hours."],"a":0,"why":"An owner who profits from the lake will allow only as many boats as maximize its value, so creating private property in the resource lines each fishing decision up with the efficient outcome."},{"id":"dd2-38","s":7,"type":"mc","src":"DemiDec SE2 Q38 RG p.56","term":"Degrees of Rivalry","q":"On an empty road one more car barely affects others, but as the road nears capacity each added car slows everyone. What does this show about rivalry in consumption?","opts":["A road counts as a pure public good at all times.","A road is excludable to drivers but never rival.","Rivalry and excludability tend to move together.","Rivalry can be a matter of degree."],"a":3,"why":"A lightly used road is non-rival, but as it fills up one driver's use begins to crowd out others, showing that rivalry can vary by degree rather than being a simple yes or no."},{"id":"dd2-39","s":7,"type":"mc","src":"DemiDec SE2 Q39 RG p.57","term":"Powers of Government","q":"What two powers set government apart from private organizations?","opts":["the power to tax and a monopoly on the legitimate use of force","the power to print money and to fix prices","the power to set interest rates and to charter corporations","the power to enforce contracts and to grant patents"],"a":0,"why":"Private groups must rely on voluntary exchange, but government alone can compel its citizens to pay taxes and can lawfully use force, and these two powers underlie everything else it does."},{"id":"dd2-40","s":7,"type":"mc","src":"DemiDec SE2 Q40 RG p.58","term":"Voting with Your Feet","q":"Citizens who dislike high taxes can","opts":["stop using the public services their taxes pay for","move to a jurisdiction that taxes them less","choose a lower personal tax rate when they file","refuse to pay without legal consequence"],"a":1,"why":"People can vote with their feet, relocating to a city, state, or country with lower taxes, which limits how much any one government can take before residents leave."},{"id":"dd2-41","s":7,"type":"mc","src":"DemiDec SE2 Q41 RG p.58","term":"Contract Enforcement","q":"How does a court system that enforces contracts increase the amount of voluntary exchange in an economy?","opts":["It guarantees that both parties will benefit from contracts.","It removes any need for the parties to inspect each other's goods.","It sets the prices at which contracts must be carried out.","It assures each party the deal will hold, so more of them are willing to enter one."],"a":3,"why":"Knowing a court will hold the other side to the deal, people enter agreements they would otherwise avoid for fear of being left worse off when circumstances change."},{"id":"dd2-42","s":7,"type":"mc","src":"DemiDec SE2 Q42 RG p.58","term":"Shared-Cost Problem","q":"Five friends agree to split a restaurant bill evenly. One of them orders a four-dollar dessert he values at only three dollars. Why does he order it anyway?","opts":["His own share of the cost rises by only eighty cents.","He expects the others to order just as much, so it all evens out.","He figures the other four will not mind paying a little extra.","He cares more about looking generous than about the extra cost."],"a":0,"why":"Splitting the bill five ways means the four-dollar dessert raises his own tab by just eighty cents, less than the three dollars of enjoyment he gets, so he buys it even though it costs the group more than it is worth."},{"id":"dd2-43","s":7,"type":"mc","src":"DemiDec SE2 Q43 RG p.58","term":"Logrolling","q":"A legislator backs a colleague's costly local project in return for the colleague's vote on her own. What is this vote-trading called?","opts":["free riding","pork barrel politics","logrolling","earmarking"],"a":2,"why":"Trading votes so each legislator can pass a pet project for the home district is known as logrolling, and it accounts for a share of wasteful government spending."},{"id":"dd2-44","s":7,"type":"mc","src":"DemiDec SE2 Q44 RG p.59","term":"Rent Seeking","q":"United States sugar policy keeps domestic prices near twice the world level, costing households billions in total but only a few dollars each, while enriching a small group of growers. The growers' lobbying to preserve this policy is an example of","opts":["price discrimination","comparative advantage","rent seeking","creative destruction"],"a":2,"why":"Spending resources to win a transfer of wealth rather than to create new value is rent seeking, and concentrated sugar growers have every reason to lobby while diffuse consumers barely notice the cost."},{"id":"dd2-45","s":6,"type":"mc","src":"DemiDec SE2 Q45 RG p.45","term":"Monopoly Pricing","q":"A cable monopoly finds that its marginal cost equals its marginal revenue at 700 subscribers. At that quantity marginal revenue is seven dollars while the demand curve stands at thirteen dollars. What monthly price should it charge to maximize profit?","opts":["twenty dollars","ten dollars","thirteen dollars","seven dollars"],"a":2,"why":"A monopolist sets quantity where marginal cost meets marginal revenue, then charges the highest price buyers will pay there, which the demand curve puts at thirteen dollars, not the seven-dollar marginal-revenue figure."},{"id":"dd2-46","s":6,"type":"mc","src":"DemiDec SE2 Q46 RG p.42; 45","term":"Price Taker","q":"A wheat farmer and a cable monopoly each want to sell one more unit. Whose marginal revenue equals the market price?","opts":["the cable monopoly, which sets its own price","neither, since marginal revenue is always below price","the wheat farmer, who is too small to affect the price","both, since marginal revenue always equals price"],"a":2,"why":"A competitive seller takes the price as given, so each extra unit brings in the full market price, while a monopoly must cut its price to sell more, pulling its marginal revenue below the price."},{"id":"dd2-47","s":13,"type":"mc","src":"DemiDec SE2 Q47 RG p.40","term":"Winners and Losers from Trade","q":"When a country whose domestic price is above the world price opens to trade, which group gains and which loses?","opts":["Producers gain surplus, while consumers lose surplus.","Consumers gain surplus, while producers lose surplus.","Both groups lose surplus.","Both groups gain surplus."],"a":1,"why":"Opening trade pulls the high domestic price down to the world price, so buyers pay less and gain surplus while domestic producers, facing the lower price, give some up, though the country's total welfare still rises."},{"id":"dd2-48","s":7,"type":"mc","src":"DemiDec SE2 Q48 RG p.49","term":"Sources of Market Failure","q":"Economists group most market failures into two broad categories. What are they?","opts":["ordinary shortages and surpluses","externalities and weak property rights","monopoly and oligopoly power","rising inflation and unemployment"],"a":1,"why":"Markets fail mainly when spillovers go unpriced (externalities) or when goods cannot be owned and withheld, the weak or missing property rights that give rise to public goods."},{"id":"dd2-49","s":7,"type":"mc","src":"DemiDec SE2 Q49 RG p.51","term":"Transaction Costs","q":"Why does private bargaining usually fail to curb the pollution an oil refinery dumps into a river used by thousands?","opts":["Negotiating with so many scattered victims costs far too much.","The pollution actually harms no one downstream.","The refinery values the river more than the victims do.","Property rights to the river are perfectly clear."],"a":0,"why":"When the harm falls on a large, diffuse group, the cost of getting everyone to the bargaining table is prohibitive, so the parties cannot strike the deal Coase's reasoning would otherwise predict."},{"id":"dd2-50","s":7,"type":"mc","src":"DemiDec SE2 Q50 RG p.50","term":"Negative Externality","q":"A paper mill that ignores the downstream cost of its pollution will produce","opts":["more paper than is socially optimal","less paper than is socially optimal","no paper at all once the harm is counted","exactly the socially optimal amount"],"a":0,"why":"Because the mill weighs only its own costs and not the harm to those downstream, it pushes output past the point where total social costs balance the benefits, so it overproduces."},{"id":"dd3-01","s":8,"type":"mc","src":"DemiDec SE3 Q1 RG p.61","term":"Macroeconomics","q":"An economist who wants to explain why the national unemployment rate jumped in 2020 is working in","opts":["macroeconomics","normative economics","positive economics","microeconomics"],"a":0,"why":"Macroeconomics studies the performance of whole national economies, including swings in total output, unemployment, and inflation, rather than the behavior of a single market."},{"id":"dd3-02","s":8,"type":"mc","src":"DemiDec SE3 Q2 RG p.61; 72","term":"Real vs Nominal GDP","q":"Real Gross Domestic Product differs from nominal Gross Domestic Product in that real Gross Domestic Product","opts":["adds the value of imports to domestic output","counts only goods sold to foreign buyers","strips out price changes to track the quantity of output","measures output before any taxes are subtracted"],"a":2,"why":"Real Gross Domestic Product values output using constant prices, so it isolates changes in the actual quantity of goods and services from changes in their prices."},{"id":"dd3-03","s":8,"type":"mc","src":"DemiDec SE3 Q3 RG p.62","term":"Labor Productivity","q":"Total output divided by the number of workers employed gives economists a measure they call","opts":["output per capita","the labor force participation rate","real Gross Domestic Product","average labor productivity"],"a":3,"why":"Average labor productivity is output per worker, a gauge of how much a typical worker produces, distinct from output per capita, which divides output over the whole population."},{"id":"dd3-04","s":8,"type":"mc","src":"DemiDec SE3 Q4 RG p.64","term":"Business Cycle","q":"The repeated alternation of expansions and recessions in an economy is known as the","opts":["business cycle","circular flow","long-run growth trend","cycle of trade surpluses and deficits"],"a":0,"why":"The back-and-forth between expansions and recessions is the business cycle, one of the central patterns that macroeconomics tries to explain."},{"id":"dd3-05","s":8,"type":"mc","src":"DemiDec SE3 Q5 RG p.64","term":"Cost of Recessions","q":"Why do macroeconomic policymakers work to reduce the depth and length of recessions?","opts":["Recessions drive interest rates sharply higher.","Recessions bring falling employment and slower wage growth.","Recessions enlarge the country's trade deficit.","Recessions push the overall price level up too quickly."],"a":1,"why":"During recessions jobs grow scarce and wages stagnate, so easing the severity and duration of these periods is a central goal of macroeconomic policy."},{"id":"dd3-06","s":9,"type":"mc","src":"DemiDec SE3 Q6 RG p.64","term":"Unemployment & the Cycle","q":"Over the course of the business cycle, the unemployment rate usually","opts":["falls during recessions","moves with the inflation rate","falls during expansions","stays roughly constant throughout"],"a":2,"why":"When output falls in a recession, firms shed workers and slow hiring, so unemployment climbs, then recedes as an expansion restores the demand for labor."},{"id":"dd3-07","s":9,"type":"mc","src":"DemiDec SE3 Q7 RG p.64; 74","term":"Unemployment Rate","q":"To compute the unemployment rate, economists divide the number of unemployed people by the","opts":["labor force","working-age population","number of employed people","total population"],"a":0,"why":"The unemployment rate is the share of the labor force, those working or actively seeking work, who cannot find a job, so the denominator is the labor force rather than the whole population."},{"id":"dd3-08","s":9,"type":"mc","src":"DemiDec SE3 Q8 RG p.74","term":"Labor Force","q":"Who counts as part of the labor force under the Bureau of Labor Statistics definition?","opts":["everyone of working age, whether or not they seek work","every adult aged eighteen and over","people who are either employed or actively seeking work","those who hold full-time jobs"],"a":2,"why":"The labor force is the working-age people who are employed plus those actively looking for a job, leaving out anyone who is neither working nor searching."},{"id":"dd3-09","s":9,"type":"mc","src":"DemiDec SE3 Q9 RG p.75","term":"Unemployed","q":"Last week Maria did no paid work, but she filled out applications and went to two job interviews. How does the Bureau of Labor Statistics classify her?","opts":["a discouraged worker","unemployed","not of working age","out of the labor force"],"a":1,"why":"Someone who did no paid work but actively searched within the past four weeks counts as unemployed, which still places her inside the labor force."},{"id":"dd3-10","s":9,"type":"mc","src":"DemiDec SE3 Q10 RG p.65","term":"Natural Rate","q":"Even during a strong expansion, the unemployment rate never falls all the way to zero. Why?","opts":["Workers are always between jobs as new people enter the labor force and industries shift.","Cyclical unemployment lingers even at the peak of an expansion.","Some people choose to stay jobless rather than take the work available.","The number of job-seekers always exceeds the number of open positions."],"a":0,"why":"New entrants are always job-hunting and some firms are always shrinking while others grow, so a pool of people between jobs keeps the rate above zero even in good times."},{"id":"dd3-11","s":9,"type":"mc","src":"DemiDec SE3 Q11 RG p.","term":"Frictional Unemployment","q":"A software engineer quits one job and spends three weeks interviewing before starting a better one. Which type of unemployment are they experiencing?","opts":["structural unemployment","frictional unemployment","cyclical unemployment","seasonal unemployment"],"a":1,"why":"Frictional unemployment is the brief joblessness that comes from the normal time it takes to match workers with employers, exactly the engineer's short search."},{"id":"dd3-12","s":9,"type":"mc","src":"DemiDec SE3 Q12 RG p.76; 77","term":"Structural Unemployment","q":"Workers who are fired because of AI and struggle to find new jobs are experiencing","opts":["cyclical unemployment","structural unemployment","voluntary unemployment","frictional unemployment"],"a":1,"why":"Structural unemployment comes from a lasting mismatch between the skills or locations of job-seekers and the jobs on offer, which is what stranded these workers."},{"id":"dd3-13","s":9,"type":"mc","src":"DemiDec SE3 Q13 RG p.77","term":"Cyclical Unemployment","q":"During a deep recession, layoffs climb and hiring stalls, leaving many workers jobless. The extra unemployment caused this way is called","opts":["structural unemployment","frictional unemployment","cyclical unemployment","the natural rate of unemployment"],"a":2,"why":"The added unemployment that appears when a recession cuts the demand for labor is cyclical unemployment, distinct from the frictional and structural joblessness present even in good times."},{"id":"dd3-14","s":8,"type":"mc","src":"DemiDec SE3 Q14 RG p.65","term":"Inflation","q":"What occurs when the prices of goods and services across the whole economy rise together?","opts":["aggregation","inflation","a trade deficit","stagflation"],"a":1,"why":"A general, economy-wide rise in prices is inflation, which erodes purchasing power because everything people buy grows more expensive."},{"id":"dd3-15","s":8,"type":"mc","src":"DemiDec SE3 Q15 RG p.66","term":"Trade Balance","q":"A country that exports more goods and services than it imports is running a","opts":["trade surplus","balance of trade","budget surplus","balanced budget"],"a":0,"why":"Exports above imports give a trade surplus, while the reverse gives a trade deficit; both describe trade, not the government's budget."},{"id":"dd3-16","s":8,"type":"mc","src":"DemiDec SE3 Q16 RG p.67","term":"GDP","q":"Gross Domestic Product is defined as the market value of all final goods and services produced","opts":["within a country during a set period of time","by a country's firms anywhere in the world","and sold to buyers during that same period","including the resale of used goods and assets"],"a":0,"why":"Gross Domestic Product counts output made inside a country's borders during a specific span, such as a year or a quarter, whoever owns the firms."},{"id":"dd3-17","s":8,"type":"mc","src":"DemiDec SE3 Q17 RG p.67; 68","term":"GDP","q":"An economy makes 100 t-shirts at five dollars each and 25 pairs of shorts at ten dollars each. What is its Gross Domestic Product?","opts":["$375","$125","$750","$1,250"],"a":2,"why":"Gross Domestic Product adds the market value of each good, so 100 shirts at five dollars plus 25 shorts at ten dollars comes to 500 plus 250, or 750 dollars."},{"id":"dd3-18","s":8,"type":"mc","src":"DemiDec SE3 Q18 RG p.68","term":"Market Value in GDP","q":"Why does a higher-priced good add more to Gross Domestic Product than a cheaper good of the same physical kind?","opts":["Only the most expensive version of a good is counted.","Higher-priced goods take more labor to produce.","Its market price reflects the greater value consumers place on it.","Cheaper goods are treated as intermediate goods."],"a":2,"why":"Gross Domestic Product uses market prices, and a higher price signals that buyers value the good more, so it contributes more to measured output."},{"id":"dd3-19","s":8,"type":"mc","src":"DemiDec SE3 Q19 RG p.68; 69","term":"Final vs Intermediate Goods","q":"A steel mill sells $200,000 of steel to an automaker, which then sells $1,000,000 of finished cars. How much do these activities add to Gross Domestic Product?","opts":["$200,000, the value of the steel","$1,200,000, the steel plus the cars","$800,000, the cars minus the steel","$1,000,000, the value of the final cars"],"a":3,"why":"Only the final cars count, since the steel's value is already inside the car price, and adding the steel separately would double-count it."},{"id":"dd3-20","s":8,"type":"mc","src":"DemiDec SE3 Q20 RG p.69","term":"Final vs Intermediate Goods","q":"Sylvia grows $200 of tomatoes; she sells $100 of them fresh and turns the other $100 into sauce she sells for $200. What is her contribution to Gross Domestic Product?","opts":["$500","$300","$400","$200"],"a":1,"why":"Count the $100 of tomatoes sold fresh plus the $200 of sauce sold to consumers; the $100 of tomatoes used up in the sauce is already inside the sauce's value, so the total is $300."},{"id":"dd3-21","s":8,"type":"mc","src":"DemiDec SE3 Q21 RG p.70","term":"Capital Goods in GDP","q":"Why does Gross Domestic Product include newly produced machinery and factory buildings in the year they are made?","opts":["They replace consumer goods produced in the same year.","They are resold each year at the same value.","They are final output, and counting them rewards building for the future.","They are intermediate goods that economists choose to double-count."],"a":2,"why":"Capital goods are long-lived final output, so counting them in the year produced keeps a country that builds for the future from appearing smaller than one that consumes everything now."},{"id":"dd3-22","s":8,"type":"mc","src":"DemiDec SE3 Q22 RG p.70","term":"Domestic Production","q":"United States Gross Domestic Product counts a car built in Ohio by a Japanese-owned plant but not a car built in Mexico by a United States company. Which part of the definition explains this?","opts":["Output is counted by the nationality of the firm's owners.","Output is counted within the country's borders, whoever owns the firm.","Only goods made by domestic-born workers are counted.","Only goods sold to domestic buyers are counted."],"a":1,"why":"The word domestic means output produced inside the country's borders, so location, not ownership, decides what counts in Gross Domestic Product."},{"id":"dd3-23","s":8,"type":"mc","src":"DemiDec SE3 Q23 RG p.70","term":"Used Goods in GDP","q":"A twenty-year-old house sells this year for $150,000, and the agent earns a 6 percent commission. How much of this enters this year's Gross Domestic Product?","opts":["nothing, since no new good was produced","$9,000, the agent's commission","$150,000, the price of the house","$159,000, the house plus the commission"],"a":1,"why":"The house was counted when it was built, so its resale does not count again, but the agent's $9,000 of brokerage service was produced this year and does count."},{"id":"dd3-24","s":8,"type":"mc","src":"DemiDec SE3 Q24 RG p.70","term":"Simon Kuznets","q":"Whom did the United States Commerce Department commission in 1932 to build the first official system for measuring national output?","opts":["William Petty","Simon Kuznets","Michael Boskin","Adam Smith"],"a":1,"why":"Simon Kuznets built the national-accounting system during the Great Depression and later won the Nobel Prize for the work, long after William Petty's much earlier, cruder attempt."},{"id":"dd3-25","s":8,"type":"mc","src":"DemiDec SE3 Q25 RG p.70","term":"Nonmarket Production","q":"Why can Gross Domestic Product rise when families begin paying for childcare they used to provide themselves, even if no additional childcare actually happens?","opts":["Childcare is counted twice once it is paid for.","Unpaid work is counted at below market price.","Only market transactions count.","Paid childcare is of higher quality than unpaid care."],"a":2,"why":"Unpaid household work is left out of Gross Domestic Product, so shifting that work into the paid market makes measured output rise even when the actual amount of childcare is unchanged."},{"id":"dd3-26","s":8,"type":"mc","src":"DemiDec SE3 Q26 RG p.70","term":"Limits of GDP","q":"Kuznets noted that national defense spending is counted as a final good in Gross Domestic Product, even though it could instead be viewed as a(n)","opts":["transfer payment","non-market activity","resale of an existing asset","intermediate input"],"a":3,"why":"Defense can be seen as an input that makes other consumption possible rather than something valued for its own sake, which shows how hard it can be to draw the line around final goods."},{"id":"dd3-27","s":8,"type":"mc","src":"DemiDec SE3 Q27 RG p.70","term":"Limits of GDP","q":"Which of the following costs of production does conventional Gross Domestic Product ignore?","opts":["the market value of exported goods","the wages paid to factory workers","the cost of imported raw materials","the depletion of natural resources and environmental damage"],"a":3,"why":"Standard Gross Domestic Product leaves out the using-up of natural resources and pollution, so measured output can look higher even as the environment is degraded."},{"id":"dd3-28","s":8,"type":"mc","src":"DemiDec SE3 Q28 RG p.71","term":"Expenditures Approach","q":"The expenditures approach to Gross Domestic Product divides all buyers into","opts":["farmers, manufacturers, retailers, and exporters","households, firms, government, and the foreign sector","workers, owners, lenders, and borrowers","consumers, savers, investors, and taxpayers"],"a":1,"why":"Spending is grouped by who does it: households for consumption, firms for investment, government for its purchases, and the foreign sector for net exports."},{"id":"dd3-29","s":8,"type":"mc","src":"DemiDec SE3 Q29 RG p.71","term":"Expenditures Approach","q":"Which of the following equations states the expenditures approach to Gross Domestic Product?","opts":["GDP = C + I + G + NX","GDP = C + I + G - NX","GDP = C + I - G + NX","GDP = C + I + G + T"],"a":0,"why":"Gross Domestic Product equals consumption plus investment plus government purchases plus net exports, the combined spending of the four groups of buyers."},{"id":"dd3-30","s":8,"type":"mc","src":"DemiDec SE3 Q30 RG p.71","term":"Investment in GDP","q":"In ordinary speech, buying shares of stock is called investing, yet economists do not count it as investment in Gross Domestic Product. Why not?","opts":["It is recorded as consumption instead of investment.","Shares of stock are counted as intermediate goods.","It involves foreign rather than domestic buyers.","Buying stock does not create new capital."],"a":3,"why":"To economists, investment means newly produced capital like buildings and equipment, but buying existing shares just moves ownership and makes no new asset, so it is not investment."},{"id":"dd3-31","s":8,"type":"mc","src":"DemiDec SE3 Q31 RG p.71","term":"Residential Investment","q":"Under the expenditures approach, how is a household's purchase of a newly built house classified?","opts":["as a consumer durable","as investment","as a resale of existing property","as the purchase of a financial asset like stock"],"a":1,"why":"New houses are placed under residential fixed investment rather than consumer durables, one of the few household purchases that counts as investment."},{"id":"dd3-32","s":8,"type":"mc","src":"DemiDec SE3 Q32 RG p.71","term":"Consumer Durables","q":"Automobiles, washing machines, and furniture are","opts":["fixed investments","intermediate goods","consumer services","consumer durables"],"a":3,"why":"Long-lived household goods like cars and furniture are consumer durables, distinct from nondurables such as food and clothing that are used up quickly."},{"id":"dd3-33","s":8,"type":"mc","src":"DemiDec SE3 Q33 RG p.71","term":"Transfer Payments","q":"Government purchases in Gross Domestic Product include teachers' salaries and fighter planes, but they exclude","opts":["new equipment bought by city governments","Social Security benefits and interest on the national debt","the wages of firefighters and soldiers","the cost of constructing public schools"],"a":1,"why":"Transfer payments like Social Security and interest on the debt do not buy current output, so they fall outside government purchases in Gross Domestic Product."},{"id":"dd3-34","s":8,"type":"mc","src":"DemiDec SE3 Q34 RG p.71","term":"Net Exports","q":"In the Gross Domestic Product accounts, net exports are defined as","opts":["exports divided by imports","imports minus exports","exports minus imports","exports plus imports"],"a":2,"why":"Net exports subtract the value of imported goods from the value of exports, so a country that imports more than it exports has negative net exports."},{"id":"dd3-35","s":8,"type":"mc","src":"DemiDec SE3 Q35 RG p.72","term":"Three Ways to Measure GDP","q":"Gross Domestic Product can be measured as production, as expenditures, or as income. Why do the three give the same total?","opts":["Imports are added to each of the three measures.","The three agree only in a closed economy.","Each figure is an average of the others.","Every dollar spent on output is income for someone else."],"a":3,"why":"Whatever is produced is sold, and the revenue from each sale is paid out as wages and profit, so production, spending, and income all come to the same total."},{"id":"dd3-36","s":8,"type":"mc","src":"DemiDec SE3 Q36 RG p.72","term":"Real vs Nominal GDP","q":"How do economists construct real Gross Domestic Product so that it reflects changes in output but not changes in prices?","opts":["They divide nominal Gross Domestic Product by the population.","They value each year's output using the prices of a single base year.","They count only goods whose prices did not change.","They subtract net exports from nominal Gross Domestic Product."],"a":1,"why":"By pricing every year's quantities at the same base-year prices, real Gross Domestic Product changes only when output changes, holding prices fixed."},{"id":"dd3-37","s":8,"type":"mc","src":"DemiDec SE3 Q37 RG p.73","term":"CPI","q":"The Consumer Price Index tracks the cost of","opts":["every good and service produced in the economy","a fixed basket of goods a typical household buys","the capital equipment that firms purchase","only goods made by domestic firms"],"a":1,"why":"The Consumer Price Index follows the cost of a representative basket of consumer goods and services, not all output, which is what the Gross Domestic Product deflator covers."},{"id":"dd3-38","s":8,"type":"mc","src":"DemiDec SE3 Q38 RG p.73","term":"CPI Basket","q":"How does the Bureau of Labor Statistics decide which items belong in the Consumer Price Index basket?","opts":["It surveys manufacturers about their wholesale costs.","It uses figures published by the Federal Reserve.","It surveys households about what they actually buy.","It includes every item sold anywhere in the economy."],"a":2,"why":"The Consumer Expenditure Survey has a sample of households record their spending, and those records determine the goods and quantities that make up the basket."},{"id":"dd3-39","s":8,"type":"mc","src":"DemiDec SE3 Q39 RG p.73","term":"CPI","q":"With 2015 as the base year, the Consumer Price Index for a later year equals 100 times the","opts":["cost of the basket in 2015 divided by its cost that year","cost of the basket that year divided by its cost in 2015","basket's cost that year minus its cost in 2015","change in the basket's cost divided by total output"],"a":1,"why":"The index sets the base-year basket equal to 100, then states each later year as 100 times that year's basket cost over the base-year cost."},{"id":"dd3-40","s":8,"type":"mc","src":"DemiDec SE3 Q40 RG p.73","term":"Substitution Bias","q":"Why does the fixed-basket Consumer Price Index tend to overstate the rise in the cost of living?","opts":["The basket overweights luxury goods few households buy.","Stores raise their prices faster than the Bureau can record them.","Households shift toward cheaper goods, but the basket stays fixed.","Households keep buying the same goods no matter how prices move."],"a":2,"why":"When one good gets pricier, families substitute toward cheaper alternatives, but the fixed basket assumes they keep the old mix, so it overstates the true increase in the cost of living."},{"id":"dd3-41","s":8,"type":"mc","src":"DemiDec SE3 Q41 RG p.74","term":"GDP Deflator","q":"The Gross Domestic Product deflator is calculated as 100 times","opts":["real Gross Domestic Product divided by nominal Gross Domestic Product","nominal Gross Domestic Product divided by real Gross Domestic Product","nominal Gross Domestic Product divided by the population","the change in prices divided by total output"],"a":1,"why":"The deflator is the ratio of nominal to real Gross Domestic Product times 100, an inflation gauge that covers all domestic output rather than a fixed consumer basket."},{"id":"dd3-42","s":8,"type":"mc","src":"DemiDec SE3 Q42 RG p.79","term":"GDP per Capita","q":"Real Gross Domestic Product per capita can be written as the product of average labor productivity and the","opts":["size of the trade surplus","growth rate of the population","rate of inflation","share of the population that is working"],"a":3,"why":"Output per person equals output per worker times the fraction of people employed, so living standards rise with productivity and with the share of the population at work."},{"id":"dd3-43","s":8,"type":"mc","src":"DemiDec SE3 Q43 RG p.79","term":"Labor Productivity","q":"Across countries, the largest share of the long-run difference in Gross Domestic Product per capita traces back to differences in","opts":["what share of the population holds a job","how fast the price level is rising","how large the total population is","how much output each worker produces"],"a":3,"why":"Participation rates vary only modestly, so nearly all the gap in output per person between rich and poor countries comes down to differences in average labor productivity, or output per worker."},{"id":"dd3-44","s":8,"type":"mc","src":"DemiDec SE3 Q44 RG p.81","term":"Knowledge Spillovers","q":"Why may private firms underinvest in research and development?","opts":["Research and development rarely produces useful new knowledge.","Research and development requires more capital than a single firm can raise.","Patents make research and development unprofitable.","New knowledge is a public good others can use without reducing its value."],"a":3,"why":"Because a discovery can be used by others without losing its value to the inventor, firms cannot capture all the gains, so they tend to do less research than is socially worthwhile."},{"id":"dd3-45","s":8,"type":"mc","src":"DemiDec SE3 Q45 RG p.63","term":"GDP per Capita","q":"In 2019 China's population was about five times that of the United States, but its total output was only about two-thirds as large. What does this imply about China's output per person?","opts":["It was about two-thirds of the United States level.","It was roughly fifteen percent of the United States level.","It was about five times the United States level.","It was about equal to the United States level."],"a":1,"why":"Spreading two-thirds of the United States output over five times the population gives (2/3) ÷ 5, about 13 percent of the United States output per person. Roughly fifteen percent is the closest choice."},{"id":"dd3-46","s":8,"type":"mc","src":"DemiDec SE3 Q46 RG p.72","term":"Real vs Nominal GDP","q":"Between 2015 and 2020 an economy doubles its output of every good while all prices rise 50 percent. What happens to nominal and real Gross Domestic Product?","opts":["Nominal triples while real doubles.","Both double.","Both triple.","Nominal rises 50 percent while real doubles."],"a":0,"why":"Real Gross Domestic Product follows the doubling of quantities, but nominal also picks up the 50 percent price rise, so nominal rises by two times 1.5, which triples it."},{"id":"dd3-47","s":9,"type":"mc","src":"DemiDec SE3 Q47 RG p.75","term":"Participation Rate","q":"The labor force participation rate is found by dividing the labor force by the","opts":["working-age population","number of people employed","total population","number of people unemployed"],"a":0,"why":"The participation rate is the share of the working-age population that is in the labor force, so the denominator is the working-age population rather than everyone."},{"id":"dd3-48","s":8,"type":"mc","src":"DemiDec SE3 Q48 RG p.74","term":"Quality Change Bias","q":"Personal computers grow far more powerful over the years, yet the Consumer Price Index does not fully capture the improvement. Which source of bias is at work?","opts":["quality change","substitution bias","vertical integration","deflation"],"a":0,"why":"When a good improves but the index treats it as the same item, the recorded price rise overstates the real cost increase, the bias from unmeasured quality change."},{"id":"dd3-49","s":8,"type":"mc","src":"DemiDec SE3 Q49 RG p.77","term":"Circular Flow","q":"In the circular flow model, how do households earn the income they spend?","opts":["by supplying factors of production such as labor and capital to firms","by collecting taxes from firms and government","by selling finished goods and services to firms","by borrowing from the financial markets"],"a":0,"why":"Households own the factors of production and rent them to firms, earning the wages and returns they then spend, save, or pay in taxes."},{"id":"dd3-50","s":8,"type":"mc","src":"DemiDec SE3 Q50 RG p.80","term":"Technological Progress","q":"Which of the following factors do economists call the single MOST important source of long-run gains in labor productivity?","opts":["a higher labor force participation rate","advances in technological knowledge","increases in the trade surplus","growth in the total population"],"a":1,"why":"New techniques and products, from the moving assembly line to semiconductors, have done more than anything else to raise how much a worker can produce over the long run."},{"id":"dd4-01","s":9,"type":"mc","src":"DemiDec SE4 Q1 RG p.81","term":"Bond","q":"A bond is BEST described as a(n)","opts":["claim on assets","insured deposit","share of ownership","certificate of debt"],"a":3,"why":"A bond is an IOU, a certificate of debt that sets out when the loan will be repaid and the interest the borrower will pay, unlike a share of stock, which is part ownership of a firm."},{"id":"dd4-02","s":9,"type":"mc","src":"DemiDec SE4 Q2 RG p.82","term":"Stock","q":"When already-issued shares are bought and sold on an exchange such as the New York Stock Exchange, how much does the issuing company receive from those trades?","opts":["the dividend portion of each share traded","the sale price of every share that is traded","a small commission on each share traded","nothing"],"a":3,"why":"Trades on the secondary market move shares between investors, so the company gets no money from them; only the original issue of new shares brings funds into the firm."},{"id":"dd4-03","s":9,"type":"mc","src":"DemiDec SE4 Q3 RG p.82","term":"Financial Intermediary","q":"A financial intermediary is a(n)","opts":["exchange where stocks are traded directly between investors","saver who lends directly to a company","third party that channels funds from savers to borrowers","government agency that prints the nation's currency"],"a":2,"why":"An intermediary such as a bank or mutual fund stands between savers and borrowers, taking funds from one side and supplying them to the other, unlike a direct loan or a stock exchange."},{"id":"dd4-04","s":9,"type":"mc","src":"DemiDec SE4 Q4 RG p.82","term":"Banks as Intermediaries","q":"Where do banks get the money they lend out to borrowers?","opts":["from reserves they borrow from the Federal Reserve","from the sale of the bank's own shares of stock","from the deposits that savers place with them","from interest on their investments"],"a":2,"why":"Banks gather funds by accepting deposits from savers, then lend those funds out, paying depositors less than they charge borrowers to cover their costs and earn a profit."},{"id":"dd4-05","s":9,"type":"mc","src":"DemiDec SE4 Q5 RG p.82","term":"Deposit Insurance","q":"Why do most depositors regard their bank deposits as nearly free of risk?","opts":["The deposits are backed by shares of the bank's own stock.","The deposits are insured and can be withdrawn anytime.","The deposits rise in value along with the bank's loan profits.","The deposits are guaranteed to earn a high rate of return."],"a":1,"why":"Insured deposits can be withdrawn at any time and do not change in value with the bank's fortunes, so depositors bear little risk while the bank's owners bear it instead."},{"id":"dd4-06","s":9,"type":"mc","src":"DemiDec SE4 Q6 RG p.82","term":"Financial Intermediary","q":"How does a mutual fund reduce risk for a saver who has only a small amount to invest?","opts":["It guarantees the saver a fixed return regardless of the market.","It insures each saver's account against any market loss.","It spreads the money across many companies' stocks and bonds.","It shifts all of the saver's money into cash before any downturn."],"a":2,"why":"A small saver cannot easily buy many securities alone, but a mutual fund pools money to hold a broad portfolio, so a loss at one company is cushioned by gains at others."},{"id":"dd4-07","s":9,"type":"mc","src":"DemiDec SE4 Q7 RG p.83","term":"Saving Equals Investment","q":"In a closed economy, the identity that national saving equals investment follows from the fact that","opts":["in a closed economy there are no exports or imports to subtract","income not spent on consumption or government purchases is what funds investment","households choose to save exactly the amount that firms plan to invest","the interest rate adjusts until the amount saved equals the amount invested"],"a":1,"why":"Starting from Y equals C plus I plus G, subtracting consumption and government purchases leaves saving on one side and investment on the other, so saving equals investment by definition."},{"id":"dd4-08","s":9,"type":"mc","src":"DemiDec SE4 Q8 RG p.83","term":"National Saving","q":"National saving can be divided into two parts. Which of the following pairs names them?","opts":["currency and bank reserves","consumption and investment","private saving and government saving","exports and imports"],"a":2,"why":"National saving is the sum of private saving, what households keep after taxes and consumption, and government saving, the gap between tax revenue and government purchases."},{"id":"dd4-09","s":9,"type":"mc","src":"DemiDec SE4 Q9 RG p.83","term":"Government Saving","q":"Government saving is defined as the difference between","opts":["the government's total spending and the money supply","private saving and private investment","the value of exports and the value of imports","tax revenue and the purchases of goods and services"],"a":3,"why":"Government saving equals tax revenue minus government purchases, so a positive figure is a budget surplus and a negative figure is a budget deficit."},{"id":"dd4-10","s":9,"type":"mc","src":"DemiDec SE4 Q10 RG p.87","term":"Crowding Out","q":"A larger government deficit reduces the supply of saving and drives up the interest rate, leaving less funding for private investment. Economists call this effect","opts":["the menu-cost effect","the multiplier effect","crowding out","the wealth effect"],"a":2,"why":"When government borrowing pulls funds away from private investment by pushing interest rates up, economists call the result crowding out."},{"id":"dd4-11","s":9,"type":"mc","src":"DemiDec SE4 Q11 RG p.83","term":"Net Capital Outflow","q":"Net capital outflow is defined as","opts":["foreigners' purchases of domestic assets minus residents' purchases of foreign assets","domestic residents' purchases of foreign assets minus foreigners' purchases of domestic assets","domestic saving minus domestic investment in a closed economy","the value of exported goods minus the value of imported goods"],"a":1,"why":"Net capital outflow is what domestic residents buy in foreign assets less what foreigners buy in domestic assets, the financial-market counterpart to net exports."},{"id":"dd4-12","s":9,"type":"mc","src":"DemiDec SE4 Q12 RG p.83","term":"FDI vs Portfolio","q":"The Chinese government buys United States Treasury bonds. Which type of international capital flow is this?","opts":["foreign direct investment","a transfer payment","portfolio investment","a net export"],"a":2,"why":"Buying foreign stocks or bonds without taking active control is portfolio investment, unlike foreign direct investment, where the buyer manages the asset, as when a firm builds a plant abroad."},{"id":"dd4-13","s":9,"type":"mc","src":"DemiDec SE4 Q13 RG p.84","term":"Real Interest Rate","q":"The real interest rate equals the nominal interest rate","opts":["divided by the rate of inflation","multiplied by the rate of inflation","plus the rate of inflation","minus the rate of inflation"],"a":3,"why":"The real interest rate adjusts the nominal rate for inflation by subtracting it, showing the true gain in purchasing power a saver earns."},{"id":"dd4-14","s":9,"type":"mc","src":"DemiDec SE4 Q14 RG p.84","term":"Loanable Funds Market","q":"In the market for saving and investment, what adjusts to bring the quantity of saving supplied into line with the quantity demanded for investment?","opts":["the foreign exchange rate","the money multiplier","the rate of inflation","the real interest rate"],"a":3,"why":"The real interest rate is the price of a loan; it rises when borrowers are short of funds and falls when savers are, until saving and investment are equal."},{"id":"dd4-15","s":10,"type":"mc","src":"DemiDec SE4 Q15 RG p.87","term":"Functions of Money","q":"Which of the following functions does money NOT serve?","opts":["hedge against inflation","store of value","unit of account","medium of exchange"],"a":0,"why":"Money must be a medium of exchange, a unit of account, and a store of value; earning interest is not one of these functions, which is why money can pay none and still be held."},{"id":"dd4-16","s":10,"type":"mc","src":"DemiDec SE4 Q16 RG p.87","term":"Medium of Exchange","q":"Why are people willing to hold money even though it pays no interest?","opts":["It is useful for transactions.","It gains value over time.","It can be exchanged for specie on demand.","It is more secure than other assets."],"a":0,"why":"The convenience of being able to buy things quickly with money compensates people for the interest they could have earned by holding a less liquid asset instead."},{"id":"dd4-17","s":10,"type":"mc","src":"DemiDec SE4 Q17 RG p.87","term":"Store of Value","q":"A shopkeeper accepts cash today and holds it for three months before spending it. Which function of money is at work?","opts":["store of value","unit of account","medium of exchange","lender of last resort"],"a":0,"why":"Holding money to carry purchasing power from now into the future is the store-of-value function, distinct from using money to make a purchase or to quote prices."},{"id":"dd4-18","s":10,"type":"mc","src":"DemiDec SE4 Q18 RG p.88","term":"Liquidity","q":"Which of the following assets is the MOST liquid?","opts":["a house","farmland","an antique","currency"],"a":3,"why":"Liquidity is how easily an asset becomes the medium of exchange, and currency already is that medium, while real estate and antiques take time and effort to sell."},{"id":"dd4-19","s":10,"type":"mc","src":"DemiDec SE4 Q19 RG p.88","term":"Commodity Money","q":"During World War II, prisoners of war used cigarettes as money. What kind of money is this?","opts":["commodity money","commercial money","fiat money","fiduciary money"],"a":0,"why":"Cigarettes have worth of their own apart from trade, so using them as money is commodity money, unlike fiat money such as dollar bills, whose value rests on government decree."},{"id":"dd4-20","s":10,"type":"mc","src":"DemiDec SE4 Q20 RG p.88","term":"M1","q":"Besides currency, what does M1 count?","opts":["shares of corporate stock","checking-account deposits","savings-account deposits","the resale value of real estate"],"a":1,"why":"M1 is currency plus checkable deposits, the money in checking accounts that can be spent with a check or debit card; stocks, real estate, and credit lines are not part of it."},{"id":"dd4-21","s":10,"type":"mc","src":"DemiDec SE4 Q21 RG p.88; 89","term":"Money","q":"Why are credit cards left out of the money measures M1 and M2?","opts":["A credit card is accepted only by the largest retailers.","A credit card is issued by the government rather than by banks.","Credit cards are too recent to have been added to the measures.","A credit card defers a payment rather than making one."],"a":3,"why":"Paying with a credit card postpones payment until you settle with the bank later, so it is a way of borrowing, not a stock of money like currency or deposits."},{"id":"dd4-22","s":10,"type":"mc","src":"DemiDec SE4 Q22 RG p.89","term":"The Fed","q":"The Federal Reserve System serves as the United States","opts":["stock exchange","treasury department","largest commercial bank","central bank"],"a":3,"why":"The Federal Reserve is the nation's central bank, supervising banks and regulating the money supply, rather than a commercial bank, a tax collector, or an exchange."},{"id":"dd4-23","s":10,"type":"mc","src":"DemiDec SE4 Q23 RG p.89","term":"Structure of the Fed","q":"The Federal Reserve System is made up of the Federal Reserve Board in Washington plus","opts":["fifty state-run Reserve banks","the commercial banks' trade association","twelve regional Reserve banks","a single national Reserve bank"],"a":2,"why":"Twelve regional Reserve banks, owned by the commercial banks in their districts, operate under the Board of Governors in Washington."},{"id":"dd4-24","s":10,"type":"mc","src":"DemiDec SE4 Q24 RG p.89","term":"The Fed","q":"How do the seven members of the Federal Reserve Board of Governors take office?","opts":["They are appointed by the President and confirmed by the Senate for fourteen years.","They are appointed by Congress to serve four-year terms.","They are elected by the public to serve fourteen-year terms.","They are chosen by the commercial banks that they regulate."],"a":0,"why":"Governors are presidential appointees confirmed by the Senate, and their long fourteen-year terms help shield Fed decisions from political pressure."},{"id":"dd4-25","s":10,"type":"mc","src":"DemiDec SE4 Q25 RG p.89","term":"FOMC","q":"Who makes up the Federal Open Market Committee?","opts":["the seven Fed governors plus all twelve regional bank presidents","the twelve regional bank presidents alone","the seven Fed governors plus five regional bank presidents","the President and the Senate banking committee"],"a":2,"why":"The committee seats all seven governors and five of the twelve regional presidents, with the New York president always included and the others rotating."},{"id":"dd4-26","s":10,"type":"mc","src":"DemiDec SE4 Q26 RG p.89; 90","term":"First Loan","q":"A bank receives a $100 deposit and, holding 20 percent in reserve, lends out $80. By how much does the money supply rise?","opts":["$200","$100","$180","$80"],"a":2,"why":"The depositor still has $100 on deposit while the borrower now holds $80 in currency, so the money supply rises to $180; fractional-reserve lending creates money, though not new wealth."},{"id":"dd4-27","s":10,"type":"mc","src":"DemiDec SE4 Q27 RG p.90","term":"Money Multiplier","q":"If banks hold 20 percent of their deposits as reserves, the money multiplier equals","opts":["80","20","5","0.2"],"a":2,"why":"The money multiplier is one divided by the reserve ratio, so a 20 percent ratio gives one divided by 0.2, or 5 dollars of money for each dollar of reserves."},{"id":"dd4-28","s":10,"type":"mc","src":"DemiDec SE4 Q28 RG p.90","term":"Monetary Base","q":"What name do economists give to the sum of currency held by the public plus the reserves held by banks?","opts":["the money multiplier","the national saving rate","net capital outflow","the monetary base"],"a":3,"why":"Currency plus bank reserves is the monetary base, also called high-powered money, the foundation on which the broader money supply is built."},{"id":"dd4-29","s":10,"type":"mc","src":"DemiDec SE4 Q29 RG p.91","term":"Discount vs Fed Funds","q":"The interest rate the Federal Reserve charges on loans it makes to commercial banks is the","opts":["prime rate","federal funds rate","reserve requirement","discount rate"],"a":3,"why":"The discount rate is what the Fed charges banks that borrow from it, closely linked to the federal funds rate, which is what banks charge one another."},{"id":"dd4-30","s":10,"type":"mc","src":"DemiDec SE4 Q30 RG p.90; 91","term":"Bank Run","q":"A sudden rush of depositors all trying to withdraw their funds at once from a fractional-reserve bank is called","opts":["a margin call","a bank run","an open market operation","a budget deficit"],"a":1,"why":"Because the bank holds only a fraction of deposits as reserves, a simultaneous rush of withdrawals, a bank run, can force even a sound bank to close its doors for a time."},{"id":"dd4-31","s":10,"type":"mc","src":"DemiDec SE4 Q31 RG p.91","term":"Lender of Last Resort","q":"A fundamentally sound bank faces a surge of withdrawals it cannot meet from its reserves. The Federal Reserve steps in as a(n)","opts":["guarantor of its deposits","lender of last resort","buyer of its troubled loans","enforcer of its reserve requirement"],"a":1,"why":"The Fed lends to a solvent bank caught in a run, acting as lender of last resort so that one bank's trouble does not spread through the whole system."},{"id":"dd4-32","s":10,"type":"mc","src":"DemiDec SE4 Q32 RG p.92; 94","term":"Neutrality of Money","q":"The long-run neutrality of money is the principle that a change in the money supply changes","opts":["neither the price level nor real output","the price level but not real output","the price level and real output by equal amounts","real output but not the price level"],"a":1,"why":"In the long run, more money raises prices in proportion but leaves real quantities such as output and relative prices unchanged, which is what neutrality means."},{"id":"dd4-33","s":10,"type":"mc","src":"DemiDec SE4 Q33 RG p.94","term":"Velocity","q":"The velocity of money is defined as the","opts":["share of national income that households save","average number of times a dollar is spent in a year","rate at which the money supply grows each year","total quantity of money the Federal Reserve has issued"],"a":1,"why":"Velocity measures how many times the typical dollar changes hands for goods and services in a year, found by dividing nominal output by the money supply."},{"id":"dd4-34","s":10,"type":"mc","src":"DemiDec SE4 Q34 RG p.94","term":"Velocity","q":"An economy produces 500 t-shirts that sell for $5 each, and its money supply is $250. What is the velocity of money?","opts":["5","0.1","10","50"],"a":2,"why":"Nominal output is 500 times 5, or 2,500 dollars; dividing by the 250-dollar money supply gives a velocity of 10, so each dollar is spent ten times on average."},{"id":"dd4-35","s":10,"type":"mc","src":"DemiDec SE4 Q35 RG p.92","term":"Value of Money","q":"If P is the aggregate price level, the value of money measured in goods and services is","opts":["1 divided by P","P times the money supply","P minus the inflation rate","P itself"],"a":0,"why":"Since P is the dollar cost of a basket of goods, one divided by P is how much of those goods a single dollar can buy, which is the value of money in real terms."},{"id":"dd4-36","s":10,"type":"mc","src":"DemiDec SE4 Q36 RG p.95","term":"Inflation Tax","q":"Inflation is sometimes described as a tax on holding money. Why?","opts":["Cash holdings are taxed at a higher rate than other assets.","Rising prices steadily reduce the purchasing power of the currency people hold.","Inflation pushes incomes into higher tax brackets, raising taxes owed.","Banks charge a penalty on deposits whenever prices rise."],"a":1,"why":"As prices climb, each dollar held buys fewer goods, so inflation works like a tax on money balances, leading people to hold less cash and visit the bank more often."},{"id":"dd4-37","s":10,"type":"mc","src":"DemiDec SE4 Q37 RG p.95; 96","term":"Costs of Inflation","q":"Why does inflation tend to slow long-run economic growth?","opts":["It reduces the number of hours people are willing to work.","It makes future prices hard to predict, discouraging investment.","It pushes firms to downsize their staffing and production.","It diverts investment funds out of bonds and into the stock market."],"a":1,"why":"Uncertainty about future inflation adds risk to lending and borrowing, which cuts the saving and investment that economic growth depends on."},{"id":"dd4-38","s":8,"type":"mc","src":"DemiDec SE4 Q38 RG p.96","term":"Recession","q":"According to the National Bureau of Economic Research, a recession is a period","opts":["whenever the unemployment rate climbs above 5 percent","when economic growth slows but output is still rising","of any two months in which prices are rising","between a peak and a trough in economic activity"],"a":3,"why":"The NBER defines a recession as the stretch from a peak down to a trough, when activity declines broadly across the economy; the reverse, trough to peak, is an expansion."},{"id":"dd4-39","s":9,"type":"mc","src":"DemiDec SE4 Q39 RG p.98","term":"Potential Output","q":"Potential output is BEST described as the quantity of goods and services an economy produces when","opts":["all of its prices are rising together","its resources are employed at normal rates","every worker in the labor force has a job","all sectors of the economy are running at maximum possible capacity"],"a":1,"why":"Potential output is what the economy makes when capital and labor are used at normal rates, a level that still leaves some frictional and structural unemployment rather than none."},{"id":"dd4-40","s":10,"type":"mc","src":"DemiDec SE4 Q40 RG p.98","term":"Output Gap","q":"If Y is actual output and Y* is potential output, the output gap equals","opts":["Y minus Y*","Y* minus Y","Y divided by Y*","Y multiplied by Y*"],"a":0,"why":"The output gap is actual output minus potential output, Y minus Y*, so it is negative during a recession, when actual output falls short of potential."},{"id":"dd4-41","s":9,"type":"mc","src":"DemiDec SE4 Q41 RG p.99","term":"Natural Rate","q":"The natural rate of unemployment is made up of","opts":["frictional and structural unemployment","structural and cyclical unemployment","frictional and cyclical unemployment","cyclical unemployment by itself"],"a":0,"why":"The natural rate is the frictional plus structural unemployment that remains when actual output equals potential; cyclical unemployment, which rises and falls with recessions, is left out."},{"id":"dd4-42","s":9,"type":"mc","src":"DemiDec SE4 Q42 RG p.99","term":"Okun's Law","q":"Under Okun's Law, each one-percentage-point rise in unemployment above the natural rate is associated with an output gap of about","opts":["two percent","one percent","one-half of one percent","ten percent"],"a":0,"why":"Arthur Okun found that every extra percentage point of cyclical unemployment goes with roughly a two-percentage-point shortfall of output below potential."},{"id":"dd4-43","s":10,"type":"mc","src":"DemiDec SE4 Q43 RG p.100; 101","term":"Keynesian Model","q":"In the short run, many firms hold their prices fixed and sell however much is demanded. As a result, short-run output is determined mainly by the","opts":["level of potential output","level of aggregate demand","natural rate of unemployment","size of the money multiplier"],"a":1,"why":"When prices are sticky, firms meet whatever demand appears, so total spending, or aggregate demand, sets output in the short run, while potential output governs the long run."},{"id":"dd4-44","s":10,"type":"mc","src":"DemiDec SE4 Q44 RG p.101","term":"John Maynard Keynes","q":"Who developed the model of short-run fluctuations, in a 1936 book written in response to the Great Depression?","opts":["Arthur Okun","Simon Kuznets","Milton Friedman","John Maynard Keynes"],"a":3,"why":"John Maynard Keynes set out the model of short-run fluctuations in his 1936 General Theory, written to explain the persistent unemployment of the Great Depression."},{"id":"dd4-45","s":10,"type":"mc","src":"DemiDec SE4 Q45 RG p.101; 102","term":"Wealth Effect","q":"Which of the following effects helps explain why the aggregate demand curve slopes downward?","opts":["the menu-cost effect","the crowding-out effect","the wealth effect","the multiplier effect"],"a":2,"why":"A lower price level makes the money people hold worth more in real terms, so they spend more; this wealth effect, with interest-rate and exchange-rate effects, gives aggregate demand its downward slope."},{"id":"dd4-46","s":10,"type":"mc","src":"DemiDec SE4 Q46 RG p.102","term":"Aggregate Demand Shifts","q":"A sharp drop in stock prices wipes out household wealth, as happened after the 2008 financial crisis. In the AD-AS model, this effect","opts":["shifts the long-run aggregate supply curve to the left","shifts the aggregate demand curve to the left","shifts the short-run aggregate supply curve to the left","shifts the aggregate demand curve to the right"],"a":1,"why":"Lower wealth leads households to cut spending at every price level, so the aggregate demand curve shifts left; the shock works through demand, not through either supply curve."},{"id":"dd4-47","s":10,"type":"mc","src":"DemiDec SE4 Q47 RG p.104; 105","term":"Stagflation","q":"How does a negative aggregate supply shock initially affect output and the price level?","opts":["Both output and the price level fall.","Both output and the price level rise.","Output rises while the price level falls.","Output falls while the price level rises."],"a":3,"why":"A leftward shift of short-run aggregate supply cuts the quantity supplied at every price, so output falls and the price level rises together, the pattern called stagflation."},{"id":"dd4-48","s":10,"type":"mc","src":"DemiDec SE4 Q48 RG p.107","term":"Quantity Equation","q":"Potential output grows 2 percent a year while the money supply grows 5 percent a year, with velocity constant. The quantity equation implies long-run inflation of about","opts":["10 percent","7 percent","2 percent","3 percent"],"a":3,"why":"With velocity fixed, prices rise by the gap between money growth and output growth, so 5 percent minus 2 percent leaves inflation of about 3 percent a year."},{"id":"dd4-49","s":10,"type":"mc","src":"DemiDec SE4 Q49 RG p.108","term":"Fiscal Policy","q":"What is an example of expansionary fiscal policy?","opts":["an increase in government spending on public projects","an increase in lending to banks by the Federal Reserve","a purchase of government bonds by the Federal Reserve","an increase in the money supply by the Federal Reserve"],"a":0,"why":"Fiscal policy works through the government's budget, so raising government spending is the fiscal tool against a recession; cutting rates, buying bonds, and expanding the money supply are monetary tools of the Federal Reserve."},{"id":"dd4-50","s":10,"type":"mc","src":"DemiDec SE4 Q50 RG p.108","term":"Fed Tools","q":"The economy is overheating and inflation is accelerating. Which action would the Federal Reserve take to slow it?","opts":["cut federal spending on public programs","raise income taxes to reduce household spending","sell government bonds to reduce the money supply","raise tariffs on imported goods"],"a":2,"why":"The Federal Reserve cools an overheating economy by selling bonds to shrink the money supply and raise interest rates; taxes, spending, and tariffs are tools of Congress, not the Fed."},{"id":"dd5-01","s":11,"type":"mc","src":"DemiDec SE5 Q1 RG p.112","term":"Agglomeration","q":"Economists use the term economies of agglomeration for the gains that arise when","opts":["travelers spread out across a wide rural area","a single firm grows large enough to lower its average cost","people, firms, and institutions locate close to one another","many firms come under one shared regulatory agency"],"a":2,"why":"Economies of agglomeration are the cost savings and productivity gains that come from people, firms, and institutions clustering together, which is why faster, cheaper movement within a city strengthens them."},{"id":"dd5-02","s":11,"type":"mc","src":"DemiDec SE5 Q2 RG p.112","term":"John R. Meyer","q":"Whose work in the late 1950s established transportation economics as a distinct field?","opts":["John R. Meyer","Arthur Okun","Adam Smith","John Maynard Keynes"],"a":0,"why":"Transportation economics emerged in the late 1950s through John R. Meyer, who blended economic theory with civil engineering practice."},{"id":"dd5-03","s":11,"type":"mc","src":"DemiDec SE5 Q3 RG p.112","term":"Discrete Choice","q":"Because travelers often have options, transportation analysts rely on","opts":["benefit-cost analysis","marginal cost pricing","the Rule of Half","discrete choice models"],"a":3,"why":"Choosing between distinct alternatives like driving and rail calls for discrete choice models, statistical tools that became central to modern econometrics."},{"id":"dd5-04","s":11,"type":"mc","src":"DemiDec SE5 Q4 RG p.112","term":"Generalized Cost","q":"In transportation economics, what does the generalized cost of a trip take into account?","opts":["both the monetary expense and the value of travel time","only the money a traveler pays out of pocket","only the time the trip takes from start to finish","the pollution and noise the trip imposes on others"],"a":0,"why":"Generalized cost combines what a trip costs in money with the value of the time it takes, so it captures more than fares or fuel alone."},{"id":"dd5-05","s":11,"type":"mc","src":"DemiDec SE5 Q5 RG p.112","term":"Congestion Pricing","q":"Congestion pricing allows governments to","opts":["charge every traveler the same toll at every hour","remove traffic congestion completely at all times","recover the full capital cost of building the road","account for the social cost of travel"],"a":3,"why":"When travelers do not bear the full social cost of pollution, noise, and delay, tools like congestion pricing and emissions controls make them face more of it, narrowing the gap between private and social cost."},{"id":"dd5-06","s":11,"type":"mc","src":"DemiDec SE5 Q6 RG p.113","term":"Derived Demand","q":"Transportation demand is derived because it","opts":["springs from wanting to do something somewhere else","depends mainly on the price of other inputs","must be met at the moment it is felt","includes demand for many goods and services at the same time"],"a":0,"why":"Travel is a derived demand because the need for it comes from wanting to do something at another place, like working or shopping, rather than from a desire to move for its own sake."},{"id":"dd5-07","s":11,"type":"mc","src":"DemiDec SE5 Q7 RG p.113","term":"Derived Demand","q":"Which of the following situations BEST illustrates the derived nature of passenger transportation demand?","opts":["A couple strolls through a park after dinner.","A jogger runs laps around a track for exercise.","A person drives across town to reach a job interview.","A tourist takes a scenic train ride for the views."],"a":2,"why":"Derived demand means the trip serves a purpose beyond travel, so commuting to a job interview qualifies, while a scenic ride or a stroll is movement enjoyed for its own sake."},{"id":"dd5-08","s":11,"type":"mc","src":"DemiDec SE5 Q8 RG p.113","term":"Freight Demand","q":"The demand for freight transportation is MOST closely tied to the","opts":["value travelers place on saving time","cost of the transported goods","relative cost of the options available for transport","locations of production and consumption"],"a":3,"why":"Freight moves goods from where they are produced to where they are used, so its demand follows the geography of production and consumption, like Midwest grain heading to coastal export terminals."},{"id":"dd5-09","s":11,"type":"mc","src":"DemiDec SE5 Q9 RG p.113","term":"Freight Demand","q":"What phenomenon is MOST responsible for increased demand for regional trucking?","opts":["the growth of e-commerce","the expansion of the interstate highway system","the rise of remote and hybrid work","the growth of intercity passenger rail"],"a":0,"why":"Online retail generates many small, time-sensitive shipments from warehouses to homes, which has boosted demand for regional trucking, urban delivery, and fulfillment centers near transportation hubs."},{"id":"dd5-10","s":11,"type":"mc","src":"DemiDec SE5 Q10 RG p.","term":"Four Trip Decisions","q":"A commuter leaves home earlier than usual specifically to avoid rush-hour congestion. Which travel decision is this?","opts":["mode choice","departure time choice","route choice","destination choice"],"a":1,"why":"Choosing when to begin a trip is the departure time decision, distinct from choosing the mode, the route, or the destination."},{"id":"dd5-11","s":11,"type":"mc","src":"DemiDec SE5 Q11 RG p.114","term":"Four Trip Decisions","q":"An exporter decides whether to ship goods by rail, which is cheaper and slower, or by air, which is faster and more expensive. Which travel decision is this?","opts":["mode choice","destination choice","route choice","departure time choice"],"a":0,"why":"Deciding how a trip will be made, such as rail versus air freight, is the mode decision, which weighs cost against speed."},{"id":"dd5-12","s":11,"type":"mc","src":"DemiDec SE5 Q12 RG p.114","term":"Four Trip Decisions","q":"An eighteen-wheeler driver picks a longer road with wide lanes and gentle curves over a shorter path through narrow streets with tight turns. Which travel decision is this?","opts":["departure time choice","route choice","mode choice","destination choice"],"a":1,"why":"Selecting the specific path a trip follows is the route decision, here favoring a longer but safer road for a large vehicle."},{"id":"dd5-13","s":11,"type":"mc","src":"DemiDec SE5 Q13 RG p.114","term":"Value of Time","q":"Why do higher-income travelers typically place a higher value on travel time?","opts":["They live farther from their workplaces.","Their vehicles are most costly to operate.","They must choose among more modes of transport.","The opportunity cost of their time is greater."],"a":3,"why":"The value of travel time reflects what a person gives up by spending time traveling, and higher earners have more to give up, so their opportunity cost of time is higher."},{"id":"dd5-14","s":11,"type":"mc","src":"DemiDec SE5 Q14 RG p.116","term":"Tested Percentages","q":"About what fraction of the total social cost of an average commute falls externally, on people other than the driver?","opts":["about 10 percent","about 50 percent","about 29 percent","about 75 percent"],"a":2,"why":"About 29 percent of an average commute's total social cost falls on non-drivers, through crash costs, government services, and environmental impacts."},{"id":"dd5-15","s":11,"type":"mc","src":"DemiDec SE5 Q15 RG p.116","term":"Tested Percentages","q":"About what share of roadway costs do drivers fund through fuel taxes and tolls?","opts":["about 3 percent","about 100 percent","about 25 percent","about 75 percent"],"a":2,"why":"Drivers cover only about 25 percent of roadway costs through fuel taxes and tolls, with the rest paid by other taxpayers and employers; by contrast they fund under 3 percent of parking costs."},{"id":"dd5-16","s":11,"type":"mc","src":"DemiDec SE5 Q16 RG p.116","term":"Cost Categories","q":"Which of the following costs is a capital cost of a road?","opts":["labor","maintenance","traffic signals","fuel"],"a":2,"why":"Capital costs are the large, up-front investments needed to build the road itself, such as installing traffic signals, while fuel, labor, and maintenance are recurring operating costs."},{"id":"dd5-17","s":11,"type":"mc","src":"DemiDec SE5 Q17 RG p.116","term":"Internal vs External","q":"What is true of a situation in which the social costs of transportation are equal to private costs?","opts":["Travelers bear less than the full cost of their trips.","The trip creates a market failure that pricing must correct.","The government is subsidizing part of the trip's cost.","There are no externalities."],"a":3,"why":"When social cost equals private cost, travelers bear the whole cost of their trips and impose nothing on anyone else, so no externality exists."},{"id":"dd5-18","s":11,"type":"mc","src":"DemiDec SE5 Q18 RG p.117","term":"Tolling","q":"What strategy can fill the gap between fuel tax revenues and road maintenance costs?","opts":["tolling","widening congested highways","expanding park-and-ride lots","raising the posted speed limit"],"a":0,"why":"Fuel taxes often bring in less than roads cost to maintain, and charging a toll collects revenue straight from the drivers who use the road, closing the gap."},{"id":"dd5-19","s":11,"type":"mc","src":"DemiDec SE5 Q19 RG p.117","term":"Internal vs External","q":"Which of the following costs is substantially borne by non-highway-users?","opts":["vehicle capital","schedule unreliability","operating and maintenance","crashes"],"a":3,"why":"Users pay their own operating, vehicle, and reliability costs in full, but a crash also imposes costs on other drivers, passengers, and the public, so much of it falls outside the individual user."},{"id":"dd5-20","s":11,"type":"mc","src":"DemiDec SE5 Q20 RG p.118","term":"Congestion Pricing","q":"New York City's congestion pricing program, launched in January 2025, charges a toll to drivers who","opts":["park anywhere within New York State","register an electric vehicle in the city","enter Manhattan's core south of 60th Street","drive on any interstate highway in the country"],"a":2,"why":"Since January 2025, drivers entering Manhattan's Congestion Relief Zone south of 60th Street pay a toll, $9 for passenger cars at peak hours, which has cut traffic and sped up transit."},{"id":"dd5-21","s":11,"type":"mc","src":"DemiDec SE5 Q21 RG p.118","term":"HOT Lanes","q":"A dynamically priced high-occupancy toll (HOT) lane sets its toll so as to","opts":["fill the lane to its maximum vehicle capacity","keep speeds in the lane at or above a target level","guarantee the lowest possible toll at all hours","bar high-occupancy vehicles from the lane"],"a":1,"why":"A HOT lane uses real-time sensor data to raise or lower its toll, keeping the lane flowing near a target speed of roughly 45 to 55 miles per hour so paying drivers get a reliable trip."},{"id":"dd5-22","s":11,"type":"mc","src":"DemiDec SE5 Q22 RG p.118","term":"Marginal Cost Pricing","q":"Setting the price of a trip equal to the cost of serving one more trip, in order to maximize social benefit, is called","opts":["marginal cost pricing","profit maximization","average cost pricing","Ramsey pricing"],"a":0,"why":"Marginal cost pricing charges what it costs to serve one additional trip, which maximizes social benefit by setting the number of trips where demand meets marginal cost."},{"id":"dd5-23","s":11,"type":"mc","src":"DemiDec SE5 Q23 RG p.118","term":"Monopoly in Transportation","q":"Why is the gap between profit maximization and marginal cost pricing especially important in transportation?","opts":["Transportation markets usually contain many competing firms.","Transportation has almost no fixed costs to recover.","Transportation services often come from a single operator with monopoly power.","Transportation prices are set entirely by travelers."],"a":2,"why":"Because a single public agency or private operator often controls a service, it could charge a profit-maximizing monopoly price, which makes marginal cost pricing important for protecting social welfare."},{"id":"dd5-24","s":11,"type":"mc","src":"DemiDec SE5 Q24 RG p.118","term":"First-Best Pricing","q":"First-best road pricing fully internalizes congestion, but it is unrealistic because it requires","opts":["perfect information on travel times and tolls and perfectly competitive markets","that every road in the network be toll-free","that travelers ignore all alternative routes","a complete ban on private passenger vehicles"],"a":0,"why":"First-best pricing would charge every driver for the delay imposed on others, but it depends on perfect information and perfectly competitive markets, conditions that cannot be met in practice."},{"id":"dd5-25","s":11,"type":"mc","src":"DemiDec SE5 Q25 RG p.118","term":"Second-Best Pricing","q":"Because first-best pricing is unattainable, second-best pricing instead","opts":["applies marginal cost principles within technological, political, and financial limits","abandons marginal cost principles altogether","removes all tolls from the network","charges every traveler the same flat toll"],"a":0,"why":"Second-best pricing keeps the goal of marginal cost pricing, maximizing welfare, but adapts it to real technological, political, and financial constraints."},{"id":"dd5-26","s":11,"type":"mc","src":"DemiDec SE5 Q26 RG p.118","term":"Congestion Pricing","q":"Congestion pricing manages traffic on a roadway by","opts":["lowering the posted speed limit at peak times","adjusting the toll to influence how many vehicles use the road","widening the road to add more travel lanes","banning trucks from the road during daytime hours"],"a":1,"why":"Congestion pricing uses supply and demand, raising or lowering the toll to control traffic volume so the road does not become overcrowded."},{"id":"dd5-27","s":11,"type":"mc","src":"DemiDec SE5 Q27 RG p.118","term":"Congestion Pricing","q":"What will happen to transportation facilities not rationed by pricing?","opts":["They will be reserved for high-occupancy vehicles.","They will be allocated fairly among all users.","They will be used at their most efficient level.","They will become intolerably congested."],"a":3,"why":"With no price to limit use, drivers keep piling onto a free facility until the traffic itself rations access, leaving the road intolerably congested."},{"id":"dd5-28","s":11,"type":"mc","src":"DemiDec SE5 Q28 RG p.119","term":"Ramsey Pricing","q":"Ramsey pricing explains why airlines charge business travelers more than leisure travelers. The reason is that business travelers","opts":["have less flexible schedules and lower price sensitivity","travel far more often than leisure travelers do","tend to purchase their tickets at the last minute","are charged more by government regulation"],"a":0,"why":"Ramsey pricing puts the biggest markups on customers whose demand is least price-sensitive, like business travelers who must fly at set times, so airlines charge them more while keeping leisure fares low."},{"id":"dd5-29","s":11,"type":"mc","src":"DemiDec SE5 Q29 RG p.119","term":"Deregulation Trade-off","q":"What is a negative outcome of deregulation in the transportation industry?","opts":["reduced competition among carriers","higher prices for shippers and passengers","tighter government control over routes","lowered safety standards"],"a":3,"why":"Freed from regulation, carriers may cut costs in ways that weaken safety, one of the tradeoffs that came with deregulating trucking, rail, and airlines."},{"id":"dd5-30","s":11,"type":"mc","src":"DemiDec SE5 Q30 RG p.119","term":"Economic vs Social Regulation","q":"Economic regulation in transportation has traditionally aimed to","opts":["prevent monopolistic behavior by private firms","improve safety in vehicle crashes","set standards for vehicle fuel economy","reduce pollution from vehicle tailpipes"],"a":0,"why":"Economic regulation controls things like maximum prices, profits, and market entry to curb monopoly power, while safety, emissions, and fuel economy fall under social regulation."},{"id":"dd5-31","s":11,"type":"mc","src":"DemiDec SE5 Q31 RG p.119","term":"Deregulation","q":"In what decade did the United States deregulate trucking, rail, and airlines?","opts":["the 1960s","the 1970s","the 1990s","the 1950s"],"a":1,"why":"The United States deregulated its trucking, railroad, and airline industries in the late 1970s, opening them to competition and letting prices respond to demand."},{"id":"dd5-32","s":11,"type":"mc","src":"DemiDec SE5 Q32 RG p.119","term":"Economies of Density","q":"Which of the following situations BEST exemplifies the economics of density?","opts":["A shipping company builds a new distribution center to reach more customers.","A teenager gets her driver’s license and a new car, but road maintenance costs do not increase.","Two competing bus lines merge into one larger company.","A city widens a highway to carry a growing number of vehicles."],"a":1,"why":"Economies of density appear when more traffic uses infrastructure that already exists without adding to its cost, so an extra driver on existing roads lowers the average cost per user."},{"id":"dd5-33","s":11,"type":"mc","src":"DemiDec SE5 Q33 RG p.119","term":"Historic Regulators","q":"Which of the following pairs names independent regulatory agencies that Congress established to oversee transportation sectors?","opts":["the Federal Reserve and the Treasury Department","the Securities and Exchange Commission and the FDIC","the National Park Service and the Census Bureau","the Interstate Commerce Commission and the Civil Aeronautics Board"],"a":3,"why":"Congress created independent agencies like the Interstate Commerce Commission and the Civil Aeronautics Board to investigate and regulate transportation industries."},{"id":"dd5-34","s":11,"type":"mc","src":"DemiDec SE5 Q34 RG p.120","term":"CAFE","q":"The United States first regulated fuel economy through","opts":["Corporate Average Fuel Economy (CAFE) standards","the Interstate Commerce Commission","the Highway Safety Improvement Program","the National Environmental Policy Act"],"a":0,"why":"The 1973 oil crisis prompted the first fuel-economy rules, the Corporate Average Fuel Economy standards, which are distinct from environmental, safety, or economic regulations."},{"id":"dd5-35","s":11,"type":"mc","src":"DemiDec SE5 Q35 RG p.120","term":"Vehicle Useful Life","q":"Under EPA rules, the “useful life” over which a car or light truck's emissions must meet standards is defined as","opts":["fifteen years or 150,000 miles, whichever comes first","ten years or 120,000 miles, whichever comes first","the entire period the vehicle stays registered","five years or 60,000 miles, whichever comes first"],"a":1,"why":"The EPA sets a vehicle's useful life at ten years or 120,000 miles, whichever comes first, as the period over which emissions must stay within standards."},{"id":"dd5-36","s":11,"type":"mc","src":"DemiDec SE5 Q36 RG p.120; 121","term":"CAFE","q":"What event preceded the first fuel economy standards in the United States?","opts":["the building of the interstate highway system","the 2008 financial crisis","the 1973 oil crisis","the end of World War II"],"a":2,"why":"The 1973 oil crisis and the fuel shortages it triggered pushed Congress to set the first fuel-economy rules, the Corporate Average Fuel Economy standards."},{"id":"dd5-37","s":11,"type":"mc","src":"DemiDec SE5 Q37 RG p.120","term":"Clean Air Act","q":"Which act allows the EPA to recall vehicles that do not meet emissions standards?","opts":["the Clean Water Act","the Clean Air Act","the National Environmental Policy Act","the Motor Vehicle Safety Act"],"a":1,"why":"The Clean Air Act gives the EPA authority to set vehicle emissions limits and to order recalls of cars and trucks that fail to meet them."},{"id":"dd5-38","s":11,"type":"mc","src":"DemiDec SE5 Q38 RG p.121","term":"Highway Trust Fund","q":"The Federal Highway Trust Fund is supported MAINLY by","opts":["vehicle-related taxes","tolls collected by private operators","state property taxes","general federal income taxes"],"a":0,"why":"The Highway Trust Fund draws mainly on federal motor fuel taxes plus truck tire, vehicle sales, and heavy-vehicle taxes, not general income taxes."},{"id":"dd5-39","s":11,"type":"mc","src":"DemiDec SE5 Q39 RG p.121","term":"Transportation Bonds","q":"In transportation finance, a bond issued by a state or local government is BEST described as","opts":["a tax levied on every vehicle owner","a written promise to repay borrowed money with interest","a grant of funds from the federal government","a share of ownership in a toll road"],"a":1,"why":"A transportation bond is a written promise to pay back borrowed money plus interest over its life, a way for governments to raise funds for projects."},{"id":"dd5-40","s":11,"type":"mc","src":"DemiDec SE5 Q40 RG p.121; 122","term":"EVs and the Trust Fund","q":"Why does the spread of hybrid and electric vehicles strain state transportation budgets?","opts":["These vehicles generate less fuel tax revenue than gas cars.","These vehicles damage the roadways more than gas cars.","These vehicles have subsidies that states must bear.","These vehicles cause more crashes than gas cars."],"a":0,"why":"Because fuel taxes depend on gasoline consumed, hybrids and electric vehicles that burn less or no gasoline bring in less fuel tax revenue, straining the budgets that fuel taxes support."},{"id":"dd5-41","s":11,"type":"mc","src":"DemiDec SE5 Q41 RG p.122","term":"Project Delivery","q":"In the 2000s, transportation agencies began adopting design-build delivery in order to","opts":["allow more public review","attract private investment","complete projects more safely","lower construction costs"],"a":1,"why":"Agencies turned to design-build, which combines design and construction, to finish projects faster and draw private investment into large efforts."},{"id":"dd5-42","s":11,"type":"mc","src":"DemiDec SE5 Q42 RG p.122; 123","term":"Rule of Half","q":"The Rule of Half is used in transportation evaluation to estimate the","opts":["discount rate to apply to a project","share of a project's cost paid for by tolls","gain in traveler welfare when travel costs fall","number of crashes a project will prevent"],"a":2,"why":"When travel costs fall, the Rule of Half estimates the resulting gain in traveler welfare, counting full benefits for existing users and half-benefits for new users along a linear demand curve."},{"id":"dd5-43","s":11,"type":"mc","src":"DemiDec SE5 Q43 RG p.122","term":"Project Delivery","q":"Which two groups might agree under a public-private partnership?","opts":["a state highway commission and a county transit authority","a federal court and a state legislature","a state highway commission and a suburban developer","a freight railroad and a trucking company"],"a":2,"why":"A public-private partnership pairs a public agency with a private party, such as a state highway commission and a developer who helps fund and build a project in exchange for a share of the revenue."},{"id":"dd5-44","s":11,"type":"mc","src":"DemiDec SE5 Q44 RG p.123","term":"NPV","q":"What is the net present value (NPV) of a transportation project?","opts":["the toll revenue it collects in the first year","its lifetime benefits minus costs, all expressed in today's dollars","its total construction cost by itself","the ratio of its benefits to its costs"],"a":1,"why":"NPV sums a project's discounted cash flows, benefits minus costs each year, less the initial cost, to state its whole-life worth in present-value dollars."},{"id":"dd5-45","s":11,"type":"mc","src":"DemiDec SE5 Q45 RG p.123","term":"IRR and MARR","q":"The internal rate of return (IRR) of a project is defined as the discount rate that","opts":["makes the project's net present value as large as possible","matches the rate of inflation each year","makes the project's net present value equal to zero","equals the toll charged per mile of travel"],"a":2,"why":"The IRR is the discount rate at which a project's NPV comes out to zero, the effective interest rate that measures the investment's return."},{"id":"dd5-46","s":11,"type":"mc","src":"DemiDec SE5 Q46 RG p.124","term":"Benefit-Cost Analysis","q":"What fundamental economic concept is MOST captured by a benefit-cost analysis?","opts":["economic efficiency","comparative advantage","opportunity cost","supply and demand"],"a":0,"why":"Benefit-cost analysis weighs a project's total social benefits against its total social costs to judge whether it leaves society better off, which is a test of economic efficiency."},{"id":"dd5-47","s":11,"type":"mc","src":"DemiDec SE5 Q47 RG p.124","term":"IRR and MARR","q":"Which of the following metrics should have a value greater than the discount rate in order for a project to be considered economically worthwhile?","opts":["B/C ratio","NPV","IRR","MARR"],"a":2,"why":"A project passes when its internal rate of return is higher than the discount rate, meaning the return beats the cost of tying up the money."},{"id":"dd5-48","s":11,"type":"mc","src":"DemiDec SE5 Q48 RG p.123","term":"NPV","q":"In calculating net present value, what does T indicate?","opts":["the project’s design life","the cash flow","the discount rate","the initial project cost"],"a":0,"why":"In the NPV formula, T stands for the number of years the project operates, its design life, over which each year's costs and benefits are discounted and added up."},{"id":"dd5-49","s":11,"type":"mc","src":"DemiDec SE5 Q49 RG p.124","term":"Transportation Market Failures","q":"Why can private profit-based decisions fail to capture the full social value of transportation?","opts":["Private firms tend to overstate their costs to regulators.","Revenue usually exceeds the true benefits to users.","Some parts are public goods or externalities that markets fail to price.","Travelers rarely pay for the services they actually use."],"a":2,"why":"Local streets, air traffic control, and navigation aids are public goods, and noise, congestion, and pollution are externalities, so revenue and profit miss part of transportation's true social value."},{"id":"dd5-50","s":11,"type":"mc","src":"DemiDec SE5 Q50 RG p.116","term":"Crash Costs","q":"According to the peak-commute breakdown, about what share of crash-related costs do drivers themselves pay?","opts":["about 5 percent","about 59 percent","about 25 percent","about 95 percent"],"a":1,"why":"Drivers personally bear about 59 percent of crash-related costs, with the remaining 41 percent falling on society."},{"id":"s9-01","s":9,"type":"mc","term":"Labor Force","q":"Who is in the labor force?","opts":["Everyone 16 and over","Everyone with a job","Everyone with a job plus everyone jobless who searched in the last month","Everyone who wants a job"],"a":2,"why":"Employed plus unemployed. Retirees, full-time students, and people who stopped looking are out.","src":"Session 9 vocabulary guide"},{"id":"s9-02","s":9,"type":"num","term":"Unemployment Rate","q":"Labor force 200, unemployed 14, working-age population 300. Unemployment rate, as a percent?","ans":7,"tol":0.1,"why":"14 ÷ 200 = 7%. Divide by the labor force, not the population.","src":"Session 9 vocabulary guide"},{"id":"s9-03","s":9,"type":"num","term":"Participation Rate","q":"Labor force 200, working-age population 300. Labor force participation rate, as a percent (one decimal)?","ans":66.7,"tol":0.2,"why":"200 ÷ 300 = 66.7%. Different denominator from the unemployment rate.","src":"Session 9 vocabulary guide"},{"id":"s9-04","s":9,"type":"mc","term":"Discouraged Worker","q":"Thousands of discouraged workers stop searching. The unemployment rate:","opts":["Rises","Falls, with nobody hired","Stays the same","Doubles"],"a":1,"why":"They leave the labor force, so the measured rate falls even though nobody found work.","src":"Session 9 vocabulary guide"},{"id":"s9-05","s":9,"type":"two","term":"Types of Unemployment","q":"A new graduate spends two months finding a first job.","opts":["Frictional","Structural"],"a":0,"why":"Short, voluntary matching time. Frictional.","src":"Session 9 vocabulary guide"},{"id":"s9-06","s":9,"type":"two","term":"Types of Unemployment","q":"Shuttle drivers are replaced by automated vehicles and lack the skills for open jobs.","opts":["Frictional","Structural"],"a":1,"why":"Skills mismatch that a recovery does not fix. Structural.","src":"Session 9 vocabulary guide"},{"id":"s9-07","s":9,"type":"mc","term":"Cyclical Unemployment","q":"Natural rate 5%, actual rate 8%. Cyclical unemployment is:","opts":["5%","8%","3%","13%"],"a":2,"why":"Actual minus natural = 3 points. It disappears when the economy recovers.","src":"Session 9 vocabulary guide"},{"id":"s9-08","s":9,"type":"mc","term":"Full Employment","q":"Full employment means:","opts":["Zero unemployment","Actual rate equals the natural rate","Everyone 16+ has a job","No structural unemployment"],"a":1,"why":"Frictional and structural remain. Only cyclical is zero.","src":"Session 9 vocabulary guide"},{"id":"s9-09","s":9,"type":"num","term":"Okun's Law","q":"Unemployment is 7%, natural rate 5%. By Okun's law, output is about how many percent below potential?","ans":4,"tol":0.1,"why":"2 points × 2% = 4% below potential.","src":"Session 9 vocabulary guide"},{"id":"s9-10","s":9,"type":"two","term":"Stock vs Bond","q":"Which is paid first if the company goes bankrupt?","opts":["Bondholders","Shareholders"],"a":0,"why":"Bondholders are lenders and get paid before owners.","src":"Session 9 vocabulary guide"},{"id":"s9-11","s":9,"type":"mc","term":"Stock","q":"You buy 100 existing shares of a company on an exchange. The company receives:","opts":["The full purchase price","Half the price","Nothing","A loan"],"a":2,"why":"Shares already issued trade between investors. The company gets nothing.","src":"Session 9 vocabulary guide"},{"id":"s9-12","s":9,"type":"mc","term":"Financial Intermediary","q":"Why does a mutual fund reduce risk for a small saver?","opts":["It guarantees returns","It pools money across many stocks and bonds","It is insured by the Fed","It pays higher interest"],"a":1,"why":"Diversification. Many assets instead of one.","src":"Session 9 vocabulary guide"},{"id":"s9-13","s":9,"type":"mc","term":"Crowding Out","q":"The city sells $400 million in bonds for the corridor. In the market for saving and investment:","opts":["Real interest rate falls; private investment rises","Real interest rate rises; some private investment is crowded out","Saving supply shifts right","Nothing changes"],"a":1,"why":"Government borrowing adds to demand for saving, raising the real rate.","src":"Session 9 vocabulary guide"},{"id":"s9-14","s":9,"type":"num","term":"Real Interest Rate","q":"Nominal rate 7%, inflation 4%. Real interest rate, as a percent?","ans":3,"tol":0.1,"why":"Nominal minus inflation = 3%.","src":"Session 9 vocabulary guide"},{"id":"s9-15","s":9,"type":"mc","term":"National Saving","q":"National saving equals:","opts":["Private saving only","Private saving plus government saving","Tax revenue","Investment minus consumption"],"a":1,"why":"Private plus government saving; a deficit is negative government saving.","src":"Session 9 vocabulary guide"},{"id":"s9-16","s":9,"type":"mc","term":"NCO = NX","q":"Foreigners buy more United States goods. Net capital outflow:","opts":["Falls","Is unchanged","Rises, because NCO always equals NX","Becomes negative"],"a":2,"why":"They end up holding dollars, which are United States assets. NCO = NX.","src":"Session 9 vocabulary guide"},{"id":"s9-17","s":9,"type":"two","term":"FDI vs Portfolio","q":"A foreign carmaker builds a plant in Tennessee.","opts":["Foreign direct investment","Portfolio investment"],"a":0,"why":"Buying a business to own and run is FDI.","src":"Session 9 vocabulary guide"},{"id":"s10-01","s":10,"type":"mc","term":"Functions of Money","q":"Which is NOT a function of money?","opts":["Medium of exchange","Unit of account","Store of value","Hedge against inflation"],"a":3,"why":"Three functions. Inflation erodes money; it is not a hedge.","src":"Session 10 vocabulary guide"},{"id":"s10-02","s":10,"type":"mc","term":"Money","q":"A credit card is not money because it:","opts":["Is plastic","Defers a payment instead of making one","Pays no interest","Is issued by banks"],"a":1,"why":"It creates a debt to settle later; the settlement is the money.","src":"Session 10 vocabulary guide"},{"id":"s10-03","s":10,"type":"num","term":"Money Multiplier","q":"Reserve ratio 10%. The money multiplier is:","ans":10,"tol":0,"why":"1 ÷ 0.10 = 10.","src":"Session 10 vocabulary guide"},{"id":"s10-04","s":10,"type":"num","term":"Money Multiplier","q":"Reserve ratio 20%. A new $500 deposit can at most become how many dollars of deposits?","ans":2500,"tol":0,"why":"Multiplier 5 × $500 = $2,500.","src":"Session 10 vocabulary guide"},{"id":"s10-05","s":10,"type":"num","term":"First Loan","q":"Reserve ratio 20%. A $100 deposit arrives and the bank makes its first loan. Money supply right after that loan, in dollars?","ans":180,"tol":0,"why":"$100 deposit still exists plus the $80 loan = $180.","src":"Session 10 vocabulary guide"},{"id":"s10-06","s":10,"type":"mc","term":"Lender of Last Resort","q":"Depositors rush to withdraw from a sound bank. Who lends so one bank's trouble does not spread?","opts":["Congress","The Treasury","The Federal Reserve","The stock exchange"],"a":2,"why":"The Fed is the lender of last resort.","src":"Session 10 vocabulary guide"},{"id":"s10-07","s":10,"type":"mc","term":"The Fed","q":"Why do Fed governors serve fourteen-year terms?","opts":["To match Senate terms","To keep decisions away from political pressure","Because banking is slow","It is a lifetime job"],"a":1,"why":"Long terms insulate monetary policy from short-term politics.","src":"Session 10 vocabulary guide"},{"id":"s10-08","s":10,"type":"mc","term":"FOMC","q":"The FOMC is:","opts":["Twelve regional bank presidents","Seven governors only","Seven governors plus five regional presidents, New York always seated","The Treasury Secretary and the Fed chair"],"a":2,"why":"Seven plus five, with New York permanent.","src":"Session 10 vocabulary guide"},{"id":"s10-09","s":10,"type":"two","term":"Fed Tools","q":"The Fed buys government bonds. Money supply:","opts":["Rises","Falls"],"a":0,"why":"Buying bonds puts reserves into banks. Expansionary.","src":"Session 10 vocabulary guide"},{"id":"s10-10","s":10,"type":"two","term":"Fed Tools","q":"The Fed raises the reserve ratio. Money supply:","opts":["Rises","Falls"],"a":1,"why":"Banks must hold more and lend less.","src":"Session 10 vocabulary guide"},{"id":"s10-11","s":10,"type":"mc","term":"Discount vs Fed Funds","q":"The rate the Fed charges banks that borrow from it is the:","opts":["Federal funds rate","Discount rate","Prime rate","Real rate"],"a":1,"why":"Discount rate. Fed funds is bank-to-bank overnight.","src":"Session 10 vocabulary guide"},{"id":"s10-12","s":10,"type":"mc","term":"Money Market","q":"Why is the money supply curve vertical?","opts":["Demand is fixed","Only the Fed sets it and it does not respond to the interest rate","Banks refuse to lend","Prices are sticky"],"a":1,"why":"Quantity is set by policy, not by the rate.","src":"Session 10 vocabulary guide"},{"id":"s10-13","s":10,"type":"num","term":"Velocity","q":"Output 500 shirts at $5 each, money supply $250. Velocity of money?","ans":10,"tol":0,"why":"Nominal GDP $2,500 ÷ $250 = 10.","src":"Session 10 vocabulary guide"},{"id":"s10-14","s":10,"type":"num","term":"Quantity Equation","q":"Money grows 5%, output grows 2%, velocity steady. Inflation, as a percent?","ans":3,"tol":0.1,"why":"Money growth minus output growth ≈ 3%.","src":"Session 10 vocabulary guide"},{"id":"s10-15","s":10,"type":"mc","term":"Neutrality of Money","q":"In the long run, doubling the money supply:","opts":["Doubles real output","Doubles the price level, leaves real output unchanged","Halves unemployment","Raises the real interest rate"],"a":1,"why":"Money is neutral in the long run.","src":"Session 10 vocabulary guide"},{"id":"s10-16","s":10,"type":"mc","term":"Aggregate Demand","q":"Which is NOT a reason aggregate demand slopes down?","opts":["Wealth effect","Interest rate effect","Exchange rate effect","Substitution between two goods"],"a":3,"why":"Substitution explains a single good's demand, not the whole economy's.","src":"Session 10 vocabulary guide"},{"id":"s10-17","s":10,"type":"mc","term":"Stagflation","q":"An oil price spike hits nearly every business. Output falls and prices rise. This is:","opts":["A recessionary gap from falling demand","Stagflation from a leftward SRAS shift","An inflationary gap","Neutrality of money"],"a":1,"why":"Cost shock shifts short-run aggregate supply left: less output, higher prices.","src":"Session 10 vocabulary guide"},{"id":"s10-18","s":10,"type":"two","term":"Output Gap","q":"Equilibrium output is below potential, with idle resources.","opts":["Recessionary gap","Inflationary gap"],"a":0,"why":"Below potential = recessionary.","src":"Session 10 vocabulary guide"},{"id":"s10-19","s":10,"type":"two","term":"Fiscal vs Monetary","q":"Congress raises spending on public projects.","opts":["Fiscal policy","Monetary policy"],"a":0,"why":"Spending and taxes are fiscal; the Fed does monetary.","src":"Session 10 vocabulary guide"},{"id":"s10-20","s":10,"type":"mc","term":"Keynesian Model","q":"In the Keynesian short run, what sets output?","opts":["Potential output","Aggregate demand, because prices are sticky","The money multiplier","The exchange rate"],"a":1,"why":"Firms meet whatever demand appears when prices are sticky.","src":"Session 10 vocabulary guide"},{"id":"s10-21","s":10,"type":"mc","term":"Expansionary Monetary","q":"To close a recessionary gap, the Fed would:","opts":["Sell bonds","Raise the discount rate","Buy bonds","Raise taxes"],"a":2,"why":"Buy bonds → money supply up → nominal rate down → investment up → AD right.","src":"Session 10 vocabulary guide"},{"id":"s11-01","s":11,"type":"mc","term":"Agglomeration","q":"Why are cities more productive per worker?","opts":["Higher taxes","Economies of agglomeration: shared labor pools, nearby suppliers, fast idea spread","Lower rents","Less traffic"],"a":1,"why":"Clustering raises productivity, and cheap movement is what allows clustering.","src":"Session 11 vocabulary guide"},{"id":"s11-02","s":11,"type":"two","term":"Derived Demand","q":"Driving across town to a job interview.","opts":["Derived demand","Not derived demand"],"a":0,"why":"The trip exists to do something elsewhere.","src":"Session 11 vocabulary guide"},{"id":"s11-03","s":11,"type":"two","term":"Derived Demand","q":"A scenic train ride taken for the views.","opts":["Derived demand","Not derived demand"],"a":1,"why":"The travel itself is the goal.","src":"Session 11 vocabulary guide"},{"id":"s11-04","s":11,"type":"mc","term":"Remote Work","q":"Remote work shrinks the rush-hour peak because:","opts":["Roads got wider","It removes the derived trips the commute generated","Gas got cheaper","Transit improved"],"a":1,"why":"No work destination, no derived trip.","src":"Session 11 vocabulary guide"},{"id":"s11-05","s":11,"type":"mc","term":"Four Trip Decisions","q":"A trucker picks a longer road with wider lanes. Which decision?","opts":["Departure time","Destination","Mode","Route"],"a":3,"why":"Which path = route.","src":"Session 11 vocabulary guide"},{"id":"s11-06","s":11,"type":"mc","term":"Four Trip Decisions","q":"Leaving at 6 a.m. to miss traffic is a:","opts":["Time decision","Destination decision","Mode decision","Route decision"],"a":0,"why":"When to go.","src":"Session 11 vocabulary guide"},{"id":"s11-07","s":11,"type":"mc","term":"Discrete Choice","q":"A discrete choice model outputs:","opts":["A certainty about which mode a traveler takes","A probability for each option","The cheapest route","The fastest route"],"a":1,"why":"Scores become probabilities, which planners sum into forecasts.","src":"Session 11 vocabulary guide"},{"id":"s11-08","s":11,"type":"num","term":"Generalized Cost","q":"Bus fare $2.50, trip 40 minutes, rider values time at $15 an hour. Generalized cost in dollars?","ans":12.5,"tol":0.01,"why":"$2.50 + (40/60 × $15 = $10) = $12.50. Count time, not just money.","src":"Session 11 vocabulary guide"},{"id":"s11-09","s":11,"type":"mc","term":"Value of Time","q":"Who values travel time most?","opts":["Vacationer on a weekend","Business traveler on a work trip","Student on a free day","Retiree running errands"],"a":1,"why":"Time is an opportunity cost; business time earns more.","src":"Session 11 vocabulary guide"},{"id":"s11-10","s":11,"type":"two","term":"Internal vs External","q":"The delay one more car adds to everyone behind it.","opts":["Internal cost","External cost"],"a":1,"why":"Each driver slows the system and pays nothing for it.","src":"Session 11 vocabulary guide"},{"id":"s11-11","s":11,"type":"num","term":"Tested Percentages","q":"About what percent of a car commute's total cost falls on other people?","ans":29,"tol":1,"why":"29% external. Drivers cover about 25% of road costs and under 3% of parking.","src":"Session 11 vocabulary guide"},{"id":"s11-12","s":11,"type":"mc","term":"Cost Categories","q":"Which cost varies MOST across modes?","opts":["Operating","Capital","Fuel","Staff"],"a":1,"why":"Highways, tracks, airports: big fixed capital. Operating costs look alike.","src":"Session 11 vocabulary guide"},{"id":"s11-13","s":11,"type":"mc","term":"Marginal Cost Pricing","q":"A free road is priced:","opts":["Exactly right","Too high, so it is underused","Too low, so it grows congested","At the monopoly level"],"a":2,"why":"Zero price below marginal social cost. Congestion rations it instead.","src":"Session 11 vocabulary guide"},{"id":"s11-14","s":11,"type":"mc","term":"First-Best Pricing","q":"Why is first-best pricing unrealistic?","opts":["Tolls are illegal","It needs information nobody has and perfectly competitive markets","Drivers refuse to pay","It only works for freight"],"a":1,"why":"Second-best keeps the marginal-cost goal within real limits.","src":"Session 11 vocabulary guide"},{"id":"s11-15","s":11,"type":"mc","term":"Congestion Pricing","q":"Manhattan's 2025 congestion pricing tolls vehicles entering:","opts":["Any bridge","Below 60th Street","Central Park","Brooklyn"],"a":1,"why":"About $9 at peak for cars. Traffic fell, transit sped up.","src":"Session 11 vocabulary guide"},{"id":"s11-16","s":11,"type":"mc","term":"HOT Lanes","q":"HOT lane prices change minute by minute to:","opts":["Maximize revenue","Fill the lane to capacity","Keep the lane moving near a target speed","Punish solo drivers"],"a":2,"why":"Live pricing to hold speed, not to fill.","src":"Session 11 vocabulary guide"},{"id":"s11-17","s":11,"type":"mc","term":"Ramsey Pricing","q":"Airlines charge business travelers more because their demand is:","opts":["Elastic","Inelastic","Derived","External"],"a":1,"why":"Charge the least price-sensitive users the most. Session 4 elasticity, applied.","src":"Session 11 vocabulary guide"},{"id":"s11-18","s":11,"type":"mc","term":"Freight Demand","q":"Freight demand comes from:","opts":["Wanting to move goods for its own sake","The gap between where goods are produced and consumed","Government mandates","Fuel prices only"],"a":1,"why":"Midwest grain to export terminals; crude to Gulf refineries.","src":"Session 11 vocabulary guide"},{"id":"s12-01","s":12,"type":"two","term":"Economic vs Social Regulation","q":"A rule capping what a pipeline may charge shippers.","opts":["Economic regulation","Social regulation"],"a":0,"why":"Prices, profits, entry = economic. Health, safety, environment = social.","src":"Session 12 vocabulary guide"},{"id":"s12-02","s":12,"type":"two","term":"Economic vs Social Regulation","q":"A rule limiting tailpipe emissions on new cars.","opts":["Economic regulation","Social regulation"],"a":1,"why":"Environmental protection is social regulation.","src":"Session 12 vocabulary guide"},{"id":"s12-03","s":12,"type":"mc","term":"Economies of Density","q":"Why does one dominant firm usually end up serving a transportation market?","opts":["Government picks a winner","Economies of density: more traffic on existing infrastructure lowers cost per user","Consumers prefer monopolies","Fuel is cheap"],"a":1,"why":"Duplicate tracks would waste resources, which is why economic regulation exists.","src":"Session 12 vocabulary guide"},{"id":"s12-04","s":12,"type":"mc","term":"Historic Regulators","q":"Which agency regulated airlines until it was abolished in 1985?","opts":["Interstate Commerce Commission","Civil Aeronautics Board","NHTSA","EPA"],"a":1,"why":"CAB (abolished 1985). ICC went in 1995.","src":"Session 12 vocabulary guide"},{"id":"s12-05","s":12,"type":"mc","term":"Deregulation","q":"Deregulation of trucking, rail, and airlines began in the:","opts":["1950s","1960s","Late 1970s","1990s"],"a":2,"why":"Late 1970s. More competition, lower fares, demand sets prices.","src":"Session 12 vocabulary guide"},{"id":"s12-06","s":12,"type":"mc","term":"Deregulation Trade-off","q":"The exam's negative outcome of deregulation is:","opts":["Higher fares","Fewer companies","Lowered safety standards","Government-set prices"],"a":2,"why":"New risk to workers, safety, and long-term investment.","src":"Session 12 vocabulary guide"},{"id":"s12-07","s":12,"type":"mc","term":"NEPA","q":"The 1969 act requiring federal projects to study environmental effects first:","opts":["Clean Air Act","NEPA","CAFE standards","SAFETEA-LU"],"a":1,"why":"National Environmental Policy Act, 1969.","src":"Session 12 vocabulary guide"},{"id":"s12-08","s":12,"type":"mc","term":"Clean Air Act","q":"Under the Clean Air Act, a car's useful life for emissions rules is:","opts":["5 years or 50,000 miles","10 years or 120,000 miles","15 years or 200,000 miles","Unlimited"],"a":1,"why":"Ten years or 120,000 miles.","src":"Session 12 vocabulary guide"},{"id":"s12-09","s":12,"type":"mc","term":"CAFE","q":"Corporate Average Fuel Economy standards (1973) were set after:","opts":["The Great Depression","World War II","The oil crisis","The 2008 recession"],"a":2,"why":"First fuel economy rules, a response to the 1973 oil crisis.","src":"Session 12 vocabulary guide"},{"id":"s12-10","s":12,"type":"num","term":"Road Deaths","q":"About how many people die on American roads each year (thousands)?","ans":40,"tol":2,"why":"About 40,000.","src":"Session 12 vocabulary guide"},{"id":"s12-11","s":12,"type":"num","term":"Crash Costs","q":"Drivers bear about what percent of crash-related costs?","ans":59,"tol":1,"why":"59%. The rest falls on society.","src":"Session 12 vocabulary guide"},{"id":"s12-12","s":12,"type":"mc","term":"Highway Trust Fund","q":"The Highway Trust Fund is fed mainly by:","opts":["General income taxes","Motor fuel taxes and truck-related taxes","Property taxes","Transit fares"],"a":1,"why":"Fuel, truck tire, truck sales, heavy vehicle use taxes. Not income tax.","src":"Session 12 vocabulary guide"},{"id":"s12-13","s":12,"type":"mc","term":"EVs and the Trust Fund","q":"Electric vehicles strain the Highway Trust Fund because they:","opts":["Weigh more","Pay little or no fuel tax","Use more road space","Need new roads"],"a":1,"why":"Less gasoline burned, less fuel tax paid.","src":"Session 12 vocabulary guide"},{"id":"s12-14","s":12,"type":"mc","term":"Project Delivery","q":"The department finishes the design, then hires a separate company to build. This is:","opts":["Design-build","Design-bid-build","Public-private partnership","Tax increment financing"],"a":1,"why":"Separation keeps bidding fair.","src":"Session 12 vocabulary guide"},{"id":"s12-15","s":12,"type":"mc","term":"Project Delivery","q":"A private investor helps fund a toll road and earns it back through tolls under a fixed-term agreement:","opts":["Design-bid-build","Design-build","Public-private partnership","Highway Trust Fund"],"a":2,"why":"P3: private capital, private operation, fixed term.","src":"Session 12 vocabulary guide"},{"id":"s12-16","s":12,"type":"num","term":"Discount Rate","q":"A $110 benefit arrives one year from now. At a 10% discount rate, its value today in dollars?","ans":100,"tol":0.01,"why":"110 ÷ 1.10 = 100.","src":"Session 12 vocabulary guide"},{"id":"s12-17","s":12,"type":"mc","term":"Discount Rate","q":"A higher discount rate:","opts":["Helps long-lived projects","Shrinks far-off benefits, working against long-lived projects","Has no effect on NPV","Raises IRR"],"a":1,"why":"Future dollars are worth less today at a higher rate.","src":"Session 12 vocabulary guide"},{"id":"s12-18","s":12,"type":"two","term":"NPV","q":"NPV is negative. The project:","opts":["Passes","Fails"],"a":1,"why":"Costs beat discounted benefits.","src":"Session 12 vocabulary guide"},{"id":"s12-19","s":12,"type":"mc","term":"IRR and MARR","q":"Which metric must exceed the discount rate for a project to pass?","opts":["NPV","Benefit-cost ratio","IRR","MARR"],"a":2,"why":"IRR is the rate that makes NPV zero; it must beat the discount rate and the MARR.","src":"Session 12 vocabulary guide"},{"id":"s12-20","s":12,"type":"num","term":"Rule of Half","q":"A project saves $4 per trip. 1,000 existing trips, 200 new trips. Total traveler benefit in dollars by the Rule of Half?","ans":4400,"tol":0,"why":"$4 × 1,000 + $2 × 200 = $4,400.","src":"Session 12 vocabulary guide"},{"id":"s12-21","s":12,"type":"mc","term":"Rule of Half","q":"Why do new travelers get only half the savings on average?","opts":["They pay half fare","The first new traveler gains almost all, the last barely any","Half of them quit","It is a tax rule"],"a":1,"why":"Benefit to new trips forms a triangle; average is half.","src":"Session 12 vocabulary guide"},{"id":"s12-22","s":12,"type":"two","term":"BCA vs EIA","q":"Counts a rider's time savings as a benefit.","opts":["Benefit-cost analysis","Economic impact analysis"],"a":0,"why":"BCA counts gains that never become money. EIA follows money only.","src":"Session 12 vocabulary guide"},{"id":"s12-23","s":12,"type":"two","term":"BCA vs EIA","q":"Maps the jobs and business sales a project creates.","opts":["Benefit-cost analysis","Economic impact analysis"],"a":1,"why":"EIA tracks ripple effects; BCA decides if the project is worth it.","src":"Session 12 vocabulary guide"},{"id":"s12-24","s":12,"type":"mc","term":"BCA Pass","q":"A project passes benefit-cost analysis when:","opts":["BCR below 1","NPV above 0, BCR above 1, IRR above the discount rate","It creates jobs","Revenue exceeds cost"],"a":1,"why":"All three tests point the same way.","src":"Session 12 vocabulary guide"},{"id":"s4-10","s":4,"type":"num","term":"Midpoint Method","q":"Quantity falls from 21,000 to 19,000. Percent change by midpoint (whole number)?","ans":10,"tol":0.5,"why":"2,000 ÷ 20,000 = 10%.","src":"Session 4 vocabulary guide"},{"id":"s4-11","s":4,"type":"mc","term":"Total Revenue Test","q":"Price falls and total revenue rises. Demand is:","opts":["Elastic","Inelastic","Unit elastic","Perfectly inelastic"],"a":0,"why":"Opposite directions = elastic.","src":"Session 4 vocabulary guide"},{"id":"s4-12","s":4,"type":"two","term":"Elastic vs Inelastic","q":"Insulin for a diabetic patient.","opts":["Elastic","Inelastic"],"a":1,"why":"Necessity with no substitutes.","src":"Session 4 vocabulary guide"},{"id":"s4-13","s":4,"type":"two","term":"Elastic vs Inelastic","q":"A specific brand of bottled water.","opts":["Elastic","Inelastic"],"a":0,"why":"Many close substitutes.","src":"Session 4 vocabulary guide"},{"id":"s4-14","s":4,"type":"mc","term":"Perfectly Inelastic","q":"A vertical demand curve means elasticity is:","opts":["Infinite","Zero","One","Negative one"],"a":1,"why":"Quantity does not respond to price at all.","src":"Session 4 vocabulary guide"},{"id":"s4-15","s":4,"type":"mc","term":"Income Elasticity","q":"Income rises 10%, quantity demanded rises 20%. The good is:","opts":["Inferior","Normal and a necessity","Normal and a luxury","Giffen"],"a":2,"why":"Income elasticity 2, greater than 1 = luxury.","src":"Session 4 vocabulary guide"},{"id":"s4-16","s":4,"type":"mc","term":"Cross-Price Elasticity","q":"Cross-price elasticity between two goods is negative. They are:","opts":["Substitutes","Complements","Unrelated","Inferior"],"a":1,"why":"Price of one up, demand for other down = complements.","src":"Session 4 vocabulary guide"},{"id":"s4-17","s":4,"type":"num","term":"Price Elasticity","q":"Price rises 10%, quantity falls 5%. Elasticity (drop the sign, one decimal)?","ans":0.5,"tol":0.01,"why":"5 ÷ 10 = 0.5. Inelastic.","src":"Session 4 vocabulary guide"},{"id":"s4-18","s":4,"type":"mc","term":"Time Horizon","q":"Gasoline demand is more elastic in the long run because:","opts":["Prices fall","Buyers have time to adjust: carpool, move, buy efficient cars","Supply increases","Taxes change"],"a":1,"why":"More time, more options, more elastic.","src":"Session 4 vocabulary guide"},{"id":"s4-19","s":4,"type":"num","term":"Total Revenue","q":"Fare $7.00, riders 19,000. Daily total revenue in dollars?","ans":133000,"tol":0,"why":"P × Q = $133,000.","src":"Session 4 vocabulary guide"},{"id":"s5-11","s":5,"type":"two","term":"Binding Ceiling","q":"Equilibrium rent $1,200; ceiling set at $1,500.","opts":["Binding","Not binding"],"a":1,"why":"Above equilibrium, a ceiling does nothing.","src":"Session 5 vocabulary guide"},{"id":"s5-12","s":5,"type":"two","term":"Binding Floor","q":"Equilibrium wage $14; minimum wage $17.","opts":["Binding","Not binding"],"a":0,"why":"Above equilibrium, the floor binds and creates a surplus of labor.","src":"Session 5 vocabulary guide"},{"id":"s5-13","s":5,"type":"mc","term":"Price Ceiling Effects","q":"A binding rent ceiling leads to:","opts":["More apartments built","Shortage, waiting lists, lower quality","Lower demand","Higher landlord profit"],"a":1,"why":"Qd > Qs at the capped price; non-price rationing follows.","src":"Session 5 vocabulary guide"},{"id":"s5-14","s":5,"type":"mc","term":"Tax Incidence","q":"A tax is levied on sellers. Compared to the same tax on buyers, the burden split is:","opts":["Entirely on sellers","Entirely on buyers","The same; elasticities decide","Reversed"],"a":2,"why":"Who writes the check does not change who bears it.","src":"Session 5 vocabulary guide"},{"id":"s5-15","s":5,"type":"num","term":"Tax Wedge","q":"Buyers pay $6.10, sellers receive $4.50. Size of the tax in dollars?","ans":1.6,"tol":0.01,"why":"6.10 − 4.50 = $1.60.","src":"Session 5 vocabulary guide"},{"id":"s5-16","s":5,"type":"mc","term":"Deadweight Loss","q":"Deadweight loss from a tax is larger when:","opts":["Demand and supply are inelastic","Demand and supply are elastic","The tax is small","Government spends the revenue"],"a":1,"why":"Elastic curves mean more trades vanish.","src":"Session 5 vocabulary guide"},{"id":"s5-17","s":5,"type":"num","term":"Deadweight Loss","q":"A $1.60 tax cuts rides from 21,000 to 19,000. Deadweight loss in dollars?","ans":1600,"tol":0,"why":"½ × 2,000 × $1.60 = $1,600.","src":"Session 5 vocabulary guide"},{"id":"s5-18","s":5,"type":"mc","term":"Subsidy","q":"A subsidy to shuttle operators shifts:","opts":["Demand left","Supply right, lowering price and raising quantity","Supply left","Nothing"],"a":1,"why":"Opposite of a tax on sellers.","src":"Session 5 vocabulary guide"},{"id":"s5-19","s":5,"type":"mc","term":"Price Floor Surplus","q":"At a $17 minimum wage, 900 workers want jobs and firms hire 700. Unemployment created:","opts":["200","700","900","1,600"],"a":0,"why":"Qs − Qd = 200.","src":"Session 5 vocabulary guide"},{"id":"s5-20","s":5,"type":"mc","term":"Burden Rule","q":"Supply is perfectly elastic. Who bears the whole tax?","opts":["Sellers","Buyers","Split evenly","Government"],"a":1,"why":"Sellers can walk away entirely; buyers bear it all.","src":"Session 5 vocabulary guide"},{"id":"s7-11","s":7,"type":"two","term":"Externality Sign","q":"A neighbor plants a flower garden everyone enjoys.","opts":["Positive externality","Negative externality"],"a":0,"why":"Benefit spills onto others.","src":"Session 7 vocabulary guide"},{"id":"s7-12","s":7,"type":"two","term":"Externality Sign","q":"A factory's smoke drifts over a school.","opts":["Positive externality","Negative externality"],"a":1,"why":"Cost spills onto others.","src":"Session 7 vocabulary guide"},{"id":"s7-13","s":7,"type":"mc","term":"Negative Externality","q":"With a negative externality, the market produces:","opts":["Too little","Too much, because private cost is below social cost","Exactly the right amount","Nothing"],"a":1,"why":"Producers ignore the external cost.","src":"Session 7 vocabulary guide"},{"id":"s7-14","s":7,"type":"mc","term":"Pigouvian Tax","q":"A tax equal to the external cost per unit is a:","opts":["Subsidy","Pigouvian tax","Price ceiling","Tariff"],"a":1,"why":"It internalizes the externality.","src":"Session 7 vocabulary guide"},{"id":"s7-15","s":7,"type":"num","term":"Social Cost","q":"Private cost $5.35, external cost $0.80. Social cost in dollars?","ans":6.15,"tol":0.01,"why":"Private + external.","src":"Session 7 vocabulary guide"},{"id":"s7-16","s":7,"type":"mc","term":"Public Good","q":"A public good is:","opts":["Rival and excludable","Non-rival and non-excludable","Provided only by charities","Always free"],"a":1,"why":"Fireworks, national defense, streetlights.","src":"Session 7 vocabulary guide"},{"id":"s7-17","s":7,"type":"mc","term":"Free Rider","q":"The free-rider problem explains why:","opts":["Private firms underprovide public goods","Taxes are too high","Monopolies form","Prices rise"],"a":0,"why":"People benefit without paying, so nobody wants to pay.","src":"Session 7 vocabulary guide"},{"id":"s7-18","s":7,"type":"mc","term":"Tragedy of the Commons","q":"Overfishing in open ocean is an example of:","opts":["A public good","Tragedy of the commons","A natural monopoly","Price discrimination"],"a":1,"why":"Rival but non-excludable: common resource, overused.","src":"Session 7 vocabulary guide"},{"id":"s7-19","s":7,"type":"mc","term":"Coase Theorem","q":"The Coase theorem says private parties can solve externalities themselves if:","opts":["Government bans the activity","Transaction costs are low and property rights are clear","Taxes are zero","There are many parties"],"a":1,"why":"Bargaining works when it is cheap and rights are defined.","src":"Session 7 vocabulary guide"},{"id":"s7-20","s":7,"type":"mc","term":"Asymmetric Information","q":"Used-car buyers can't tell lemons from good cars, so good cars leave the market. This is:","opts":["Moral hazard","Adverse selection","A public good","A positive externality"],"a":1,"why":"Hidden information before the deal drives out quality.","src":"Session 7 vocabulary guide"},{"id":"m1-01","s":1,"type":"mc","term":"Opportunity Cost","q":"A city council votes to spend $2 million on a new skate park instead of resurfacing roads. In economic terms, the roads are the project's:","opts":["sunk cost","opportunity cost","marginal cost","implicit revenue"],"a":1,"why":"Opportunity cost is the best alternative given up. The roads were the next-best use of the $2 million.","src":"Practice item, RG p.6"},{"id":"m1-02","s":1,"type":"mc","term":"Positive vs Normative","q":"Which statement is normative rather than positive?","opts":["Raising the minimum wage to $20 would reduce teen employment.","Gasoline prices rose 8% last year.","The government ought to cap rent increases.","Most households spend more on housing than on food."],"a":2,"why":"“Ought to” signals a value judgment. The others can be tested against data.","src":"Practice item, RG p.7"},{"id":"m1-03","s":1,"type":"mc","term":"Marginal Thinking","q":"A student weighs whether to study one more hour. Economists say she should continue as long as:","opts":["the total benefit of studying exceeds its total cost","the marginal benefit of the hour exceeds its marginal cost","her grade is below an A","she has not yet studied as long as her classmates"],"a":1,"why":"Decisions at the margin compare the extra benefit and extra cost of one more unit.","src":"Practice item, RG p.8"},{"id":"m1-04","s":1,"type":"mc","term":"Economic Models","q":"Why do economists build simplified models that leave out many real-world details?","opts":["Because complete data are never available","Because simplification isolates the relationship being studied","Because models are only used for teaching","Because real economies are too small to measure"],"a":1,"why":"A model is a deliberate simplification that makes one causal link visible.","src":"Practice item, RG p.8"},{"id":"m1-05","s":1,"type":"mc","term":"Micro vs Macro","q":"Which question belongs to macroeconomics rather than microeconomics?","opts":["How a tariff changes the price of imported steel","Why a bakery hires a third baker","What determines the national unemployment rate","How a drought affects the price of almonds"],"a":2,"why":"Economy-wide aggregates like unemployment are macro; single markets and firms are micro.","src":"Practice item, RG p.9"},{"id":"m1-06","s":1,"type":"mc","term":"PPF","q":"A point inside an economy's production possibilities frontier shows:","opts":["an unattainable combination of goods","full and efficient use of resources","unemployed or misallocated resources","economic growth"],"a":2,"why":"Inside the frontier, the economy could produce more of both goods with the resources it has.","src":"Practice item, RG p.8"},{"id":"m1-07","s":1,"type":"mc","term":"Increasing Opportunity Cost","q":"A bowed-out production possibilities frontier reflects:","opts":["constant opportunity costs","increasing opportunity costs as resources are shifted","decreasing returns to scarcity","perfectly substitutable resources"],"a":1,"why":"Resources are specialized, so each extra unit of one good costs more of the other.","src":"Practice item, RG p.8"},{"id":"m1-08","s":1,"type":"mc","term":"Scarcity","q":"Scarcity exists because:","opts":["some goods are expensive","human wants exceed the resources available to satisfy them","governments restrict production","markets fail to clear"],"a":1,"why":"Scarcity is the gap between unlimited wants and limited resources, not a price level.","src":"Practice item, RG p.6"},{"id":"m1-09","s":1,"type":"mc","term":"Pareto Efficiency","q":"An outcome is Pareto efficient when:","opts":["income is distributed equally","no one can be made better off without making someone else worse off","total output is at its maximum","every market has a single price"],"a":1,"why":"Pareto efficiency is about the absence of unexploited gains, not fairness or output size.","src":"Practice item, RG p.9"},{"id":"m1-10","s":1,"type":"mc","term":"Implicit Cost","q":"A restaurant owner pays $4,000 rent and could have earned $5,000 working elsewhere. Her implicit cost this month is:","opts":["$4,000","$5,000","$9,000","$1,000"],"a":1,"why":"Implicit cost is the forgone alternative, the salary she gave up. Rent is explicit.","src":"Practice item, RG p.6"},{"id":"m1-11","s":1,"type":"mc","term":"Incentives","q":"Which is an example of the incentive principle?","opts":["Consumers buy less when the price rises","A worker who gets a raise feels wealthier","Firms with higher profits hire fewer workers","A tax cut reduces government debt"],"a":0,"why":"People respond predictably to changes in costs and benefits; higher price, less bought.","src":"Practice item, RG p.7"},{"id":"m1-12","s":1,"type":"mc","term":"Rational Choice","q":"Rational self-interest in economics means that people:","opts":["always act selfishly","compare costs and benefits before choosing","never make mistakes","care only about money"],"a":1,"why":"Rational means weighing costs against benefits, whatever the person values.","src":"Practice item, RG p.7"},{"id":"m1-13","s":1,"type":"mc","term":"Invisible Hand","q":"The invisible hand refers to:","opts":["government regulators correcting markets","self-interested exchange producing socially useful outcomes without central direction","central banks setting interest rates","charities filling gaps in markets"],"a":1,"why":"Adam Smith's phrase for how prices coordinate self-interested buyers and sellers.","src":"Practice item, RG p.9"},{"id":"m1-14","s":1,"type":"mc","term":"Sunk Cost","q":"A sunk cost should be ignored in a decision because:","opts":["it is usually small","it cannot be recovered regardless of the choice made","it was paid by someone else","it is an implicit cost"],"a":1,"why":"Only costs and benefits that change with the decision matter at the margin.","src":"Practice item, RG p.8"},{"id":"m1-15","s":1,"type":"mc","term":"PPF Shift","q":"Economic growth is shown on a production possibilities diagram as:","opts":["a movement from inside the curve to the curve","an outward shift of the entire curve","a movement along the curve","a steeper slope"],"a":1,"why":"Growth expands what the economy can produce; the whole frontier moves out.","src":"Practice item, RG p.8"},{"id":"m2-01","s":2,"type":"mc","term":"Tastes & Preferences","q":"A news report says eating blueberries improves memory. In the market for blueberries this causes:","opts":["a movement along the demand curve","a rightward shift of demand","a rightward shift of supply","a movement along the supply curve"],"a":1,"why":"Tastes are a demand shifter. More bought at every price.","src":"Practice item, RG p.12"},{"id":"m2-02","s":2,"type":"mc","term":"Substitutes","q":"The price of coffee rises and consumers buy more tea. Coffee and tea are:","opts":["complements","substitutes","inferior goods","normal goods"],"a":1,"why":"A price rise in one raises demand for the other; that is the definition of substitutes.","src":"Practice item, RG p.13"},{"id":"m2-03","s":2,"type":"mc","term":"Inferior Good","q":"Consumer incomes fall during a recession and sales of store-brand cereal rise. Store-brand cereal is a(n):","opts":["normal good","inferior good","luxury good","complement"],"a":1,"why":"Demand rises when income falls; inferior good.","src":"Practice item, RG p.13"},{"id":"m2-04","s":2,"type":"mc","term":"Input Prices","q":"Which event shifts the supply curve for wheat to the left?","opts":["A rise in the price of wheat","A new high-yield seed","A drought in the growing region","Lower demand for bread"],"a":2,"why":"A drought raises the cost of producing each bushel; less supplied at every price.","src":"Practice item, RG p.15"},{"id":"m2-05","s":2,"type":"mc","term":"Seller Expectations","q":"Sellers expect the price of lumber to be higher next month. This month, supply:","opts":["shifts right","shifts left","is unchanged; expectations affect only demand","moves along the curve"],"a":1,"why":"Sellers hold inventory to sell later, reducing current supply.","src":"Practice item, RG p.15"},{"id":"m2-06","s":2,"type":"mc","term":"Ceteris Paribus","q":"The law of demand holds other things constant. If both the price of a good and consumer incomes rise at the same time, quantity demanded:","opts":["must fall","must rise","cannot be determined without more information","stays the same"],"a":2,"why":"Price pushes quantity down the curve; income shifts the curve out. The net effect depends on magnitudes.","src":"Practice item, RG p.12"},{"id":"m2-07","s":2,"type":"mc","term":"Market Demand","q":"A market demand curve is found by:","opts":["averaging individual demand curves","adding individual quantities demanded at each price","adding individual prices at each quantity","multiplying price by quantity"],"a":1,"why":"Horizontal summation: at each price, add up what every buyer would purchase.","src":"Practice item, RG p.12"},{"id":"m2-08","s":2,"type":"mc","term":"Input Prices","q":"A rise in the wages of auto workers would:","opts":["shift the demand for cars left","shift the supply of cars left","move along the supply of cars","shift the supply of cars right"],"a":1,"why":"Input prices are a supply shifter. Higher costs mean less supplied at every price.","src":"Practice item, RG p.15"},{"id":"m2-09","s":2,"type":"mc","term":"Complements","q":"The price of smartphones falls and demand for phone cases rises. Phones and cases are:","opts":["substitutes","complements","inferior goods","unrelated goods"],"a":1,"why":"Price down in one raises demand for the other; complements are used together.","src":"Practice item, RG p.13"},{"id":"m2-10","s":2,"type":"mc","term":"Shift vs Movement","q":"Which of the following does NOT shift the demand curve for pizza?","opts":["A change in the price of pizza","A change in the price of burgers","A change in the number of consumers","A change in consumer incomes"],"a":0,"why":"Own price moves you along the curve; everything else listed shifts it.","src":"Practice item, RG p.12"},{"id":"m2-11","s":2,"type":"mc","term":"Number of Sellers","q":"More firms enter the market for electric scooters. The supply curve:","opts":["shifts left","shifts right","becomes vertical","does not change; only demand shifts"],"a":1,"why":"Number of sellers is a supply shifter.","src":"Practice item, RG p.15"},{"id":"m2-12","s":2,"type":"mc","term":"Law of Supply","q":"The law of supply says that, other things equal, a higher price:","opts":["shifts supply right","raises the quantity supplied","lowers the quantity supplied","has no effect on sellers"],"a":1,"why":"Higher price, higher quantity supplied, a movement along the curve.","src":"Practice item, RG p.14"},{"id":"m2-13","s":2,"type":"mc","term":"Buyer Expectations","q":"Consumers expect gasoline prices to rise next week. This week, demand for gasoline:","opts":["shifts right","shifts left","is unaffected","moves down along the curve"],"a":0,"why":"Buyers fill up now before the increase, raising current demand.","src":"Practice item, RG p.13"},{"id":"m2-14","s":2,"type":"mc","term":"Quantity Demanded","q":"Quantity demanded is best defined as:","opts":["the amount consumers want at any price","the amount consumers are willing and able to buy at a specific price","the amount actually sold","the amount producers offer"],"a":1,"why":"A specific point on the demand curve, at one price.","src":"Practice item, RG p.12"},{"id":"m2-15","s":2,"type":"mc","term":"Technology & Supply","q":"A technological improvement in solar panel manufacturing:","opts":["shifts demand right","shifts supply right","moves along the supply curve","shifts supply left"],"a":1,"why":"Technology lowers production cost; more supplied at every price.","src":"Practice item, RG p.15"},{"id":"m3-01","s":3,"type":"mc","term":"Surplus","q":"At a price of $12, sellers offer 800 units and buyers want 500. The market has a:","opts":["shortage of 300","surplus of 300","surplus of 800","shortage of 500"],"a":1,"why":"Quantity supplied exceeds quantity demanded by 300; price is above equilibrium.","src":"Practice item, RG p.17"},{"id":"m3-02","s":3,"type":"mc","term":"Market Adjustment","q":"When a market has a shortage, the price tends to:","opts":["fall as sellers compete","rise as buyers compete for scarce units","stay fixed","fall as buyers leave"],"a":1,"why":"Buyers bid up the price until quantity demanded falls to meet quantity supplied.","src":"Practice item, RG p.17"},{"id":"m3-03","s":3,"type":"mc","term":"Demand Shift Effects","q":"Demand for avocados rises while supply is unchanged. Equilibrium price and quantity:","opts":["both rise","both fall","price rises, quantity falls","price falls, quantity rises"],"a":0,"why":"Rightward demand shift along a fixed supply curve raises both.","src":"Practice item, RG p.18"},{"id":"m3-04","s":3,"type":"mc","term":"Supply Shift Effects","q":"A new fertilizer raises strawberry yields while demand is unchanged. Equilibrium:","opts":["price rises, quantity rises","price falls, quantity rises","price falls, quantity falls","price rises, quantity falls"],"a":1,"why":"Supply shifts right: lower price, higher quantity.","src":"Practice item, RG p.18"},{"id":"m3-05","s":3,"type":"mc","term":"Double Shift","q":"Demand and supply both increase. Which outcome is certain?","opts":["Price rises","Price falls","Quantity rises","Quantity falls"],"a":2,"why":"Both shifts push quantity up; price depends on which shift is larger.","src":"Practice item, RG p.18"},{"id":"m3-06","s":3,"type":"mc","term":"Consumer Surplus","q":"Consumer surplus is:","opts":["the amount consumers spend","the difference between willingness to pay and the price paid","the profit of sellers","the amount left unsold"],"a":1,"why":"The area below the demand curve and above the price.","src":"Practice item, RG p.20"},{"id":"m3-07","s":3,"type":"mc","term":"Consumer Surplus","q":"Four buyers value a concert ticket at $90, $70, $50, and $30. The price is $45. Total consumer surplus is:","opts":["$240","$75","$105","$60"],"a":1,"why":"Only the three buyers above $45 purchase: (90-45)+(70-45)+(50-45)=45+25+5=75.","src":"Practice item, RG p.20"},{"id":"m3-08","s":3,"type":"mc","term":"Producer Surplus","q":"Producer surplus is the area:","opts":["above the demand curve","below the supply curve","above the supply curve and below the price","between demand and supply"],"a":2,"why":"Price received minus the seller's cost, summed over units sold.","src":"Practice item, RG p.21"},{"id":"m3-09","s":3,"type":"mc","term":"Total Surplus","q":"Why does total surplus peak at the competitive equilibrium?","opts":["Because price equals zero","Because every trade whose buyer value exceeds seller cost takes place, and no others","Because government sets the price","Because sellers earn the most profit"],"a":1,"why":"Equilibrium includes exactly the mutually beneficial trades.","src":"Practice item, RG p.22"},{"id":"m3-10","s":3,"type":"mc","term":"Marginal Cost","q":"The height of the supply curve at any quantity represents:","opts":["the market price","the seller's marginal cost of that unit","consumer willingness to pay","total revenue"],"a":1,"why":"Supply traces marginal cost; a seller needs at least that price to supply the unit.","src":"Practice item, RG p.21"},{"id":"m3-11","s":3,"type":"mc","term":"Consumer Surplus","q":"The price of a good falls. Holding demand fixed, consumer surplus:","opts":["falls","rises","is unchanged","becomes negative"],"a":1,"why":"Existing buyers pay less and new buyers enter; the triangle grows.","src":"Practice item, RG p.20"},{"id":"m3-12","s":3,"type":"mc","term":"Disequilibrium","q":"A market is in disequilibrium when:","opts":["price equals marginal cost","quantity demanded differs from quantity supplied","supply equals demand","consumer surplus is zero"],"a":1,"why":"Either a shortage or a surplus exists until price adjusts.","src":"Practice item, RG p.17"},{"id":"m3-13","s":3,"type":"mc","term":"Double Shift","q":"Supply decreases and demand decreases. Which is certain?","opts":["Price rises","Price falls","Quantity falls","Quantity rises"],"a":2,"why":"Both shifts reduce quantity; price direction depends on relative size.","src":"Practice item, RG p.18"},{"id":"m3-14","s":3,"type":"mc","term":"Market Clearing","q":"At the equilibrium price, the market is said to clear because:","opts":["all sellers earn a profit","every unit offered finds a buyer and every buyer finds a unit","the government approves the price","inventories reach zero forever"],"a":1,"why":"No shortage, no surplus; quantity demanded equals quantity supplied.","src":"Practice item, RG p.17"},{"id":"m3-15","s":3,"type":"mc","term":"Producer Surplus","q":"If a seller's cost for a unit is $8 and the market price is $13, the producer surplus on that unit is:","opts":["$8","$13","$5","$21"],"a":2,"why":"Price received minus cost: 13 - 8 = 5.","src":"Practice item, RG p.21"},{"id":"m4-10","s":4,"type":"mc","term":"Total Revenue","q":"Demand for a good is inelastic. A seller who raises the price will see total revenue:","opts":["fall","rise","stay the same","fall to zero"],"a":1,"why":"Quantity falls proportionally less than price rises, so revenue climbs.","src":"Practice item, RG p.25"},{"id":"m4-11","s":4,"type":"mc","term":"Substitutes & Elasticity","q":"Which good most likely has the most elastic demand?","opts":["Electricity","Insulin","A particular brand of bottled water","Gasoline over one week"],"a":2,"why":"Many close substitutes make demand elastic.","src":"Practice item, RG p.25"},{"id":"m4-12","s":4,"type":"mc","term":"Midpoint Method","q":"Using the midpoint method, a price change from $8 to $12 is a:","opts":["50% increase","40% increase","33% increase","25% increase"],"a":1,"why":"4 divided by the midpoint 10 = 40%. Dividing by the start gives 50%, the trap.","src":"Practice item, RG p.25"},{"id":"m4-13","s":4,"type":"mc","term":"Price Elasticity","q":"Price elasticity of demand is 2.0. A 5% price cut raises quantity demanded by:","opts":["2.5%","5%","10%","20%"],"a":2,"why":"Elasticity times percent price change: 2 x 5% = 10%.","src":"Practice item, RG p.25"},{"id":"m4-14","s":4,"type":"mc","term":"Perfectly Elastic","q":"A perfectly elastic demand curve is:","opts":["vertical","horizontal","downward sloping","upward sloping"],"a":1,"why":"Any price above the line and quantity demanded falls to zero.","src":"Practice item, RG p.26"},{"id":"m4-15","s":4,"type":"mc","term":"Time Horizon","q":"Over longer time horizons, demand for most goods becomes:","opts":["less elastic","more elastic","perfectly inelastic","unit elastic"],"a":1,"why":"Buyers find substitutes and adjust habits given time.","src":"Practice item, RG p.26"},{"id":"m4-16","s":4,"type":"mc","term":"Elasticity of Supply","q":"The supply of tickets to a sold-out stadium on game night is:","opts":["perfectly elastic","highly inelastic","unit elastic","undefined"],"a":1,"why":"Seats are fixed; quantity cannot respond to price in the short run.","src":"Practice item, RG p.27"},{"id":"m4-17","s":4,"type":"mc","term":"Unit Elastic","q":"Total revenue is unchanged when price rises. Demand is:","opts":["elastic","inelastic","unit elastic","perfectly elastic"],"a":2,"why":"Percent change in quantity exactly offsets percent change in price.","src":"Practice item, RG p.25"},{"id":"m4-18","s":4,"type":"mc","term":"Income Elasticity","q":"Income elasticity of demand for a good is negative. The good is:","opts":["a luxury","a necessity","an inferior good","a complement"],"a":2,"why":"Demand falls as income rises.","src":"Practice item, RG p.26"},{"id":"m4-19","s":4,"type":"mc","term":"Budget Share","q":"A good that takes a large share of a household's budget tends to have:","opts":["more elastic demand","less elastic demand","zero elasticity","infinite elasticity"],"a":0,"why":"Buyers notice and respond to price changes on big-ticket items.","src":"Practice item, RG p.26"},{"id":"m5-11","s":5,"type":"mc","term":"Shortage from Ceiling","q":"A rent ceiling is set below the equilibrium rent. The most likely result is:","opts":["a surplus of apartments","a shortage of apartments","no change in the market","higher-quality housing"],"a":1,"why":"At the lower price, quantity demanded exceeds quantity supplied.","src":"Practice item, RG p.32"},{"id":"m5-12","s":5,"type":"mc","term":"Minimum Wage","q":"A minimum wage set above the equilibrium wage creates:","opts":["a shortage of workers","a surplus of workers","more jobs","no effect on employment"],"a":1,"why":"Price floor above equilibrium: quantity of labor supplied exceeds quantity demanded.","src":"Practice item, RG p.33"},{"id":"m5-13","s":5,"type":"mc","term":"Tax Shifts Supply","q":"A $2 tax is placed on sellers of a good. The supply curve:","opts":["shifts down by $2","shifts up by $2","is unchanged","shifts right"],"a":1,"why":"Sellers need $2 more at every quantity to cover the tax.","src":"Practice item, RG p.33"},{"id":"m5-14","s":5,"type":"mc","term":"Burden Rule","q":"Who bears more of a tax when demand is less elastic than supply?","opts":["Sellers","Buyers","Government","The burden is always equal"],"a":1,"why":"The side with fewer alternatives absorbs more of the price change.","src":"Practice item, RG p.34"},{"id":"m5-15","s":5,"type":"mc","term":"Consumer Burden","q":"Before a tax, price is $10. After a $3 tax, buyers pay $12 and sellers receive $9. The buyers' share of the tax is:","opts":["$3","$2","$1","$12"],"a":1,"why":"Buyers' price rose from $10 to $12. Subtract from the original price, not from the tax.","src":"Practice item, RG p.34"},{"id":"m5-16","s":5,"type":"mc","term":"Deadweight Loss","q":"Deadweight loss from a tax represents:","opts":["revenue collected by the government","the value of trades that no longer occur","the burden on sellers","the burden on buyers"],"a":1,"why":"Mutually beneficial trades blocked by the wedge; value nobody receives.","src":"Practice item, RG p.34"},{"id":"m5-17","s":5,"type":"mc","term":"Price Ceiling","q":"A price ceiling set above the equilibrium price:","opts":["creates a shortage","creates a surplus","has no effect","raises the price"],"a":2,"why":"A non-binding ceiling leaves the market at equilibrium.","src":"Practice item, RG p.32"},{"id":"m5-18","s":5,"type":"mc","term":"Tax Revenue","q":"Tax revenue equals:","opts":["the tax per unit times the pre-tax quantity","the tax per unit times the post-tax quantity","the deadweight loss","the buyers' burden"],"a":1,"why":"Only units actually sold after the tax generate revenue.","src":"Practice item, RG p.34"},{"id":"m5-19","s":5,"type":"mc","term":"Tax Incidence","q":"When supply is perfectly inelastic, a tax is borne:","opts":["entirely by buyers","entirely by sellers","equally","by neither"],"a":1,"why":"Sellers cannot reduce quantity, so the whole tax comes out of their price.","src":"Practice item, RG p.34"},{"id":"m5-20","s":5,"type":"mc","term":"Price Floor Surplus","q":"A binding price floor on milk leads to:","opts":["a shortage and black markets","a surplus the government may have to buy","lower prices for consumers","more consumption"],"a":1,"why":"Quantity supplied exceeds quantity demanded at the floor.","src":"Practice item, RG p.33"},{"id":"m6-10","s":6,"type":"mc","term":"Profit Maximization","q":"A perfectly competitive firm maximizes profit by producing where:","opts":["price is highest","marginal revenue equals marginal cost","average cost is lowest","total revenue is highest"],"a":1,"why":"Past MR = MC, each additional unit costs more than it brings in.","src":"Practice item, RG p.42"},{"id":"m6-11","s":6,"type":"mc","term":"Monopoly MR","q":"For a monopolist, marginal revenue is less than price because:","opts":["costs are rising","it must lower the price on all units to sell one more","demand is perfectly elastic","it faces no competition"],"a":1,"why":"Downward-sloping demand means the price cut applies to every unit.","src":"Practice item, RG p.48"},{"id":"m6-12","s":6,"type":"mc","term":"Monopolistic Competition","q":"Which market structure has many firms selling slightly differentiated products?","opts":["Perfect competition","Monopoly","Oligopoly","Monopolistic competition"],"a":3,"why":"Restaurants and clothing brands: many sellers, each with some price control.","src":"Practice item, RG p.52"},{"id":"m6-13","s":6,"type":"mc","term":"Natural Monopoly","q":"A natural monopoly exists when:","opts":["the government grants a patent","one firm can serve the market at lower average cost than two or more","the product has no substitutes","barriers to entry are legal"],"a":1,"why":"Large fixed costs and falling average cost favor a single provider.","src":"Practice item, RG p.46"},{"id":"m6-14","s":6,"type":"mc","term":"Economic Profit","q":"Accounting profit minus implicit costs equals:","opts":["total revenue","economic profit","marginal profit","normal cost"],"a":1,"why":"Economic profit subtracts both explicit and implicit costs.","src":"Practice item, RG p.40"},{"id":"m6-15","s":6,"type":"mc","term":"Cartel Instability","q":"Firms in a cartel have an incentive to:","opts":["raise prices above the agreed level","cheat by producing more than their quota","exit the industry","merge into one firm"],"a":1,"why":"Each member gains by selling extra at the high cartel price, which undermines the cartel.","src":"Practice item, RG p.54"},{"id":"m6-16","s":6,"type":"mc","term":"Price Discrimination","q":"Price discrimination requires that a seller:","opts":["face perfectly elastic demand","be able to separate buyers and prevent resale","have zero marginal cost","be regulated"],"a":1,"why":"Without separation and no resale, low-price buyers would resell to high-price buyers.","src":"Practice item, RG p.50"},{"id":"m6-17","s":6,"type":"mc","term":"Zero Economic Profit","q":"In the long run, firms in perfect competition earn:","opts":["positive economic profit","zero economic profit","negative economic profit","monopoly profit"],"a":1,"why":"Free entry drives price down to minimum average cost.","src":"Practice item, RG p.44"},{"id":"m6-18","s":6,"type":"mc","term":"Monopoly vs Competition","q":"Compared to perfect competition, a monopoly produces:","opts":["more output at a lower price","less output at a higher price","the same output at a higher price","more output at a higher price"],"a":1,"why":"Restricting output raises price; the lost trades are deadweight loss.","src":"Practice item, RG p.49"},{"id":"m6-19","s":6,"type":"mc","term":"Creative Destruction","q":"Schumpeter's creative destruction describes:","opts":["cartels collapsing from cheating","innovation that displaces established firms and monopolies","recessions destroying capital","government breaking up trusts"],"a":1,"why":"New technologies and products replace old ones; monopoly profit funds the next wave.","src":"Practice item, RG p.51"},{"id":"m7-11","s":7,"type":"mc","term":"Negative Externality","q":"A paper mill dumps waste into a river used by downstream fishermen. The mill's production creates a:","opts":["positive externality","negative externality","public good","common resource"],"a":1,"why":"Costs fall on third parties who are not part of the transaction.","src":"Practice item, RG p.56"},{"id":"m7-12","s":7,"type":"mc","term":"Positive Externality","q":"With a positive externality such as vaccination, the free market produces:","opts":["too much","too little","the efficient amount","none"],"a":1,"why":"Buyers ignore the benefit to others, so marginal social benefit exceeds private benefit.","src":"Practice item, RG p.56"},{"id":"m7-13","s":7,"type":"mc","term":"Pigouvian Tax","q":"A corrective (Pigouvian) tax on pollution is set equal to:","opts":["the firm's total cost","the external cost per unit","the firm's profit","average revenue"],"a":1,"why":"It makes private cost equal social cost, internalizing the externality.","src":"Practice item, RG p.57"},{"id":"m7-14","s":7,"type":"mc","term":"Public Good","q":"National defense is a public good because it is:","opts":["rival and excludable","non-rival and non-excludable","provided by the government","expensive"],"a":1,"why":"One person's protection does not reduce another's, and no one can be excluded.","src":"Practice item, RG p.58"},{"id":"m7-15","s":7,"type":"mc","term":"Free Rider","q":"The free-rider problem arises because:","opts":["public goods are rival","people can enjoy a public good without paying for it","taxes are too low","markets are competitive"],"a":1,"why":"Non-excludability means nobody has to pay, so private provision collapses.","src":"Practice item, RG p.58"},{"id":"m7-16","s":7,"type":"mc","term":"Common Resource","q":"A common resource differs from a public good in that it is:","opts":["excludable","rival","provided privately","always free"],"a":1,"why":"Fish in the ocean: one catch reduces what is left for others, but nobody can be excluded.","src":"Practice item, RG p.59"},{"id":"m7-17","s":7,"type":"mc","term":"Tragedy of the Commons","q":"The tragedy of the commons occurs because:","opts":["users bear the full cost of their use","each user ignores the cost imposed on others","the resource is excludable","government owns the resource"],"a":1,"why":"Private incentives lead to overuse of a shared, non-excludable resource.","src":"Practice item, RG p.59"},{"id":"m7-18","s":7,"type":"mc","term":"Coase Theorem","q":"According to the Coase theorem, private parties can resolve an externality on their own if:","opts":["the government subsidizes them","property rights are clear and bargaining costs are low","there are many affected parties","the externality is positive"],"a":1,"why":"With low transaction costs, the parties negotiate to the efficient outcome.","src":"Practice item, RG p.57"},{"id":"m7-19","s":7,"type":"mc","term":"Adverse Selection","q":"Adverse selection in the used-car market means:","opts":["buyers pay too little","sellers of good cars leave because buyers cannot tell quality","dealers collude","prices are regulated"],"a":1,"why":"Hidden information before the sale drives quality out of the market.","src":"Practice item, RG p.59"},{"id":"m7-20","s":7,"type":"mc","term":"Moral Hazard","q":"Moral hazard refers to:","opts":["changing behavior after being insured or protected from risk","hiding information before a contract","charging different prices to different buyers","cheating in a cartel"],"a":0,"why":"Protection from consequences changes incentives after the deal.","src":"Practice item, RG p.59"},{"id":"m8-01","s":8,"type":"mc","term":"What Counts in GDP","q":"Which transaction is counted in this year's GDP?","opts":["A used car sold between neighbors","Shares of stock purchased on an exchange","A new house built and sold this year","A Social Security payment"],"a":2,"why":"GDP counts newly produced final goods and services. Used goods, financial assets, and transfers are excluded.","src":"Practice item, RG p.62"},{"id":"m8-02","s":8,"type":"mc","term":"Value Added","q":"A bakery buys flour for $2 and sells bread for $5. The bakery's value added is:","opts":["$2","$5","$3","$7"],"a":2,"why":"Value added is sales minus intermediate inputs; counting the flour twice would double count.","src":"Practice item, RG p.62"},{"id":"m8-03","s":8,"type":"mc","term":"Real vs Nominal GDP","q":"Nominal GDP rises 6% while the price level rises 4%. Real GDP grew about:","opts":["10%","6%","2%","4%"],"a":2,"why":"Real growth is roughly nominal growth minus inflation.","src":"Practice item, RG p.64"},{"id":"m8-04","s":8,"type":"mc","term":"GDP Deflator","q":"The GDP deflator is:","opts":["nominal GDP divided by real GDP, times 100","real GDP divided by nominal GDP","the inflation rate","the unemployment rate"],"a":0,"why":"It measures the price level of everything in GDP relative to the base year.","src":"Practice item, RG p.64"},{"id":"m8-05","s":8,"type":"mc","term":"Investment in GDP","q":"A firm builds a new warehouse. In GDP accounting this is:","opts":["consumption","investment","government purchases","net exports"],"a":1,"why":"Business spending on new capital goods is investment.","src":"Practice item, RG p.63"},{"id":"m8-06","s":8,"type":"mc","term":"Nonmarket Production","q":"Which is NOT included in GDP?","opts":["A haircut","Household production such as cooking your own dinner","A new textbook","A restaurant meal"],"a":1,"why":"Nonmarket activity is not measured.","src":"Practice item, RG p.62"},{"id":"m8-07","s":8,"type":"mc","term":"CPI","q":"The CPI measures:","opts":["the price of all goods produced domestically","the cost of a fixed basket of goods bought by a typical consumer","the price of exports","producer costs"],"a":1,"why":"CPI tracks a consumer basket; the deflator tracks all of GDP.","src":"Practice item, RG p.68"},{"id":"m8-08","s":8,"type":"mc","term":"Unexpected Inflation","q":"Unexpected inflation tends to hurt:","opts":["borrowers with fixed-rate loans","lenders who receive fixed payments","people with wages indexed to inflation","firms with rising prices"],"a":1,"why":"Fixed payments buy less; wealth transfers from lenders to borrowers.","src":"Practice item, RG p.69"},{"id":"m8-09","s":8,"type":"mc","term":"GDP per Capita","q":"A country's standard of living is best measured by:","opts":["total GDP","GDP per capita","the inflation rate","exports"],"a":1,"why":"Output per person, not total output, reflects living standards.","src":"Practice item, RG p.65"},{"id":"m8-10","s":8,"type":"mc","term":"Labor Productivity","q":"The main driver of long-run growth in living standards is:","opts":["population growth","productivity growth","inflation","government spending"],"a":1,"why":"Output per worker determines income per person.","src":"Practice item, RG p.79"},{"id":"m8-11","s":8,"type":"mc","term":"Net Exports","q":"Imports are subtracted in the GDP formula because:","opts":["they are not consumed","they were already counted in C, I, or G but were not produced domestically","they are illegal","exports are more valuable"],"a":1,"why":"GDP measures domestic production; imported goods inside C, I, and G must be removed.","src":"Practice item, RG p.63"},{"id":"m8-12","s":8,"type":"mc","term":"Real vs Nominal GDP","q":"Real GDP is preferred to nominal GDP for comparing years because it:","opts":["includes imports","removes the effect of price changes","counts transfer payments","is larger"],"a":1,"why":"Real GDP values output at constant prices.","src":"Practice item, RG p.64"},{"id":"m8-13","s":8,"type":"mc","term":"Sources of Productivity","q":"Which of the following raises productivity?","opts":["More workers with the same tools","More capital per worker","Higher prices","Lower taxes on consumption"],"a":1,"why":"Physical capital, human capital, technology, and natural resources drive output per worker.","src":"Practice item, RG p.79"},{"id":"m8-14","s":8,"type":"mc","term":"Store of Value","q":"Hyperinflation most directly destroys money's role as a:","opts":["medium of exchange","store of value","unit of account","legal tender"],"a":1,"why":"Rapidly falling purchasing power makes holding money a losing proposition.","src":"Practice item, RG p.69"},{"id":"m8-15","s":8,"type":"mc","term":"Knowledge Spillovers","q":"Firms may underinvest in research because:","opts":["research is cheap","the benefits spill over to competitors who did not pay","governments ban it","consumers dislike new products"],"a":1,"why":"Knowledge is partly a public good; private return is below social return.","src":"Practice item, RG p.81"},{"id":"m9-18","s":9,"type":"mc","term":"Unemployed","q":"Which person is counted as unemployed?","opts":["A retiree who would work if offered a job","A full-time student not seeking work","A laid-off worker who applied for jobs last week","A parent who stopped looking for work"],"a":2,"why":"Unemployed means jobless and actively searching in the past month.","src":"Practice item, RG p.75"},{"id":"m9-19","s":9,"type":"mc","term":"Structural Unemployment","q":"Workers lose jobs when coal plants close and lack skills for new openings. This is:","opts":["frictional unemployment","structural unemployment","cyclical unemployment","seasonal unemployment"],"a":1,"why":"A skills mismatch that persists through recoveries.","src":"Practice item, RG p.76"},{"id":"m9-20","s":9,"type":"mc","term":"Natural Rate","q":"The natural rate of unemployment equals:","opts":["zero","frictional plus structural unemployment","cyclical unemployment","the labor force participation rate"],"a":1,"why":"What remains at full employment, when cyclical unemployment is zero.","src":"Practice item, RG p.76"},{"id":"m9-21","s":9,"type":"mc","term":"Participation Rate","q":"A town has 1,000 working-age adults, 600 employed, 50 unemployed. The labor force participation rate is:","opts":["60%","65%","5%","7.7%"],"a":1,"why":"Labor force 650 divided by 1,000 working-age population.","src":"Practice item, RG p.75"},{"id":"m9-22","s":9,"type":"mc","term":"Discouraged Worker","q":"Why can the unemployment rate fall during a recession without anyone finding work?","opts":["Prices fall","Discouraged workers stop searching and leave the labor force","Employers hire part-time","The population shrinks"],"a":1,"why":"Leaving the labor force removes people from both the numerator and denominator.","src":"Practice item, RG p.75"},{"id":"m9-23","s":9,"type":"mc","term":"Stock vs Bond","q":"A bondholder differs from a shareholder in that a bondholder:","opts":["owns part of the company","is a lender repaid before shareholders in bankruptcy","shares in profits","votes for the board"],"a":1,"why":"Bonds are debt; stocks are equity.","src":"Practice item, RG p.82"},{"id":"m9-24","s":9,"type":"mc","term":"Crowding Out","q":"Government runs a large deficit. In the market for saving and investment, the real interest rate:","opts":["falls, encouraging investment","rises, crowding out some private investment","is unchanged","becomes negative"],"a":1,"why":"Government borrowing adds to demand for saving.","src":"Practice item, RG p.85"},{"id":"m9-25","s":9,"type":"mc","term":"Saving Equals Investment","q":"National saving in a closed economy equals:","opts":["consumption","investment","government spending","exports"],"a":1,"why":"Income not consumed or spent by government is what funds investment.","src":"Practice item, RG p.84"},{"id":"m9-26","s":9,"type":"mc","term":"Banks as Intermediaries","q":"Where do banks get most of the money they lend?","opts":["The Federal Reserve","Depositors","The Treasury","Stock sales"],"a":1,"why":"Banks are intermediaries channeling deposits to borrowers.","src":"Practice item, RG p.83"},{"id":"m9-27","s":9,"type":"mc","term":"Real Interest Rate","q":"The nominal interest rate is 6% and inflation is 2%. The real rate is:","opts":["8%","4%","3%","12%"],"a":1,"why":"Nominal minus inflation.","src":"Practice item, RG p.85"},{"id":"m9-28","s":9,"type":"mc","term":"FDI vs Portfolio","q":"A U.S. company builds a factory in Mexico. This is:","opts":["portfolio investment","foreign direct investment","an export","a transfer payment"],"a":1,"why":"Buying or building a business to run abroad is FDI.","src":"Practice item, RG p.86"},{"id":"m9-29","s":9,"type":"mc","term":"Okun's Law","q":"Okun's law links:","opts":["inflation and unemployment","unemployment above the natural rate and output below potential","interest rates and investment","money supply and prices"],"a":1,"why":"Each point of extra unemployment goes with roughly 2% lost output.","src":"Practice item, RG p.77"},{"id":"m9-30","s":9,"type":"mc","term":"Frictional Unemployment","q":"A new graduate spends six weeks finding her first job. This is:","opts":["structural","cyclical","frictional","discouraged"],"a":2,"why":"Normal search time between jobs; present even in a healthy economy.","src":"Practice item, RG p.76"},{"id":"m10-22","s":10,"type":"mc","term":"Functions of Money","q":"Which is a function of money?","opts":["A hedge against inflation","A unit of account","A source of interest","A form of credit"],"a":1,"why":"Medium of exchange, unit of account, store of value.","src":"Practice item, RG p.88"},{"id":"m10-23","s":10,"type":"mc","term":"Money Multiplier","q":"The reserve ratio is 25%. The money multiplier is:","opts":["25","4","2.5","0.25"],"a":1,"why":"1 divided by 0.25.","src":"Practice item, RG p.91"},{"id":"m10-24","s":10,"type":"mc","term":"Fed Tools","q":"The Fed sells government bonds. The money supply:","opts":["rises","falls","is unchanged","doubles"],"a":1,"why":"Buyers pay with deposits, draining reserves from banks.","src":"Practice item, RG p.94"},{"id":"m10-25","s":10,"type":"mc","term":"Discount vs Fed Funds","q":"The federal funds rate is the rate:","opts":["the Fed charges banks","banks charge each other for overnight loans","on Treasury bonds","on mortgages"],"a":1,"why":"Bank-to-bank; the discount rate is what the Fed charges.","src":"Practice item, RG p.94"},{"id":"m10-26","s":10,"type":"mc","term":"Lender of Last Resort","q":"The Fed acts as lender of last resort to:","opts":["raise interest rates","stop a run at one sound bank from spreading","fund the Treasury","lend to consumers"],"a":1,"why":"Fractional reserves mean even sound banks cannot pay everyone at once.","src":"Practice item, RG p.92"},{"id":"m10-27","s":10,"type":"mc","term":"Quantity Equation","q":"With velocity stable, money growth of 7% and output growth of 3% imply inflation near:","opts":["10%","4%","3%","21%"],"a":1,"why":"Quantity equation: inflation is roughly money growth minus output growth.","src":"Practice item, RG p.96"},{"id":"m10-28","s":10,"type":"mc","term":"Wealth Effect","q":"Aggregate demand slopes downward partly because higher prices:","opts":["make domestic goods cheaper abroad","reduce the real value of money holdings","raise real wages","increase exports"],"a":1,"why":"The wealth effect: people feel poorer and spend less.","src":"Practice item, RG p.100"},{"id":"m10-29","s":10,"type":"mc","term":"Output Gap","q":"An inflationary gap exists when:","opts":["output is below potential","output is above potential","unemployment exceeds the natural rate","prices are falling"],"a":1,"why":"The economy runs beyond capacity and prices climb.","src":"Practice item, RG p.103"},{"id":"m10-30","s":10,"type":"mc","term":"Fiscal Policy","q":"To fight a recession, expansionary fiscal policy would:","opts":["raise taxes","cut government spending","increase government spending or cut taxes","sell bonds"],"a":2,"why":"Shifts aggregate demand right.","src":"Practice item, RG p.105"},{"id":"m10-31","s":10,"type":"mc","term":"Fiscal vs Monetary","q":"Which action is monetary, not fiscal, policy?","opts":["Raising income tax rates","Building new highways","Lowering the discount rate","Increasing tariffs"],"a":2,"why":"The Fed's tools are monetary; taxes, spending, and tariffs belong to Congress.","src":"Practice item, RG p.106"},{"id":"m10-32","s":10,"type":"mc","term":"Neutrality of Money","q":"In the long run, an increase in the money supply:","opts":["raises real output permanently","raises the price level proportionally","lowers the natural rate of unemployment","shifts LRAS right"],"a":1,"why":"Money is neutral in the long run.","src":"Practice item, RG p.97"},{"id":"m10-33","s":10,"type":"mc","term":"Stagflation","q":"A sharp rise in oil prices shifts:","opts":["aggregate demand right","short-run aggregate supply left","long-run aggregate supply right","the money supply"],"a":1,"why":"An economy-wide cost shock reduces short-run supply, causing stagflation.","src":"Practice item, RG p.102"},{"id":"m10-34","s":10,"type":"mc","term":"FOMC","q":"The FOMC includes:","opts":["only the seven governors","the seven governors plus five regional bank presidents","all twelve regional presidents","the Treasury Secretary"],"a":1,"why":"New York's president is always among the five.","src":"Practice item, RG p.93"},{"id":"m10-35","s":10,"type":"mc","term":"First Loan","q":"A $200 deposit at a 10% reserve ratio allows the bank to lend at most:","opts":["$20","$180","$200","$2,000"],"a":1,"why":"Keep $20 in reserve, lend the rest.","src":"Practice item, RG p.91"},{"id":"m11-19","s":11,"type":"mc","term":"Derived Demand","q":"Most trips are examples of derived demand because:","opts":["travelers enjoy the trip itself","the trip is a means to an activity at the destination","fares are set by governments","trips cannot be stored"],"a":1,"why":"Demand for travel comes from demand for what is at the other end.","src":"Practice item, RG p.113"},{"id":"m11-20","s":11,"type":"mc","term":"Four Trip Decisions","q":"A commuter switches from driving to the train. This is which trip decision?","opts":["Time","Destination","Mode","Route"],"a":2,"why":"How to travel is the mode decision.","src":"Practice item, RG p.115"},{"id":"m11-21","s":11,"type":"mc","term":"Agglomeration","q":"Why are cities more productive per worker than rural areas?","opts":["Higher taxes fund services","Economies of agglomeration from clustering firms and workers","Lower congestion","Cheaper land"],"a":1,"why":"Shared labor pools, nearby suppliers, and fast idea spread.","src":"Practice item, RG p.112"},{"id":"m11-22","s":11,"type":"mc","term":"Generalized Cost","q":"A bus fare is $3 and the ride takes 30 minutes. A rider valuing time at $20 per hour faces a generalized cost of:","opts":["$3","$10","$13","$23"],"a":2,"why":"$3 plus half an hour at $20 = $13.","src":"Practice item, RG p.116"},{"id":"m11-23","s":11,"type":"mc","term":"Internal vs External","q":"Which is an external cost of driving?","opts":["Gasoline","Parking fees","Delay imposed on other drivers","The driver's own time"],"a":2,"why":"Costs that fall on people outside the trip.","src":"Practice item, RG p.117"},{"id":"m11-24","s":11,"type":"mc","term":"Tested Percentages","q":"Drivers cover about what share of road costs through fuel taxes and tolls?","opts":["3%","25%","29%","50%"],"a":1,"why":"25% of road costs; under 3% of parking costs; 29% of total commute cost is external.","src":"Practice item, RG p.118"},{"id":"m11-25","s":11,"type":"mc","term":"Marginal Cost Pricing","q":"A free road is inefficient because:","opts":["nobody uses it","price is below marginal social cost, so it becomes congested","it generates no revenue","it is priced too high"],"a":1,"why":"Congestion rations what price does not.","src":"Practice item, RG p.119"},{"id":"m11-26","s":11,"type":"mc","term":"HOT Lanes","q":"HOT lanes adjust their tolls in real time in order to:","opts":["maximize revenue","keep traffic moving near a target speed","fill the lane to capacity","punish single drivers"],"a":1,"why":"Dynamic pricing to maintain flow.","src":"Practice item, RG p.120"},{"id":"m11-27","s":11,"type":"mc","term":"Ramsey Pricing","q":"Airlines charging business travelers more than vacationers is an example of:","opts":["congestion pricing","Ramsey pricing","marginal cost pricing","first-best pricing"],"a":1,"why":"Charge the least price-sensitive users the most to recover costs.","src":"Practice item, RG p.121"},{"id":"m11-28","s":11,"type":"mc","term":"First-Best Pricing","q":"First-best pricing is unrealistic because:","opts":["tolls are unpopular","it requires information no one has and perfectly competitive markets","it ignores external costs","it only applies to freight"],"a":1,"why":"Second-best pricing pursues the same goal within real limits.","src":"Practice item, RG p.120"},{"id":"m11-29","s":11,"type":"mc","term":"Congestion Pricing","q":"Manhattan's 2025 congestion pricing program:","opts":["charged all vehicles citywide","tolled vehicles entering below 60th Street, cutting traffic","was never implemented","applied only to trucks"],"a":1,"why":"About $9 at peak for cars; traffic fell and transit sped up.","src":"Practice item, RG p.120"},{"id":"m11-30","s":11,"type":"mc","term":"Cost Categories","q":"Which cost category varies most across transportation modes?","opts":["Operating costs","Capital costs","Fuel costs","Labor costs"],"a":1,"why":"Highways, rail lines, and airports are large fixed investments.","src":"Practice item, RG p.118"},{"id":"m11-31","s":11,"type":"mc","term":"Discrete Choice","q":"A discrete choice model predicts:","opts":["exactly which mode each traveler picks","the probability a traveler chooses each option","total freight volume","fuel prices"],"a":1,"why":"Scores on time, cost, and comfort become choice probabilities.","src":"Practice item, RG p.115"},{"id":"m11-32","s":11,"type":"mc","term":"Freight Demand","q":"E-commerce growth increased demand for:","opts":["long-haul rail","regional trucking and fulfillment centers","passenger air travel","pipelines"],"a":1,"why":"Many small, time-sensitive home deliveries.","src":"Practice item, RG p.114"},{"id":"m12-25","s":12,"type":"mc","term":"Economic vs Social Regulation","q":"Economic regulation in transportation focuses on:","opts":["safety standards","prices, profits, and entry","pollution limits","driver licensing"],"a":1,"why":"Social regulation covers health, safety, and the environment.","src":"Practice item, RG p.122"},{"id":"m12-26","s":12,"type":"mc","term":"Economies of Density","q":"Economies of density mean that:","opts":["denser cities have higher costs","cost per user falls as more traffic uses existing infrastructure","more roads reduce traffic","small operators are more efficient"],"a":1,"why":"This is why one dominant firm often ends up serving a transportation market.","src":"Practice item, RG p.122"},{"id":"m12-27","s":12,"type":"mc","term":"Historic Regulators","q":"The Interstate Commerce Commission regulated:","opts":["airlines until 1985","railroads and pipelines until 1995","highways","ports"],"a":1,"why":"CAB covered airlines and was abolished in 1985.","src":"Practice item, RG p.122"},{"id":"m12-28","s":12,"type":"mc","term":"Deregulation","q":"Deregulation of airlines, trucking, and rail began in the:","opts":["1950s","late 1970s","1990s","2010s"],"a":1,"why":"More competition and demand-set fares; the trade-off was safety and investment risk.","src":"Practice item, RG p.123"},{"id":"m12-29","s":12,"type":"mc","term":"NEPA","q":"The National Environmental Policy Act of 1969 requires:","opts":["fuel economy standards","federal projects to study environmental effects first","vehicle recalls","congestion tolls"],"a":1,"why":"NEPA mandates environmental review.","src":"Practice item, RG p.123"},{"id":"m12-30","s":12,"type":"mc","term":"Highway Trust Fund","q":"The Highway Trust Fund is financed mainly by:","opts":["income taxes","motor fuel and truck-related taxes","property taxes","transit fares"],"a":1,"why":"The trap answer is general income taxes.","src":"Practice item, RG p.124"},{"id":"m12-31","s":12,"type":"mc","term":"EVs and the Trust Fund","q":"Electric vehicles strain highway funding because they:","opts":["are heavier","pay little or no fuel tax","use more road space","need wider lanes"],"a":1,"why":"Less gasoline burned, less fuel tax collected.","src":"Practice item, RG p.124"},{"id":"m12-32","s":12,"type":"mc","term":"Project Delivery","q":"In design-build project delivery:","opts":["the agency designs, then bids out construction","one partner both designs and builds","a private investor funds the project","the state does all work in-house"],"a":1,"why":"Adopted to finish faster and attract private capital.","src":"Practice item, RG p.124"},{"id":"m12-33","s":12,"type":"mc","term":"Discount Rate","q":"A higher discount rate makes long-lived projects:","opts":["more attractive","less attractive, because distant benefits shrink","unaffected","shorter"],"a":1,"why":"Future dollars are worth less today at a higher rate.","src":"Practice item, RG p.125"},{"id":"m12-34","s":12,"type":"mc","term":"IRR and MARR","q":"A project passes if its internal rate of return exceeds:","opts":["zero","the discount rate and the minimum accepted rate of return","total costs","the inflation rate"],"a":1,"why":"IRR is the rate making NPV zero; it must beat the hurdle.","src":"Practice item, RG p.125"},{"id":"m12-35","s":12,"type":"mc","term":"Rule of Half","q":"Under the Rule of Half, new travelers drawn by a cheaper trip receive:","opts":["the full savings","half the savings on average","no benefit","double the savings"],"a":1,"why":"The first new traveler gains almost all, the last almost none.","src":"Practice item, RG p.126"},{"id":"m12-36","s":12,"type":"mc","term":"BCA vs EIA","q":"Which benefit does economic impact analysis miss that benefit-cost analysis captures?","opts":["Construction jobs","Business sales","Riders' time savings","Tax revenue"],"a":2,"why":"EIA follows money; BCA counts gains that never become money.","src":"Practice item, RG p.126"},{"id":"m12-37","s":12,"type":"mc","term":"Crash Costs","q":"Drivers bear roughly what share of crash-related costs?","opts":["25%","59%","90%","100%"],"a":1,"why":"The rest falls on society.","src":"Practice item, RG p.123"},{"id":"m12-38","s":12,"type":"mc","term":"CAFE","q":"Corporate Average Fuel Economy standards were created in:","opts":["1969","1970","1973","2005"],"a":2,"why":"A response to the oil crisis.","src":"Practice item, RG p.123"},{"id":"m13-01","s":13,"type":"mc","term":"Comparative Advantage","q":"Ana makes 4 cakes or 8 pies per day; Ben makes 2 cakes or 2 pies. Who has the comparative advantage in pies?","opts":["Ana","Ben","Both equally","Neither"],"a":0,"why":"Ana gives up half a cake per pie; Ben gives up a whole cake. Ana's opportunity cost is lower.","src":"Practice item, RG p.37"},{"id":"m13-02","s":13,"type":"mc","term":"Absolute Advantage","q":"Absolute advantage means:","opts":["lower opportunity cost","producing more output with the same inputs","exporting more than importing","having more resources"],"a":1,"why":"Productivity, not opportunity cost, defines absolute advantage.","src":"Practice item, RG p.36"},{"id":"m13-03","s":13,"type":"mc","term":"Comparative Advantage","q":"Gains from trade arise when countries specialize according to:","opts":["absolute advantage","comparative advantage","population size","currency strength"],"a":1,"why":"Each produces what it gives up least to make, then trades.","src":"Practice item, RG p.37"},{"id":"m13-04","s":13,"type":"mc","term":"Absolute vs Comparative","q":"A country that is better at producing everything than its trading partner:","opts":["cannot gain from trade","can still gain by specializing in its comparative advantage","should produce everything itself","should stop trading"],"a":1,"why":"Absolute advantage in all goods does not eliminate differences in opportunity cost.","src":"Practice item, RG p.38"},{"id":"m13-05","s":13,"type":"mc","term":"Tariff","q":"A tariff on imported steel most directly:","opts":["lowers the domestic price of steel","raises the domestic price and protects domestic producers","increases imports","reduces government revenue"],"a":1,"why":"A tax on imports raises price; consumers lose more than producers and government gain.","src":"Practice item, RG p.39"},{"id":"m13-06","s":13,"type":"mc","term":"Source of Gains from Trade","q":"If two people have identical opportunity costs:","opts":["trade is most beneficial","there are no gains from specialization and trade","the one with absolute advantage should do everything","prices will fall"],"a":1,"why":"Gains come from differences in opportunity cost.","src":"Practice item, RG p.38"},{"id":"m13-07","s":13,"type":"mc","term":"Terms of Trade","q":"Terms of trade that benefit both parties lie:","opts":["below both opportunity costs","between the two parties' opportunity costs","above both opportunity costs","at zero"],"a":1,"why":"Each side pays less than it would cost to make the good itself.","src":"Practice item, RG p.38"},{"id":"m13-08","s":13,"type":"mc","term":"Import Quota","q":"An import quota differs from a tariff in that a quota:","opts":["raises government revenue","limits the quantity imported directly","lowers domestic prices","has no effect on consumers"],"a":1,"why":"Both raise price; the quota's gains go to license holders instead of the treasury.","src":"Practice item, RG p.39"}];
const BOSSES=[{"id": "b-mid", "s": 4, "spell": "Divide by Starting Value", "type": "mc", "q": "Fare rises from $5.35 to $7.00. The Tome screams “31% increase!” The exam’s midpoint answer is:", "opts": ["31%", "27%", "24%", "15%"], "a": 1, "why": "$1.65 ÷ $6.175 (the midpoint) = 27%. The Tome divided by the start."}, {"id": "b-burden", "s": 5, "spell": "Subtract From the Tax", "type": "mc", "q": "Original $5.35, tax $1.60, riders now pay $6.10. The Tome hisses “consumer burden is $1.60 − $0.75 = $0.85!” The real consumer burden:", "opts": ["$0.85", "$1.60", "$0.75", "$6.10"], "a": 2, "why": "$6.10 − $5.35 = $0.75. Subtract from the ORIGINAL price."}, {"id": "b-shift", "s": 2, "spell": "Shift Everything", "type": "mc", "q": "The Tome casts a spell that raises the price of bus rides. What happens to the demand curve for bus rides?", "opts": ["Shifts left", "Shifts right", "Nothing; movement along it", "It disappears"], "a": 2, "why": "Own price never shifts the curve. Movement along."}, {"id": "b-legal", "s": 5, "spell": "Legal Payer", "type": "mc", "q": "The Tome declares: “The law makes the operator pay the $1.60, so riders pay $0!” Riders actually pay:", "opts": ["$0", "$1.60", "$0.75", "$0.85"], "a": 2, "why": "Incidence follows elasticity. Riders bear $0.75 through the higher fare."}, {"id": "b-rev", "s": 5, "spell": "Count the Dead Rides", "type": "mc", "q": "Tax $1.60; rides fall from 21,000 to 19,000. The Tome claims revenue is $33,600. Real daily tax revenue:", "opts": ["$33,600", "$30,400", "$3,200", "$1,600"], "a": 1, "why": "$1.60 × 19,000 (after-tax quantity) = $30,400."}, {"id": "b-implicit", "s": 1, "spell": "Forget the Forgone", "type": "mc", "q": "The Tome says a $9,000 degree that costs you a $14,000 job has an opportunity cost of $9,000. The real cost:", "opts": ["$9,000", "$14,000", "$23,000", "$5,000"], "a": 2, "why": "Explicit + implicit. $23,000."}, {"id": "b-mr", "s": 6, "spell": "Sell One More", "type": "mc", "q": "The monopolist Tome says “my marginal revenue equals my price, so I’ll keep selling!” For a monopolist, MR is:", "opts": ["Equal to price", "Above price", "Below price", "Zero"], "a": 2, "why": "Cutting price on every unit to sell one more pushes MR below price."}, {"id": "b-surplus", "s": 3, "spell": "Call It a Shortage", "type": "mc", "q": "Price is set ABOVE equilibrium. The Tome shrieks “shortage!” What actually happens?", "opts": ["A shortage; price rises", "A surplus; price falls", "Nothing; market clears", "Both at once"], "a": 1, "why": "Above equilibrium sellers offer more than buyers want. Surplus, and price falls."}, {"id": "b-social", "s": 7, "spell": "Subtract the Neighbors", "type": "mc", "q": "Private cost $5.35 a ride, external noise cost $0.80. The Tome says social cost is $4.55. Social cost is really:", "opts": ["$4.55", "$5.35", "$6.15", "$0.80"], "a": 2, "why": "Social cost = private + external = $6.15. Negative externality means the bigger number."}, {"id": "b-invest", "s": 8, "spell": "Buy the Stock", "type": "mc", "q": "The Tome buys $1 million of shares and declares “I is up a million!” In GDP terms that purchase counts as:", "opts": ["Investment (I)", "Consumption (C)", "Government (G)", "Nothing new was produced"], "a": 3, "why": "GDP investment is new capital goods. Buying existing shares produces nothing."}, {"id": "b-bench", "s": 9, "spell": "Print More Scot Bucks", "type": "mc", "q": "The Benchwarmer doubles the Scot Bucks in circulation and promises twice the dances. In the long run:", "opts": ["Twice as many dances", "Prices double, dances unchanged", "Half as many dances", "Interest rates fall forever"], "a": 1, "why": "Neutrality of money: price level doubles, real output does not move."}, {"id": "b-cashbox", "s": 10, "spell": "The First Loan", "type": "mc", "q": "Reserve ratio 20%. A $100 deposit arrives. The Cashbox says the money supply is still $100 after the first loan. It is actually:", "opts": ["$100", "$80", "$180", "$500"], "a": 2, "why": "The deposit still exists plus the $80 loan. $180."}, {"id": "b-dropoff", "s": 11, "spell": "Money Alone", "type": "mc", "q": "Bus $2.50 for 40 minutes, or drive for $6 in 15 minutes. You value time at $15/hr. The Drop-Off Line says the bus is cheaper. Generalized cost says:", "opts": ["Bus $2.50 vs car $6: bus wins", "Bus $12.50 vs car $9.75: car wins", "They are equal", "Cannot compare"], "a": 1, "why": "Bus $2.50 + $10 time = $12.50. Car $6 + $3.75 time = $9.75. Count time."}, {"id": "b-moocher", "s": 12, "spell": "Ride for Free", "type": "mc", "q": "The Moocher drives an EV, pays no fuel tax, and says “the roads are free.” Who pays for the road he uses?", "opts": ["Nobody; roads are free", "The Highway Trust Fund, fed by fuel and truck taxes others pay", "General income taxes", "The car dealer"], "a": 1, "why": "Fuel-tax funding; EVs ride on what gasoline drivers pay. That strain is the tested point."}];

// ---------- THE CORRIDOR CHAIN ----------
// The finale of the weekly raid: one corridor, one fare, seven linked questions.
// Each step hands a figure to the next through a {placeholder}, which always
// resolves to the TRUE value — drop a link and the rest still make sense, and
// nobody is marked wrong for faithfully carrying their own earlier error.
// The burdens are built to check each other: 0.75 + 0.85 = the full 1.60 wedge.
const CHAIN=[
{id:"ch-1",s:4,big:true,type:"num",term:"Midpoint Method",q:"The corridor fare rises from $5.35 to $7.00. Using the midpoint method, what is the percent change in price?",ans:26.7,tol:0.7,why:"$1.65 ÷ $6.175 ≈ 26.7%. Dividing by the $5.35 you started at gives 30.8% — the Tome's favourite trap.",src:"Corridor case • midpoint method",carry:"pctPrice",unit:"%",dec:1},
{id:"ch-2",s:4,big:true,type:"mc",term:"Total Revenue Test",q:"That fare rise is {pctPrice}. Corridor demand elasticity is about 0.68. What happens to total revenue?",opts:["It rises","It falls","It is unchanged","It cannot be determined"],a:0,why:"Inelastic demand (0.68 < 1) means quantity moves proportionally less than price, so price up means revenue up.",src:"Corridor case • total revenue test"},
{id:"ch-3",s:5,big:true,type:"num",term:"Tax Wedge",q:"Now the city adds a tax. Riders pay $6.10 and the operator keeps $4.50. How big is the wedge, in dollars?",ans:1.6,tol:0.001,why:"$6.10 − $4.50 = $1.60, and that gap goes to the city. After a tax there are two prices, not one.",src:"Corridor case • tax wedge",carry:"tax",unit:"$",dec:2},
{id:"ch-4",s:5,big:true,type:"num",term:"Consumer Burden",q:"The original fare was $5.35 and riders now pay $6.10. Of that {tax} tax, how much do riders bear, in dollars?",ans:0.75,tol:0.001,why:"$6.10 − $5.35 = $0.75. Measured from the ORIGINAL price, never subtracted out of the tax.",src:"Corridor case • consumer burden",carry:"consumerBurden",unit:"$",dec:2},
{id:"ch-5",s:5,big:true,type:"num",term:"Producer Burden",q:"Riders bear {consumerBurden} of the {tax} tax, and the operator now keeps $4.50 of the old $5.35. What is the producer burden, in dollars?",ans:0.85,tol:0.001,why:"$5.35 − $4.50 = $0.85. The two burdens always add to the full $1.60 — use that to check yourself.",src:"Corridor case • producer burden",carry:"producerBurden",unit:"$",dec:2},
{id:"ch-6",s:5,big:true,type:"num",term:"Tax Revenue",q:"Rides fall from 21,000 to 19,000 because of the tax. With the {tax} wedge, what does the city collect per day, in dollars?",ans:30400,tol:0,why:"$1.60 × 19,000 = $30,400. The quantity AFTER the tax — those 2,000 lost rides pay nothing.",src:"Corridor case • tax revenue",carry:"taxRevenue",unit:"$",dec:0},
{id:"ch-7",s:5,big:true,type:"num",term:"Deadweight Loss",q:"Those 2,000 rides a day stopped happening. With the {tax} wedge, what is the deadweight loss triangle worth per day, in dollars?",ans:1600,tol:0,why:"½ × 2,000 rides × $1.60 = $1,600 a day. The {taxRevenue} moves to the city, but this triangle is value nobody gets.",src:"Corridor case • deadweight loss",carry:"dwl",unit:"$",dec:0}
];
